  async exec(
    cmd: string,
    args: string[],
    signal?: AbortSignal,
  ): Promise<RedisCommandResult> {
    const c = cmd.toUpperCase();
    if (c === "BLPOP" || c === "BRPOP" ||
        c === "BZPOPMIN" || c === "BZPOPMAX") {
      const seconds = Number(args.at(-1));
      if (args.length < 2 || !Number.isFinite(seconds) || seconds < 0) {
        throw new Error("ERR invalid blocking pop timeout");
      }
      this.commandsProcessed++;
      const pop = c === "BLPOP" ? "LPOP" : c === "BRPOP" ? "RPOP" :
        c === "BZPOPMIN" ? "ZPOPMIN" : "ZPOPMAX";
      return this.waitForResult(
        (isActive) => this.runEmbeddedCommand(async () => {
          if (!isActive()) return null;
          for (const key of args.slice(0, -1)) {
            if (!isActive()) return null;
            this.touch(key);
            const value = this.dispatchSync(pop, [key]);
            if (value !== null && (!Array.isArray(value) || value.length > 0)) {
              this.recordAof(pop, [key]);
              queueMicrotask(() => this.emit("mutation"));
              this.maybeEvict();
              await this.commitEmbeddedAof();
              return [key, ...(Array.isArray(value) ? value : [value])];
            }
          }
          return null;
        }),
        seconds * 1000,
        signal,
      );
    }
    return this.runEmbeddedCommand(() => this.execNonBlocking(c, args));
  }

  private async execNonBlocking(
    c: string,
    args: string[],
  ): Promise<RedisCommandResult> {
    this.commandsProcessed++;
    // Record that the first-arg key was accessed (used by LRU eviction).
    // Multi-key commands (MGET, MSET, etc.) only touch the first key here;
    // that is sufficient as a write-recency heuristic.
    if (args[0] && c !== "__PDIM_MULTI_EXEC") this.touch(args[0]);

    let result: RedisCommandResult;
    switch (c) {
      case "__PDIM_MULTI_EXEC":
        result = await this.execMulti(args);
        break;
      // Lua scripting (async — must go through exec, not dispatchSync)
      case "EVAL":
        result = await this.cmdEval(args);
        break;
      case "EVALSHA":
        result = await this.cmdEvalSha(args);
        break;
      default:
        result = this.dispatchSync(c, args);
        // EVAL/EVALSHA writes are captured as inner redis.call() effects.
        this.recordAof(c, args);
        if (isAofMutation(c)) queueMicrotask(() => this.emit("mutation"));
    }

    this.maybeEvict();
    await this.commitEmbeddedAof();
    return result;
  }

  private async execMulti(args: string[]): Promise<RedisCommandResult> {
    if (args.length !== 1) {
      throw new Error("ERR invalid PDIM transaction payload");
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(args[0]!);
    } catch {
      throw new Error("ERR invalid PDIM transaction JSON");
    }
    if (!Array.isArray(parsed) ||
        !parsed.every((item) =>
          Array.isArray(item) &&
          item.length >= 1 &&
          typeof item[0] === "string" &&
          item.slice(1).every((value) => typeof value === "string"),
        )) {
      throw new Error("ERR invalid PDIM transaction command list");
    }

    const forbidden = new Set([
      "BLPOP", "BRPOP", "BZPOPMIN", "BZPOPMAX",
      "PUBLISH", "SUBSCRIBE", "UNSUBSCRIBE", "PSUBSCRIBE", "PUNSUBSCRIBE",
      "__PDIM_MULTI_EXEC",
    ]);
    const results: unknown[] = [];
    for (const queued of parsed as string[][]) {
      const [rawCommand, ...commandArgs] = queued;
      const command = rawCommand!.toUpperCase();
      try {
        if (forbidden.has(command)) {
          throw new Error(`ERR ${command} is not allowed inside a PDIM transaction`);
        }

        let value: RedisCommandResult;
        if (command === "EVAL") value = await this.cmdEval(commandArgs);
        else if (command === "EVALSHA") value = await this.cmdEvalSha(commandArgs);
        else value = this.dispatchSync(command, commandArgs);

        if (command !== "EVAL" && command !== "EVALSHA") {
          this.recordAof(command, commandArgs);
          if (isAofMutation(command)) queueMicrotask(() => this.emit("mutation"));
        }
        results.push([null, value]);
      } catch (cause) {
        const error = cause instanceof Error ? cause : new Error(String(cause));
        const code = (error as Error & { code?: unknown }).code;
        results.push([{
          name: error.name,
          message: error.message,
          ...(typeof code === "string" ? { code } : {}),
        }, null]);
      }
    }
    return results as RedisCommandResult;
  }

  private waitForResult(
    read: (isActive: () => boolean) =>
      RedisCommandResult | Promise<RedisCommandResult>,
    timeoutMs: number,
    signal?: AbortSignal,
  ): Promise<RedisCommandResult> {
    if (signal?.aborted) {
      return Promise.reject(
        signal.reason instanceof Error ? signal.reason : new Error("PDIM blocking command aborted"),
      );
    }
    return new Promise((resolve, reject) => {
      let timer: ReturnType<typeof setTimeout> | undefined;
      let settled = false;
      let checking = false;
      let rerunRequested = false;
      let timedOut = false;
      const cleanup = () => {
        if (settled) return;
        settled = true;
        if (timer) clearTimeout(timer);
        this.off("mutation", check);
        this.off("owner-close", close);
        signal?.removeEventListener("abort", abort);
      };
      const close = () => { cleanup(); reject(new Error("PDIM owner closed")); };
      const abort = () => {
        cleanup();
        reject(
          signal?.reason instanceof Error
            ? signal.reason
            : new Error("PDIM blocking command aborted"),
        );
      };
      const performCheck = () => {
        if (settled) return;
        if (checking) {
          rerunRequested = true;
          return;
        }
        checking = true;
        void Promise.resolve().then(() => read(() => !settled)).then((value) => {
          checking = false;
          if (settled) return;
          if (value !== null) {
            cleanup();
            resolve(value);
            return;
          }
          if (timedOut) {
            cleanup();
            resolve(null);
            return;
          }
          if (rerunRequested) {
            rerunRequested = false;
            performCheck();
          }
        }, (error: unknown) => {
          cleanup();
          reject(error);
        });
      };
      const check = () => performCheck();
      this.on("mutation", check);
      this.once("owner-close", close);
      signal?.addEventListener("abort", abort, { once: true });
      if (timeoutMs > 0) {
        timer = setTimeout(() => {
          timedOut = true;
          if (!checking) {
            cleanup();
            resolve(null);
          }
        }, timeoutMs);
      }
      // Subscribe before reading so a mutation cannot land in the gap between
      // the initial empty check and listener registration.
      check();
    });
  }

  // ============================================================================
  // SERVER COMMANDS
  // ============================================================================

  private cmdPing(args: string[]): string {
    return args[0] ?? "PONG";
  }

  private cmdFlushDb(): string {
    for (const t of this.timers.values()) clearTimeout(t);
    this.timers.clear();
    this.data.clear();
    this.dirty = true;
    this.invalidateKeyCount();
    return "OK";
  }

  private cmdDbSize(): number {
    let count = 0;
    for (const key of this.data.keys()) {
      if (!this.isExpired(key)) count++;
    }
    return count;
  }

  private cmdInfo(): string {
    const stats = this.getStats();
    return [
      `# Server`,
      `instance_id:${stats.instanceId}`,
      `instance_name:${stats.instanceName}`,
      `uptime_in_seconds:${stats.uptimeSeconds}`,
      ``,
      `# Stats`,
      `total_commands_processed:${stats.totalCommandsProcessed}`,
      ``,
      `# Keyspace`,
      `keys:${stats.keyCount}`,
      `persistence:${stats.persistenceEnabled}`,
      `last_saved_at:${stats.lastSavedAt ?? "never"}`,
    ].join("\r\n");
  }

  /** Debounce-cached key count — avoids an O(n) scan on every exec call. */
  private _cachedKeyCount: number | null = null;
  private _cachedKeyCountAt = 0;
  private static readonly KEY_COUNT_TTL_MS = 3_000; // recount at most once per 3 s

  /** Invalidate the cached key count whenever the data Map changes size. */
  private invalidateKeyCount(): void {
    this._cachedKeyCount = null;
  }

  getStats(): RedisInfoStats {
    const now = Date.now();
    if (
      this._cachedKeyCount === null ||
      now - this._cachedKeyCountAt > RedisStore.KEY_COUNT_TTL_MS
    ) {
      let count = 0;
      for (const key of this.data.keys()) {
        if (!this.isExpired(key)) count++;
      }
      this._cachedKeyCount = count;
      this._cachedKeyCountAt = now;
    }
    const count = this._cachedKeyCount;
    return {
      instanceId: this.instanceId,
      instanceName: this.instanceName,
      keyCount: count,
      totalCommandsProcessed: this.commandsProcessed,
      uptimeSeconds: Math.floor((Date.now() - this.startedAt) / 1000),
      createdAt: new Date(this.startedAt).toISOString(),
      lastSavedAt: this.lastSavedAt
        ? new Date(this.lastSavedAt).toISOString()
        : null,
      persistenceEnabled: true,
    };
  }

  // ============================================================================
  // STRING COMMANDS
  // ============================================================================

  private cmdSet(args: string[]): string | null {
    const [key, value, ...opts] = args;
    if (!key || value === undefined)
      throw new Error("ERR wrong number of arguments for 'set'");

    const upper = opts.map((o) => o.toUpperCase());
    let expiresAt: number | undefined;
    let nx = false;
    let xx = false;
    let get = false;
    let keepttl = false;

    for (let i = 0; i < upper.length; i++) {
      const opt = upper[i]!;
      if (opt === "EX") {
        expiresAt = Date.now() + Number(opts[i + 1]!) * 1000;
        i++;
      } else if (opt === "PX") {
        expiresAt = Date.now() + Number(opts[i + 1]!);
        i++;
      } else if (opt === "EXAT") {
        expiresAt = Number(opts[i + 1]!) * 1000;
        i++;
      } else if (opt === "PXAT") {
        expiresAt = Number(opts[i + 1]!);
        i++;
      } else if (opt === "NX") nx = true;
      else if (opt === "XX") xx = true;
      else if (opt === "GET") get = true;
      else if (opt === "KEEPTTL") keepttl = true;
    }

    const existing = this.isExpired(key) ? null : this.data.get(key);
    const prevValue = existing?.type === "string" ? existing.value : null;

    if (nx && existing) return get ? prevValue : null;
    if (xx && !existing) return get ? null : null;

    const prevExpiry = keepttl ? existing?.expiresAt : undefined;
    const finalExpiry = keepttl ? prevExpiry : expiresAt;

    this.clearExpiry(key);
    this.data.set(key, { type: "string", value, expiresAt: finalExpiry });
    if (finalExpiry) this.scheduleExpiry(key, finalExpiry - Date.now());
    this.dirty = true;

    return get ? prevValue : "OK";
  }

  private cmdGet(args: string[]): string | null {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'get'");
    if (this.isExpired(key)) return null;
    const entry = this.data.get(key);
    if (!entry) return null;
    if (entry.type !== "string")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value;
  }

  private cmdGetSet(args: string[]): string | null {
    const [key, value] = args;
    if (!key || value === undefined)
      throw new Error("ERR wrong number of arguments for 'getset'");
    const prev = this.cmdGet([key]);
    this.cmdSet([key, value]);
    return prev;
  }

  private cmdMGet(args: string[]): Array<string | null> {
    return args.map((k) => {
      try {
        return this.cmdGet([k]);
      } catch {
        return null;
      }
    });
  }

  private cmdMSet(args: string[]): string {
    if (args.length % 2 !== 0)
      throw new Error("ERR wrong number of arguments for 'mset'");
    for (let i = 0; i < args.length; i += 2) {
      this.cmdSet([args[i]!, args[i + 1]!]);
    }
    return "OK";
  }

  private cmdSetNx(args: string[]): number {
    const [key, value] = args;
    if (!key || value === undefined)
      throw new Error("ERR wrong number of arguments for 'setnx'");
    if (!this.isExpired(key) && this.data.has(key)) return 0;
    this.cmdSet([key, value]);
    return 1;
  }

  private cmdSetEx(args: string[]): string {
    const [key, seconds, value] = args;
    if (!key || !seconds || value === undefined)
      throw new Error("ERR wrong number of arguments for 'setex'");
    return this.cmdSet([key, value, "EX", seconds]) ?? "OK";
  }

  private cmdPSetEx(args: string[]): string {
    const [key, ms, value] = args;
    if (!key || !ms || value === undefined)
      throw new Error("ERR wrong number of arguments for 'psetex'");
    return this.cmdSet([key, value, "PX", ms]) ?? "OK";
  }

  private cmdIncrBy(key: string, by: number): number {
    if (!key) throw new Error("ERR wrong number of arguments");
    if (Number.isNaN(by))
      throw new Error("ERR value is not an integer or out of range");
    if (this.isExpired(key) || !this.data.has(key)) {
      this.data.set(key, { type: "string", value: String(by) });
      this.dirty = true;
      return by;
    }
    const entry = this.data.get(key)!;
    if (entry.type !== "string")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const n = Number(entry.value);
    if (Number.isNaN(n) || !Number.isInteger(n))
      throw new Error("ERR value is not an integer or out of range");
    const next = n + by;
    entry.value = String(next);
    this.dirty = true;
    return next;
  }

  private cmdAppend(args: string[]): number {
    const [key, value] = args;
    if (!key || value === undefined)
      throw new Error("ERR wrong number of arguments for 'append'");
    if (this.isExpired(key) || !this.data.has(key)) {
      this.data.set(key, { type: "string", value });
      this.dirty = true;
      return value.length;
    }
    const entry = this.data.get(key)!;
    if (entry.type !== "string")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    entry.value += value;
    this.dirty = true;
    return entry.value.length;
  }

  private cmdStrLen(args: string[]): number {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'strlen'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "string")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value.length;
  }

  private cmdGetRange(args: string[]): string {
    const [key, start, end] = args;
    if (!key || start === undefined || end === undefined)
      throw new Error("ERR wrong number of arguments for 'getrange'");
    if (this.isExpired(key) || !this.data.has(key)) return "";
    const entry = this.data.get(key)!;
    if (entry.type !== "string")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const s = entry.value;
    const len = s.length;
    let i = Number(start);
    let j = Number(end);
    if (i < 0) i = Math.max(0, len + i);
    if (j < 0) j = len + j;
    j = Math.min(j, len - 1);
    if (i > j) return "";
    return s.slice(i, j + 1);
  }

  // ============================================================================
  // KEY COMMANDS
  // ============================================================================

  private cmdDel(args: string[]): number {
    let count = 0;
    for (const key of args) {
      if (!this.isExpired(key) && this.data.has(key)) {
        this.data.delete(key);
        this.clearExpiry(key);
        this.zsetIndex.delete(key); // keep member index clean
        count++;
        this.dirty = true;
      }
    }
    return count;
  }

  private cmdExists(args: string[]): number {
    let count = 0;
    for (const key of args) {
      if (!this.isExpired(key) && this.data.has(key)) count++;
    }
    return count;
  }

  private cmdExpire(args: string[], useAt: boolean): number {
    const [key, seconds] = args;
    if (!key || seconds === undefined)
      throw new Error("ERR wrong number of arguments for 'expire'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const ms = useAt
      ? Number(seconds) * 1000 - Date.now()
      : Number(seconds) * 1000;
    const expiresAt = Date.now() + ms;
    const entry = this.data.get(key)!;
    entry.expiresAt = expiresAt;
    this.scheduleExpiry(key, ms);
    this.dirty = true;
    return 1;
  }

  private cmdPExpire(args: string[]): number {
    const [key, ms] = args;
    if (!key || ms === undefined)
      throw new Error("ERR wrong number of arguments for 'pexpire'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const expiresAt = Date.now() + Number(ms);
    const entry = this.data.get(key)!;
    entry.expiresAt = expiresAt;
    this.scheduleExpiry(key, Number(ms));
    this.dirty = true;
    return 1;
  }

  private cmdExpireAt(args: string[]): number {
    const [key, unixTs] = args;
    if (!key || unixTs === undefined)
      throw new Error("ERR wrong number of arguments for 'expireat'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const expiresAt = Number(unixTs) * 1000;
    const ms = expiresAt - Date.now();
    const entry = this.data.get(key)!;
    entry.expiresAt = expiresAt;
    this.scheduleExpiry(key, ms);
    this.dirty = true;
    return 1;
  }

  private cmdTtl(args: string[], precise: boolean): number {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'ttl'");
    if (this.isExpired(key) || !this.data.has(key)) return -2;
    const entry = this.data.get(key)!;
    if (!entry.expiresAt) return -1;
    const remaining = entry.expiresAt - Date.now();
    if (remaining <= 0) return -2;
    return precise ? remaining : Math.ceil(remaining / 1000);
  }

  private cmdPersist(args: string[]): number {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'persist'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (!entry.expiresAt) return 0;
    delete entry.expiresAt;
    this.clearExpiry(key);
    this.dirty = true;
    return 1;
  }

  private cmdType(args: string[]): string {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'type'");
    if (this.isExpired(key) || !this.data.has(key)) return "none";
    return this.data.get(key)!.type;
  }

  private cmdRename(args: string[]): string {
    const [src, dst] = args;
    if (!src || !dst)
      throw new Error("ERR wrong number of arguments for 'rename'");
    if (this.isExpired(src) || !this.data.has(src))
      throw new Error("ERR no such key");
    const entry = this.data.get(src)!;
    this.data.delete(src);
    this.clearExpiry(src);
    this.data.set(dst, entry);
    if (entry.expiresAt) this.scheduleExpiry(dst, entry.expiresAt - Date.now());
    this.dirty = true;
    return "OK";
  }

  private cmdRenameNx(args: string[]): number {
    const [src, dst] = args;
    if (!src || !dst)
      throw new Error("ERR wrong number of arguments for 'renamenx'");
    if (this.isExpired(src) || !this.data.has(src))
      throw new Error("ERR no such key");
    if (!this.isExpired(dst) && this.data.has(dst)) return 0;
    this.cmdRename(args);
    return 1;
  }

  private cmdKeys(args: string[]): string[] {
    const pattern = args[0] ?? "*";
    const rx = globToRegex(pattern);
    const result: string[] = [];
    for (const key of this.data.keys()) {
      if (!this.isExpired(key) && rx.test(key)) result.push(key);
    }
    return result;
  }

  private cmdScan(args: string[]): [string, string[]] {
    const cursor = Number(args[0] ?? 0);
    let match = "*";
    let count = 10;
    for (let i = 1; i < args.length; i++) {
      const opt = args[i]!.toUpperCase();
      if (opt === "MATCH") {
        match = args[++i]!;
      } else if (opt === "COUNT") {
        count = Number(args[++i]!);
      }
    }
    const rx = globToRegex(match);
    const allKeys = Array.from(this.data.keys()).filter(
      (k) => !this.isExpired(k) && rx.test(k),
    );
    // Guard against NaN: cursor % 0 is NaN; return empty page if keyspace is empty
    if (allKeys.length === 0) return ["0", []];
    const start = cursor % allKeys.length;
    const page = allKeys.slice(start, start + count);
    const nextCursor = start + count >= allKeys.length ? 0 : start + count;
    return [String(nextCursor), page];
  }

  private cmdRandomKey(): string | null {
    const keys = Array.from(this.data.keys()).filter((k) => !this.isExpired(k));
    if (keys.length === 0) return null;
    return keys[Math.floor(Math.random() * keys.length)]!;
  }

  private cmdCopy(args: string[]): number {
    const [src, dst] = args;
    if (!src || !dst)
      throw new Error("ERR wrong number of arguments for 'copy'");
    if (this.isExpired(src) || !this.data.has(src)) return 0;
    if (!this.isExpired(dst) && this.data.has(dst) && !args.includes("REPLACE"))
      return 0;
    const entry = this.data.get(src)!;
    const copy: RedisEntry = JSON.parse(JSON.stringify(entry));
    this.data.set(dst, copy);
    if (copy.expiresAt) this.scheduleExpiry(dst, copy.expiresAt - Date.now());
    this.dirty = true;
    return 1;
  }

  // ============================================================================
  // LIST COMMANDS
  // ============================================================================

  private getOrCreateList(key: string): string[] {
    const entry = this.data.get(key);
    if (!entry) {
      const list: string[] = [];
      this.data.set(key, { type: "list", value: list });
      return list;
    }
    if (entry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value;
  }

  private cmdLPush(args: string[], left: boolean): number {
    const [key, ...elements] = args;
    if (!key || elements.length === 0)
      throw new Error("ERR wrong number of arguments for 'lpush'");
    if (this.isExpired(key)) this.data.delete(key);
    const list = this.getOrCreateList(key);
    if (left) {
      for (const el of elements) list.unshift(el);
    } else {
      list.push(...elements);
    }
    this.dirty = true;
    return list.length;
  }

  private cmdLPushX(args: string[], left: boolean): number {
    const [key, ...elements] = args;
    if (!key || elements.length === 0)
      throw new Error("ERR wrong number of arguments for 'lpushx'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    return this.cmdLPush(args, left);
  }

  private cmdLPop(args: string[], left: boolean): string | null | string[] {
    const [key, countStr] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'lpop'");
    if (this.isExpired(key) || !this.data.has(key)) return countStr ? [] : null;
    const entry = this.data.get(key)!;
    if (entry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const count = countStr ? Number(countStr) : 1;
    const results: string[] = [];
    for (let i = 0; i < count; i++) {
      const el = left ? entry.value.shift() : entry.value.pop();
      if (el === undefined) break;
      results.push(el);
    }
    if (entry.value.length === 0) {
      this.data.delete(key);
      this.clearExpiry(key);
    }
    this.dirty = true;
    if (!countStr) return results[0] ?? null;
    return results;
  }

  private cmdLRange(args: string[]): string[] {
    const [key, start, stop] = args;
    if (!key || start === undefined || stop === undefined)
      throw new Error("ERR wrong number of arguments for 'lrange'");
    if (this.isExpired(key) || !this.data.has(key)) return [];
    const entry = this.data.get(key)!;
    if (entry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const len = entry.value.length;
    let s = Number(start);
    let e = Number(stop);
    if (s < 0) s = Math.max(0, len + s);
    if (e < 0) e = len + e;
    e = Math.min(e, len - 1);
    if (s > e) return [];
    return entry.value.slice(s, e + 1);
  }

  private cmdLLen(args: string[]): number {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'llen'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value.length;
  }

  private cmdLIndex(args: string[]): string | null {
    const [key, indexStr] = args;
    if (!key || indexStr === undefined)
      throw new Error("ERR wrong number of arguments for 'lindex'");
    if (this.isExpired(key) || !this.data.has(key)) return null;
    const entry = this.data.get(key)!;
    if (entry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    let i = Number(indexStr);
    if (i < 0) i = entry.value.length + i;
    return entry.value[i] ?? null;
  }

  private cmdLSet(args: string[]): string {
    const [key, indexStr, value] = args;
    if (!key || indexStr === undefined || value === undefined)
      throw new Error("ERR wrong number of arguments for 'lset'");
    if (this.isExpired(key) || !this.data.has(key))
      throw new Error("ERR no such key");
    const entry = this.data.get(key)!;
    if (entry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    let i = Number(indexStr);
    if (i < 0) i = entry.value.length + i;
    if (i < 0 || i >= entry.value.length)
      throw new Error("ERR index out of range");
    entry.value[i] = value;
    this.dirty = true;
    return "OK";
  }

  private cmdLInsert(args: string[]): number {
    const [key, where, pivot, value] = args;
    if (!key || !where || !pivot || value === undefined)
      throw new Error("ERR wrong number of arguments for 'linsert'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const idx = entry.value.indexOf(pivot);
    if (idx === -1) return -1;
    const pos = where.toUpperCase() === "AFTER" ? idx + 1 : idx;
    entry.value.splice(pos, 0, value);
    this.dirty = true;
    return entry.value.length;
  }

  private cmdLTrim(args: string[]): string {
    const [key, start, stop] = args;
    if (!key || start === undefined || stop === undefined)
      throw new Error("ERR wrong number of arguments for 'ltrim'");
    if (this.isExpired(key) || !this.data.has(key)) return "OK";
    const entry = this.data.get(key)!;
    if (entry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const len = entry.value.length;
    let s = Number(start);
    let e = Number(stop);
    if (s < 0) s = Math.max(0, len + s);
    if (e < 0) e = len + e;
    entry.value = entry.value.slice(s, e + 1);
    if (entry.value.length === 0) {
      this.data.delete(key);
      this.clearExpiry(key);
    }
    this.dirty = true;
    return "OK";
  }

  private cmdLRem(args: string[]): number {
    const [key, countStr, value] = args;
    if (!key || countStr === undefined || value === undefined)
      throw new Error("ERR wrong number of arguments for 'lrem'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const count = Number(countStr);
    let removed = 0;
    if (count > 0) {
      for (let i = 0; i < entry.value.length && removed < count; ) {
        if (entry.value[i] === value) {
          entry.value.splice(i, 1);
          removed++;
        } else i++;
      }
    } else if (count < 0) {
      const abs = Math.abs(count);
      for (let i = entry.value.length - 1; i >= 0 && removed < abs; i--) {
        if (entry.value[i] === value) {
          entry.value.splice(i, 1);
          removed++;
        }
      }
    } else {
      for (let i = 0; i < entry.value.length; ) {
        if (entry.value[i] === value) {
          entry.value.splice(i, 1);
          removed++;
        } else i++;
      }
    }
    this.dirty = true;
    return removed;
  }

  private cmdLPos(args: string[]): number | null {
    const [key, element] = args;
    if (!key || element === undefined)
      throw new Error("ERR wrong number of arguments for 'lpos'");
    if (this.isExpired(key) || !this.data.has(key)) return null;
    const entry = this.data.get(key)!;
    if (entry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const idx = entry.value.indexOf(element);
    return idx === -1 ? null : idx;
  }

  private cmdLMove(args: string[]): string | null {
    const [src, dst, srcDir, dstDir] = args;
    if (!src || !dst || !srcDir || !dstDir)
      throw new Error("ERR wrong number of arguments for 'lmove'");
    if (this.isExpired(src) || !this.data.has(src)) return null;
    const srcEntry = this.data.get(src)!;
    if (srcEntry.type !== "list")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const el =
      srcDir.toUpperCase() === "LEFT"
        ? srcEntry.value.shift()
        : srcEntry.value.pop();
    if (el === undefined) return null;
    if (srcEntry.value.length === 0) {
      this.data.delete(src);
      this.clearExpiry(src);
    }
    if (this.isExpired(dst)) this.data.delete(dst);
    const dstEntry = this.getOrCreateList(dst);
    if (dstDir.toUpperCase() === "LEFT") dstEntry.unshift(el);
    else dstEntry.push(el);
    this.dirty = true;
    return el;
  }

  // ============================================================================
  // HASH COMMANDS
  // ============================================================================

  private getOrCreateHash(key: string): Record<string, string> {
    const entry = this.data.get(key);
    if (!entry) {
      const hash: Record<string, string> = {};
      this.data.set(key, { type: "hash", value: hash });
      return hash;
    }
    if (entry.type !== "hash")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value;
  }

  private cmdHSet(args: string[]): number {
    const [key, ...pairs] = args;
    if (!key || pairs.length === 0 || pairs.length % 2 !== 0)
      throw new Error("ERR wrong number of arguments for 'hset'");
    if (this.isExpired(key)) this.data.delete(key);
    const hash = this.getOrCreateHash(key);
    let added = 0;
    for (let i = 0; i < pairs.length; i += 2) {
      if (!(pairs[i]! in hash)) added++;
      hash[pairs[i]!] = pairs[i + 1]!;
    }
    this.dirty = true;
    return added;
  }

  private cmdHMSet(args: string[]): string {
    this.cmdHSet(args);
    return "OK";
  }

  private cmdHGet(args: string[]): string | null {
    const [key, field] = args;
    if (!key || field === undefined)
      throw new Error("ERR wrong number of arguments for 'hget'");
    if (this.isExpired(key) || !this.data.has(key)) return null;
    const entry = this.data.get(key)!;
    if (entry.type !== "hash")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value[field] ?? null;
  }

  private cmdHMGet(args: string[]): Array<string | null> {
    const [key, ...fields] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'hmget'");
    if (this.isExpired(key) || !this.data.has(key))
      return fields.map(() => null);
    const entry = this.data.get(key)!;
    if (entry.type !== "hash")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return fields.map((f) => entry.value[f] ?? null);
  }

  private cmdHGetAll(args: string[]): Record<string, string> {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'hgetall'");
    if (this.isExpired(key) || !this.data.has(key)) return {};
    const entry = this.data.get(key)!;
    if (entry.type !== "hash")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return { ...entry.value };
  }

  private cmdHDel(args: string[]): number {
    const [key, ...fields] = args;
    if (!key || fields.length === 0)
      throw new Error("ERR wrong number of arguments for 'hdel'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "hash")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    let deleted = 0;
    for (const f of fields) {
      if (f in entry.value) {
        delete entry.value[f];
        deleted++;
      }
    }
    if (Object.keys(entry.value).length === 0) {
      this.data.delete(key);
      this.clearExpiry(key);
    }
    this.dirty = true;
    return deleted;
  }

  private cmdHExists(args: string[]): number {
    const [key, field] = args;
    if (!key || field === undefined)
      throw new Error("ERR wrong number of arguments for 'hexists'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "hash")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return field in entry.value ? 1 : 0;
  }

  private cmdHKeys(args: string[]): string[] {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'hkeys'");
    if (this.isExpired(key) || !this.data.has(key)) return [];
    const entry = this.data.get(key)!;
    if (entry.type !== "hash")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return Object.keys(entry.value);
  }

  private cmdHVals(args: string[]): string[] {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'hvals'");
    if (this.isExpired(key) || !this.data.has(key)) return [];
    const entry = this.data.get(key)!;
    if (entry.type !== "hash")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return Object.values(entry.value);
  }

  private cmdHLen(args: string[]): number {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'hlen'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "hash")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return Object.keys(entry.value).length;
  }

  private cmdHIncrBy(args: string[]): number {
    const [key, field, by] = args;
    if (!key || field === undefined || by === undefined)
      throw new Error("ERR wrong number of arguments for 'hincrby'");
    if (this.isExpired(key)) this.data.delete(key);
    const hash = this.getOrCreateHash(key);
    const n = Number(hash[field] ?? 0);
    if (Number.isNaN(n)) throw new Error("ERR hash value is not an integer");
    const next = n + Number(by);
    hash[field] = String(next);
    this.dirty = true;
    return next;
  }

  private cmdHIncrByFloat(args: string[]): string {
    const [key, field, by] = args;
    if (!key || field === undefined || by === undefined)
      throw new Error("ERR wrong number of arguments for 'hincrbyfloat'");
    if (this.isExpired(key)) this.data.delete(key);
    const hash = this.getOrCreateHash(key);
    const n = parseFloat(hash[field] ?? "0");
    if (Number.isNaN(n)) throw new Error("ERR hash value is not a float");
    const next = n + parseFloat(by);
    hash[field] = String(next);
    this.dirty = true;
    return String(next);
  }

  private cmdHSetNx(args: string[]): number {
    const [key, field, value] = args;
    if (!key || field === undefined || value === undefined)
      throw new Error("ERR wrong number of arguments for 'hsetnx'");
    if (this.isExpired(key)) this.data.delete(key);
    const hash = this.getOrCreateHash(key);
    if (field in hash) return 0;
    hash[field] = value;
    this.dirty = true;
    return 1;
  }

  private cmdHScan(args: string[]): [string, string[]] {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'hscan'");
    if (this.isExpired(key) || !this.data.has(key)) return ["0", []];
    const entry = this.data.get(key)!;
    if (entry.type !== "hash")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const flat: string[] = [];
    for (const [f, v] of Object.entries(entry.value)) flat.push(f, v);
    return ["0", flat];
  }

  // ============================================================================
  // SET COMMANDS
  // ============================================================================

  private getOrCreateSet(key: string): string[] {
    const entry = this.data.get(key);
    if (!entry) {
      const s: string[] = [];
      this.data.set(key, { type: "set", value: s });
      return s;
    }
    if (entry.type !== "set")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value;
  }

  private cmdSAdd(args: string[]): number {
    const [key, ...members] = args;
    if (!key || members.length === 0)
      throw new Error("ERR wrong number of arguments for 'sadd'");
    if (this.isExpired(key)) this.data.delete(key);
    const s = this.getOrCreateSet(key);
    let added = 0;
    for (const m of members) {
      if (!s.includes(m)) {
        s.push(m);
        added++;
      }
    }
    this.dirty = true;
    return added;
  }

  private cmdSRem(args: string[]): number {
    const [key, ...members] = args;
    if (!key || members.length === 0)
      throw new Error("ERR wrong number of arguments for 'srem'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "set")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    let removed = 0;
    for (const m of members) {
      const idx = entry.value.indexOf(m);
      if (idx !== -1) {
        entry.value.splice(idx, 1);
        removed++;
      }
    }
    if (entry.value.length === 0) {
      this.data.delete(key);
      this.clearExpiry(key);
    }
    this.dirty = true;
    return removed;
  }

  private cmdSMembers(args: string[]): string[] {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'smembers'");
    if (this.isExpired(key) || !this.data.has(key)) return [];
    const entry = this.data.get(key)!;
    if (entry.type !== "set")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return [...entry.value];
  }

  private cmdSCard(args: string[]): number {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'scard'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "set")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value.length;
  }

  private cmdSIsMember(args: string[]): number {
    const [key, member] = args;
    if (!key || member === undefined)
      throw new Error("ERR wrong number of arguments for 'sismember'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "set")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value.includes(member) ? 1 : 0;
  }

  private cmdSMIsMember(args: string[]): number[] {
    const [key, ...members] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'smismember'");
    if (this.isExpired(key) || !this.data.has(key)) return members.map(() => 0);
    const entry = this.data.get(key)!;
    if (entry.type !== "set")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return members.map((m) => (entry.value.includes(m) ? 1 : 0));
  }

  private resolveSet(key: string): string[] {
    if (this.isExpired(key) || !this.data.has(key)) return [];
    const entry = this.data.get(key)!;
    if (entry.type !== "set")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return [...entry.value];
  }

  private cmdSUnion(args: string[]): string[] {
    const result = new Set<string>();
    for (const key of args) for (const m of this.resolveSet(key)) result.add(m);
    return [...result];
  }

  private cmdSInter(args: string[]): string[] {
    if (args.length === 0) return [];
    let result = new Set(this.resolveSet(args[0]!));
    for (let i = 1; i < args.length; i++) {
      const s = new Set(this.resolveSet(args[i]!));
      for (const m of result) if (!s.has(m)) result.delete(m);
    }
    return [...result];
  }

  private cmdSDiff(args: string[]): string[] {
    if (args.length === 0) return [];
    const result = new Set(this.resolveSet(args[0]!));
    for (let i = 1; i < args.length; i++) {
      const s = new Set(this.resolveSet(args[i]!));
      for (const m of s) result.delete(m);
    }
    return [...result];
  }

  private cmdSUnionStore(args: string[]): number {
    const [dst, ...keys] = args;
    if (!dst)
      throw new Error("ERR wrong number of arguments for 'sunionstore'");
    const members = this.cmdSUnion(keys);
    this.data.set(dst, { type: "set", value: members });
    this.dirty = true;
    return members.length;
  }

  private cmdSInterStore(args: string[]): number {
    const [dst, ...keys] = args;
    if (!dst)
      throw new Error("ERR wrong number of arguments for 'sinterstore'");
    const members = this.cmdSInter(keys);
    this.data.set(dst, { type: "set", value: members });
    this.dirty = true;
    return members.length;
  }

  private cmdSDiffStore(args: string[]): number {
    const [dst, ...keys] = args;
    if (!dst) throw new Error("ERR wrong number of arguments for 'sdiffstore'");
    const members = this.cmdSDiff(keys);
    this.data.set(dst, { type: "set", value: members });
    this.dirty = true;
    return members.length;
  }

  private cmdSRandMember(args: string[]): string | null | string[] {
    const [key, countStr] = args;
    if (!key)
      throw new Error("ERR wrong number of arguments for 'srandmember'");
    const members = this.resolveSet(key);
    if (!countStr)
      return members[Math.floor(Math.random() * members.length)] ?? null;
    const count = Number(countStr);
    if (count >= 0) {
      const copy = [...members];
      for (let i = copy.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [copy[i], copy[j]] = [copy[j]!, copy[i]!];
      }
      return copy.slice(0, Math.min(count, copy.length));
    }
    const result: string[] = [];
    const abs = Math.abs(count);
    for (let i = 0; i < abs; i++)
      result.push(members[Math.floor(Math.random() * members.length)]!);
    return result;
  }

  private cmdSMove(args: string[]): number {
    const [src, dst, member] = args;
    if (!src || !dst || member === undefined)
      throw new Error("ERR wrong number of arguments for 'smove'");
    if (this.isExpired(src) || !this.data.has(src)) return 0;
    const srcEntry = this.data.get(src)!;
    if (srcEntry.type !== "set")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const idx = srcEntry.value.indexOf(member);
    if (idx === -1) return 0;
    srcEntry.value.splice(idx, 1);
    if (srcEntry.value.length === 0) {
      this.data.delete(src);
      this.clearExpiry(src);
    }
    if (this.isExpired(dst)) this.data.delete(dst);
    const dstSet = this.getOrCreateSet(dst);
    if (!dstSet.includes(member)) dstSet.push(member);
    this.dirty = true;
    return 1;
  }

  // ============================================================================
  // SORTED SET HELPERS
  // ============================================================================

  private resolveZSet(key: string): ZSetMember[] {
    if (this.isExpired(key) || !this.data.has(key)) return [];
    const entry = this.data.get(key)!;
    if (entry.type !== "zset")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value;
  }

  private getOrCreateZSet(key: string): ZSetMember[] {
    if (this.isExpired(key) || !this.data.has(key)) {
      const members: ZSetMember[] = [];
      this.data.set(key, { type: "zset", value: members });
      this.zsetIndex.set(key, new Map()); // fresh empty index for new ZSet
      return members;
    }
    const entry = this.data.get(key)!;
    if (entry.type !== "zset")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value;
  }

  private zsetSort(members: ZSetMember[]): void {
    members.sort((a, b) =>
      a.score !== b.score
        ? a.score - b.score
        : a.member < b.member
          ? -1
          : a.member > b.member
            ? 1
            : 0,
    );
  }

  /**
   * Return (or lazily build) the per-key member-index for a sorted set.
   * The index maps member-string → ZSetMember object for O(1) lookups,
   * replacing the previous O(n) Array.find() in every ZSet mutating command.
   */
  private getZSetIndex(key: string): Map<string, ZSetMember> {
    let idx = this.zsetIndex.get(key);
    if (!idx) {
      idx = new Map<string, ZSetMember>();
      const entry = this.data.get(key);
      if (entry?.type === "zset") {
        for (const m of entry.value) idx.set(m.member, m);
      }
      this.zsetIndex.set(key, idx);
    }
    return idx;
  }

  private parseScoreBound(s: string): { value: number; exclusive: boolean } {
    if (s === "+inf" || s === "+Inf")
      return { value: Infinity, exclusive: false };
    if (s === "-inf" || s === "-Inf")
      return { value: -Infinity, exclusive: false };
    if (s.startsWith("("))
      return { value: parseFloat(s.slice(1)), exclusive: true };
    return { value: parseFloat(s), exclusive: false };
  }

  // ============================================================================
  // SORTED SET COMMANDS
  // ============================================================================

  private cmdZAdd(args: string[]): number {
    const [key, ...rest] = args;
    if (!key || rest.length < 2)
      throw new Error("ERR wrong number of arguments for 'zadd'");

    let nx = false,
      xx = false,
      gt = false,
      lt = false,
      ch = false,
      incr = false;
    let i = 0;
    while (i < rest.length) {
      const opt = rest[i]!.toUpperCase();
      if (opt === "NX") {
        nx = true;
        i++;
      } else if (opt === "XX") {
        xx = true;
        i++;
      } else if (opt === "GT") {
        gt = true;
        i++;
      } else if (opt === "LT") {
        lt = true;
        i++;
      } else if (opt === "CH") {
        ch = true;
        i++;
      } else if (opt === "INCR") {
        incr = true;
        i++;
      } else break;
    }

    const pairs: Array<{ score: number; member: string }> = [];
    while (i < rest.length - 1) {
      pairs.push({ score: parseFloat(rest[i]!), member: rest[i + 1]! });
      i += 2;
    }
    if (pairs.length === 0) throw new Error("ERR syntax error");

    const members = this.getOrCreateZSet(key);
    const memberIdx = this.getZSetIndex(key); // O(1) lookup map
    let added = 0,
      changed = 0;
    let needsSort = false;

    for (const { score, member } of pairs) {
      const existing = memberIdx.get(member); // O(1) — was O(n) Array.find
      if (existing) {
        if (nx) continue;
        let newScore = incr ? existing.score + score : score;
        if (gt && newScore <= existing.score) continue;
        if (lt && newScore >= existing.score) continue;
        if (newScore !== existing.score) {
          existing.score = newScore;
          changed++;
          needsSort = true;
        }
      } else {
        if (xx) continue;
        const newMember: ZSetMember = { member, score };
        members.push(newMember);
        memberIdx.set(member, newMember); // keep index in sync
        added++;
        needsSort = true;
      }
    }

    if (needsSort) {
      if (added > 0 && changed === 0) {
        // Fast path: if every newly appended member's score is ≥ the previous
        // maximum AND the new members are themselves in ascending score order,
        // the full array is already sorted — skip the O(N) TimSort call.
        // This is the critical optimisation for monotonically-increasing append
        // patterns (e.g. the auto-push sorted index with 114 K entries).
        const prevLastIdx = members.length - 1 - added;
        const prevMax =
          prevLastIdx >= 0 ? members[prevLastIdx]!.score : -Infinity;
        let needFullSort = false;
        let prevScore = prevMax;
        for (let j = members.length - added; j < members.length; j++) {
          if (members[j]!.score < prevScore) {
            needFullSort = true;
            break;
          }
          prevScore = members[j]!.score;
        }
        if (needFullSort) this.zsetSort(members);
        // else: all new members are already in their correct sorted positions.
      } else {
        // Score updates may have moved members out of position — full sort.
        this.zsetSort(members);
      }
    }
    this.dirty = true;
    return ch ? added + changed : added;
  }

  private cmdZRem(args: string[]): number {
    const [key, ...members] = args;
    if (!key || members.length === 0)
      throw new Error("ERR wrong number of arguments for 'zrem'");
    const zset = this.resolveZSet(key);
    const memberIdx = this.zsetIndex.get(key);
    let removed = 0;
    for (const m of members) {
      const entry = memberIdx?.get(m);
      if (entry !== undefined) {
        // Use reference equality (indexOf) — faster than scanning by string
        const pos = zset.indexOf(entry);
        if (pos !== -1) {
          zset.splice(pos, 1);
          memberIdx!.delete(m);
          removed++;
        }
      } else {
        // Fallback for index miss (e.g. loaded from old snapshot without index)
        const idx = zset.findIndex((z) => z.member === m);
        if (idx !== -1) {
          zset.splice(idx, 1);
          removed++;
        }
      }
    }
    if (removed > 0) {
      if (zset.length === 0) {
        this.data.delete(key);
        this.clearExpiry(key);
        this.zsetIndex.delete(key);
      }
      this.dirty = true;
    }
    return removed;
  }

  private cmdZScore(args: string[]): string | null {
    const [key, member] = args;
    if (!key || member === undefined)
      throw new Error("ERR wrong number of arguments for 'zscore'");
    const found = this.getZSetIndex(key).get(member); // O(1)
    return found ? String(found.score) : null;
  }

  private cmdZMScore(args: string[]): Array<string | null> {
    const [key, ...members] = args;
    if (!key || members.length === 0)
      throw new Error("ERR wrong number of arguments for 'zmscore'");
    const idx = this.getZSetIndex(key); // O(1) per member
    return members.map((m) => {
      const f = idx.get(m);
      return f ? String(f.score) : null;
    });
  }

  private cmdZIncrBy(args: string[]): string {
    const [key, incrStr, member] = args;
    if (!key || incrStr === undefined || member === undefined)
      throw new Error("ERR wrong number of arguments for 'zincrby'");
    const members = this.getOrCreateZSet(key);
    const memberIdx = this.getZSetIndex(key);
    const existing = memberIdx.get(member); // O(1)
    const incr = parseFloat(incrStr);
    if (existing) {
      existing.score += incr;
      this.zsetSort(members);
      this.dirty = true;
      return String(existing.score);
    }
    const newMember: ZSetMember = { member, score: incr };
    members.push(newMember);
    memberIdx.set(member, newMember); // keep index in sync
    this.zsetSort(members);
    this.dirty = true;
    return String(incr);
  }

  private cmdZCard(args: string[]): number {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'zcard'");
    return this.resolveZSet(key).length;
  }

  private cmdZCount(args: string[]): number {
    const [key, minStr, maxStr] = args;
    if (!key || minStr === undefined || maxStr === undefined)
      throw new Error("ERR wrong number of arguments for 'zcount'");
    const zset = this.resolveZSet(key);
    const min = this.parseScoreBound(minStr);
    const max = this.parseScoreBound(maxStr);
    return zset.filter((z) => {
      const aboveMin = min.exclusive
        ? z.score > min.value
        : z.score >= min.value;
      const belowMax = max.exclusive
        ? z.score < max.value
        : z.score <= max.value;
      return aboveMin && belowMax;
    }).length;
  }

  private cmdZLexCount(args: string[]): number {
    const [key, minStr, maxStr] = args;
    if (!key || minStr === undefined || maxStr === undefined)
      throw new Error("ERR wrong number of arguments for 'zlexcount'");
    const zset = this.resolveZSet(key);
    const {
      inclusive: [minInc, maxInc],
      bounds: [minBound, maxBound],
    } = this.parseLexBounds(minStr, maxStr);
    return zset.filter((z) => {
      const aboveMin =
        minBound === null
          ? true
          : minInc
            ? z.member >= minBound
            : z.member > minBound;
      const belowMax =
        maxBound === null
          ? true
          : maxInc
            ? z.member <= maxBound
            : z.member < maxBound;
      return aboveMin && belowMax;
    }).length;
  }

  private parseLexBounds(
    minStr: string,
    maxStr: string,
  ): {
    members: string[];
    inclusive: [boolean, boolean];
    bounds: [string | null, string | null];
  } {
    const parseOne = (
      s: string,
    ): { bound: string | null; inclusive: boolean } => {
      if (s === "-") return { bound: null, inclusive: true };
      if (s === "+") return { bound: null, inclusive: true };
      if (s.startsWith("[")) return { bound: s.slice(1), inclusive: true };
      if (s.startsWith("(")) return { bound: s.slice(1), inclusive: false };
      throw new Error("ERR min or max is not valid string range item");
    };
    const minP = parseOne(minStr);
    const maxP = parseOne(maxStr);
    return {
      members: [],
      inclusive: [minP.inclusive, maxP.inclusive],
      bounds: [minP.bound, maxP.bound],
    };
  }

  private cmdZRange(args: string[]): string[] {
    const [key, startStr, stopStr, ...opts] = args;
    if (!key || startStr === undefined || stopStr === undefined)
      throw new Error("ERR wrong number of arguments for 'zrange'");
    const withScores = opts.some((o) => o.toUpperCase() === "WITHSCORES");
    const rev = opts.some((o) => o.toUpperCase() === "REV");
    const byscore = opts.some((o) => o.toUpperCase() === "BYSCORE");

    let zset = this.resolveZSet(key);
    if (rev) zset = [...zset].reverse();

    let result: ZSetMember[];
    if (byscore) {
      const min = this.parseScoreBound(startStr);
      const max = this.parseScoreBound(stopStr);
      result = zset.filter((z) => {
        const aboveMin = min.exclusive
          ? z.score > min.value
          : z.score >= min.value;
        const belowMax = max.exclusive
          ? z.score < max.value
          : z.score <= max.value;
        return aboveMin && belowMax;
      });
    } else {
      const start = Number(startStr);
      const stop = Number(stopStr);
      const len = zset.length;
      const s = start < 0 ? Math.max(0, len + start) : start;
      const e = stop < 0 ? len + stop : Math.min(stop, len - 1);
      result = zset.slice(s, e + 1);
    }

    if (withScores) {
      const out: string[] = [];
      for (const z of result) {
        out.push(z.member, String(z.score));
      }
      return out;
    }
    return result.map((z) => z.member);
  }

  private cmdZRevRange(args: string[]): string[] {
    const [key, startStr, stopStr, ...opts] = args;
    if (!key || startStr === undefined || stopStr === undefined)
      throw new Error("ERR wrong number of arguments for 'zrevrange'");
    const withScores = opts.some((o) => o.toUpperCase() === "WITHSCORES");
    const zset = [...this.resolveZSet(key)].reverse();
    const len = zset.length;
    const start = Number(startStr);
    const stop = Number(stopStr);
    const s = start < 0 ? Math.max(0, len + start) : start;
    const e = stop < 0 ? len + stop : Math.min(stop, len - 1);
    const slice = zset.slice(s, e + 1);
    if (withScores) {
      const out: string[] = [];
      for (const z of slice) {
        out.push(z.member, String(z.score));
      }
      return out;
    }
    return slice.map((z) => z.member);
  }

  private cmdZRangeByScore(args: string[], rev: boolean): string[] {
    let [key, minStr, maxStr, ...opts] = args;
    if (!key || minStr === undefined || maxStr === undefined)
      throw new Error("ERR wrong number of arguments");
    if (rev) {
      [minStr, maxStr] = [maxStr, minStr];
    }
    const withScores = opts.some((o) => o.toUpperCase() === "WITHSCORES");
    let limitOffset = 0,
      limitCount = -1;
    const limitIdx = opts.findIndex((o) => o.toUpperCase() === "LIMIT");
    if (limitIdx !== -1) {
      limitOffset = Number(opts[limitIdx + 1]);
      limitCount = Number(opts[limitIdx + 2]);
    }

    let zset = this.resolveZSet(key);
    if (rev) zset = [...zset].reverse();
    const minB = this.parseScoreBound(rev ? maxStr : minStr);
    const maxB = this.parseScoreBound(rev ? minStr : maxStr);

    let result = zset.filter((z) => {
      const aboveMin = minB.exclusive
        ? z.score > minB.value
        : z.score >= minB.value;
      const belowMax = maxB.exclusive
        ? z.score < maxB.value
        : z.score <= maxB.value;
      return aboveMin && belowMax;
    });

    if (limitOffset > 0) result = result.slice(limitOffset);
    if (limitCount >= 0) result = result.slice(0, limitCount);

    if (withScores) {
      const out: string[] = [];
      for (const z of result) {
        out.push(z.member, String(z.score));
      }
      return out;
    }
    return result.map((z) => z.member);
  }

  private cmdZRangeByLex(args: string[], rev: boolean): string[] {
    let [key, minStr, maxStr, ...opts] = args;
    if (!key || minStr === undefined || maxStr === undefined)
      throw new Error("ERR wrong number of arguments");
    if (rev) {
      [minStr, maxStr] = [maxStr, minStr];
    }
    let limitOffset = 0,
      limitCount = -1;
    const limitIdx = opts.findIndex((o) => o.toUpperCase() === "LIMIT");
    if (limitIdx !== -1) {
      limitOffset = Number(opts[limitIdx + 1]);
      limitCount = Number(opts[limitIdx + 2]);
    }

    const {
      inclusive: [minInc, maxInc],
      bounds: [minBound, maxBound],
    } = this.parseLexBounds(minStr!, maxStr!);
    let zset = this.resolveZSet(key);
    if (rev) zset = [...zset].reverse();

    let result = zset.filter((z) => {
      const aboveMin =
        minBound === null
          ? true
          : minInc
            ? z.member >= minBound
            : z.member > minBound;
      const belowMax =
        maxBound === null
          ? true
          : maxInc
            ? z.member <= maxBound
            : z.member < maxBound;
      return aboveMin && belowMax;
    });

    if (limitOffset > 0) result = result.slice(limitOffset);
    if (limitCount >= 0) result = result.slice(0, limitCount);
    return result.map((z) => z.member);
  }

  private cmdZRank(args: string[], rev: boolean): number | null {
    const [key, member] = args;
    if (!key || member === undefined)
      throw new Error("ERR wrong number of arguments for 'zrank'");
    let zset = this.resolveZSet(key);
    if (rev) zset = [...zset].reverse();
    const idx = zset.findIndex((z) => z.member === member);
    return idx === -1 ? null : idx;
  }

  private cmdZPop(args: string[], max: boolean): string[] {
    const [key, countStr] = args;
    if (!key)
      throw new Error("ERR wrong number of arguments for 'zpopmin/zpopmax'");
    const count = countStr !== undefined ? Number(countStr) : 1;
    const members = this.resolveZSet(key);
    if (members.length === 0) return [];
    const popped = max ? members.splice(-count) : members.splice(0, count);
    if (max) popped.reverse();
    // Keep member index in sync
    const memberIdx = this.zsetIndex.get(key);
    if (memberIdx) {
      for (const z of popped) memberIdx.delete(z.member);
    }
    if (members.length === 0) {
      this.data.delete(key);
      this.clearExpiry(key);
      this.zsetIndex.delete(key);
    } else this.dirty = true;
    const out: string[] = [];
    for (const z of popped) {
      out.push(z.member, String(z.score));
    }
    return out;
  }

  private cmdZRandMember(args: string[]): string | string[] | null {
    const [key, countStr] = args;
    if (!key)
      throw new Error("ERR wrong number of arguments for 'zrandmember'");
    const zset = this.resolveZSet(key);
    if (!countStr) {
      if (zset.length === 0) return null;
      return zset[Math.floor(Math.random() * zset.length)]!.member;
    }
    const count = Number(countStr);
    const abs = Math.abs(count);
    if (count >= 0) {
      const shuffled = [...zset].sort(() => Math.random() - 0.5);
      return shuffled
        .slice(0, Math.min(abs, shuffled.length))
        .map((z) => z.member);
    }
    const result: string[] = [];
    for (let i = 0; i < abs; i++)
      result.push(zset[Math.floor(Math.random() * zset.length)]!.member);
    return result;
  }

  /** Helper: persist a new ZSet result to a destination key, updating both data and zsetIndex. */
  private setZSetResult(dst: string, members: ZSetMember[]): void {
    this.data.set(dst, { type: "zset", value: members });
    this.zsetIndex.set(dst, new Map(members.map((m) => [m.member, m])));
    this.dirty = true;
  }

  private cmdZDiffStore(args: string[]): number {
    const [dst, ...keys] = args;
    if (!dst || keys.length === 0)
      throw new Error("ERR wrong number of arguments for 'zdiffstore'");
    const [firstKey, ...restKeys] = keys;
    const base = new Map(
      this.resolveZSet(firstKey!).map((z) => [z.member, z.score]),
    );
    for (const k of restKeys) {
      for (const z of this.resolveZSet(k)) base.delete(z.member);
    }
    const members: ZSetMember[] = Array.from(base.entries()).map(
      ([member, score]) => ({ member, score }),
    );
    this.zsetSort(members);
    this.setZSetResult(dst, members);
    return members.length;
  }

  private cmdZUnionStore(args: string[]): number {
    const [dst, numkeysStr, ...rest] = args;
    if (!dst || numkeysStr === undefined)
      throw new Error("ERR wrong number of arguments for 'zunionstore'");
    const numkeys = Number(numkeysStr);
    const keys = rest.slice(0, numkeys);
    const weightStrs = rest.slice(numkeys);
    const weights: number[] = [];
    let wi = weightStrs.findIndex((s) => s.toUpperCase() === "WEIGHTS");
    if (wi !== -1) {
      for (let j = wi + 1; j < wi + 1 + numkeys; j++)
        weights.push(Number(weightStrs[j]));
    } else {
      for (let j = 0; j < numkeys; j++) weights.push(1);
    }

    const acc = new Map<string, number>();
    for (let k = 0; k < keys.length; k++) {
      for (const z of this.resolveZSet(keys[k]!)) {
        const w = weights[k] ?? 1;
        acc.set(z.member, (acc.get(z.member) ?? 0) + z.score * w);
      }
    }
    const members: ZSetMember[] = Array.from(acc.entries()).map(
      ([member, score]) => ({ member, score }),
    );
    this.zsetSort(members);
    this.setZSetResult(dst, members);
    return members.length;
  }

  private cmdZInterStore(args: string[]): number {
    const [dst, numkeysStr, ...rest] = args;
    if (!dst || numkeysStr === undefined)
      throw new Error("ERR wrong number of arguments for 'zinterstore'");
    const numkeys = Number(numkeysStr);
    const keys = rest.slice(0, numkeys);
    const weightStrs = rest.slice(numkeys);
    const weights: number[] = [];
    let wi = weightStrs.findIndex((s) => s.toUpperCase() === "WEIGHTS");
    if (wi !== -1) {
      for (let j = wi + 1; j < wi + 1 + numkeys; j++)
        weights.push(Number(weightStrs[j]));
    } else {
      for (let j = 0; j < numkeys; j++) weights.push(1);
    }

    if (keys.length === 0) {
      this.setZSetResult(dst, []);
      return 0;
    }
    const firstSet = new Map(
      this.resolveZSet(keys[0]!).map((z) => [
        z.member,
        z.score * (weights[0] ?? 1),
      ]),
    );
    for (let k = 1; k < keys.length; k++) {
      const other = new Map(
        this.resolveZSet(keys[k]!).map((z) => [z.member, z.score]),
      );
      for (const [m] of firstSet) {
        if (!other.has(m)) firstSet.delete(m);
        else
          firstSet.set(m, firstSet.get(m)! + other.get(m)! * (weights[k] ?? 1));
      }
    }
    const members: ZSetMember[] = Array.from(firstSet.entries()).map(
      ([member, score]) => ({ member, score }),
    );
    this.zsetSort(members);
    this.setZSetResult(dst, members);
    return members.length;
  }

  // ============================================================================
  // LUA SCRIPTING (EVAL / EVALSHA / SCRIPT)
  // ============================================================================

  private sha1(script: string): string {
    return createHash("sha1").update(script).digest("hex");
  }

  private luaToRedis(val: unknown): RedisCommandResult {
    if (val === null || val === undefined) return null;
    if (typeof val === "boolean") return val ? 1 : null;
    if (typeof val === "number") return Math.trunc(val);
    if (typeof val === "string") return val;
    if (Array.isArray(val))
      return val.map((v) => this.luaToRedis(v)) as string[];
    if (typeof val === "object") {
      const obj = val as Record<string, unknown>;
      if (obj["err"] !== undefined) throw new Error(String(obj["err"]));
      if (obj["ok"] !== undefined) return String(obj["ok"]);
      const entries = Object.values(obj);
      return entries.map((v) => this.luaToRedis(v)) as string[];
    }
    return String(val);
  }

  // Recursively convert Lua table (plain JS object from wasmoon) → native JS value.
  // Lua arrays are 1-indexed integer-keyed tables; we detect and convert them.
  private luaTableToJs(val: unknown): unknown {
    if (val === null || val === undefined) return null;
    if (typeof val !== "object") return val;
    if (val instanceof Uint8Array || Buffer.isBuffer(val)) return val;
    const obj = val as Record<string | number, unknown>;
    const keys = Object.keys(obj).filter((k) => k !== "__name");
    if (keys.length === 0) return {};
    // wasmoon proxies Lua tables as 0-indexed in JS (key "0" = Lua index 1).
    // Detect either 0-based or 1-based all-integer keys and convert to JS array.
    const numericKeys = keys
      .map(Number)
      .filter((n) => Number.isInteger(n) && n >= 0);
    if (numericKeys.length === keys.length && numericKeys.length > 0) {
      const minIdx = Math.min(...numericKeys);
      const maxIdx = Math.max(...numericKeys);
      // Must be a contiguous sequence starting at 0 or 1
      if (maxIdx - minIdx + 1 === numericKeys.length) {
        const arr: unknown[] = [];
        for (let i = minIdx; i <= maxIdx; i++)
          arr.push(this.luaTableToJs(obj[i]));
        return arr;
      }
    }
    const result: Record<string, unknown> = {};
    for (const k of keys) result[k] = this.luaTableToJs(obj[k]);
    return result;
  }

  // Encode binary bytes as a hex string — ASCII-safe, survives the Lua VM unharmed.
  private bytesToLuaStr(bytes: Uint8Array): string {
    return Buffer.from(bytes).toString("hex");
  }

  // Decode a hex string (produced by bytesToLuaStr) back to binary bytes.
  private luaStrToBytes(str: unknown): Buffer {
    if (str instanceof Uint8Array) return Buffer.from(str);
    if (Buffer.isBuffer(str)) return str;
    const s = String(str);
    // Hex-encoded path (all hex chars, even length) — our encoding
    if (s.length % 2 === 0 && /^[0-9a-fA-F]*$/.test(s))
      return Buffer.from(s, "hex");
    // Fallback for raw binary passed directly (unlikely but safe)
    return Buffer.from(s, "binary");
  }

  // Emit a Lua literal for a decoded JS value (numbers, strings, bools, arrays, maps).
  // Called only for msgpack-decoded data, so no arbitrary binary byte values.
  private luaQuoteStr(s: string): string {
    // Always use double-quoted strings — safe for use as table keys too.
    return `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n").replace(/\r/g, "\\r").replace(/\0/g, "\\0")}"`;
  }

  private valToLuaLiteral(val: unknown): string {
    if (val === null || val === undefined) return "nil";
    if (typeof val === "boolean") return val ? "true" : "false";
    if (typeof val === "number") return isFinite(val) ? String(val) : "0";
    if (typeof val === "string") return this.luaQuoteStr(val);
    if (Array.isArray(val)) {
      const elems = val.map((v) => this.valToLuaLiteral(v)).join(", ");
      return `{${elems}}`;
    }
    if (typeof val === "object") {
      const pairs = Object.entries(val as Record<string, unknown>)
        .map(
          ([k, v]) =>
            `[${this.luaQuoteStr(String(k))}] = ${this.valToLuaLiteral(v)}`,
        )
        .join(", ");
      return `{${pairs}}`;
    }
    return "nil";
  }

  // Convert a JS value decoded from MessagePack back to a proper Lua value.
  // Uses doStringSync to build proper Lua tables that respond to # and key access.
  private jsToLuaVal(val: unknown, lua?: LuaEngine): unknown {
    if (val === null || val === undefined) return null;
    if (
      typeof val === "string" ||
      typeof val === "number" ||
      typeof val === "boolean"
    )
      return val;
    if (!lua) return val; // fallback without engine
    const luaCode = `return ${this.valToLuaLiteral(val)}`;
    return lua.doStringSync(luaCode);
  }

  // ─────────────────────────────────────────────────────────────────────────────
  // Redis reply → Lua value conversion (authoritative mapping from the Redis docs)
  //
  //  Reply type          Redis description             Lua equivalent
  //  ─────────────────   ─────────────────────────     ─────────────────────────
  //  Nil bulk string     GET of missing key            Lua boolean false
  //  Integer             INCR, ZADD, …                 Lua number
  //  Simple string       OK, PONG, …                   Lua string
  //  Bulk string         GET, HGET, …                  Lua string
  //  Multi-bulk array    LRANGE, SMEMBERS, KEYS, …     Lua table (1-indexed seq)
  //    ↳ with nulls      HMGET missing fields          null element → false
  //  Hash (HGETALL)      flat [k,v,k,v] multi-bulk     Lua table (1-indexed seq)
  //
  // Returning JS `null` directly to Lua crashes wasmoon (Promise extension tries
  // null.then → TypeError).  We must never return null from redis.call().
  // ─────────────────────────────────────────────────────────────────────────────
  private redisReplyToLua(result: RedisCommandResult, lua: LuaEngine): unknown {
    // ── Nil bulk reply → Lua false ──────────────────────────────────────────
    if (result === null || result === undefined) return false;

    // ── Scalars pass through unchanged ──────────────────────────────────────
    if (typeof result === "string" || typeof result === "number") return result;
    if (typeof result === "boolean") return result ? 1 : 0;

    // ── Plain JS array (LRANGE, SMEMBERS, MGET, KEYS, …) ───────────────────
    if (Array.isArray(result)) {
      // Map any null elements to false (HMGET missing fields)
      const safe = result.map((v) =>
        v === null || v === undefined ? false : v,
      );
      return this.buildLuaSequence(safe, lua);
    }

    // ── Plain JS object — only HGETALL returns this; Redis flattens it to
    //    a [field, value, field, value, …] multi-bulk reply (Lua 1-indexed seq)
    if (typeof result === "object") {
      const flat: string[] = [];
      for (const [k, v] of Object.entries(result as Record<string, string>)) {
        flat.push(k, v ?? "");
      }
      return this.buildLuaSequence(flat, lua);
    }

    return result;
  }

  // Build a proper 1-indexed Lua sequence table from a flat JS array.
  // Uses doStringSync with a generated literal so # and t[i] work natively.
  private buildLuaSequence(arr: unknown[], lua: LuaEngine): unknown {
    if (arr.length === 0) return lua.doStringSync("return {}");
    const elems = arr
      .map((v) => {
        if (v === null || v === undefined || v === false) return "false";
        if (typeof v === "number") return String(v);
        if (typeof v === "string") return this.luaQuoteStr(v);
        return "false";
      })
      .join(", ");
    return lua.doStringSync(`return {${elems}}`);
  }

  private async runLua(
    script: string,
    keys: string[],
    argv: string[],
  ): Promise<RedisCommandResult> {
    // Scripts that do NOT use redis.call() / redis.pcall() can run inside a
    // worker thread (non-blocking for the main event loop).  Scripts that DO
    // need redis.call() must run on the main thread where the store is
    // accessible.
    const usesRedisCall = /redis\s*\.\s*[pc]?call\s*\(/.test(script);
    if (!usesRedisCall && luaPool.isReady) {
      try {
        const result = await luaPool.run(script, keys, argv);
        return result as RedisCommandResult;
      } catch (err) {
        // If the pool fails, fall through to the main-thread runner
        const msg = err instanceof Error ? err.message : String(err);
        if (!msg.includes("redis.call() is not supported")) {
          // Real script error — propagate immediately
          throw err;
        }
        // else: pool signaled it can't handle this script → fall through
      }
    }

    // ── Main-thread Lua execution (supports redis.call) ─────────────────────
    // Each createEngine() allocates a full WebAssembly instance.  Cap concurrency
    // so a request flood can't exhaust the heap before V8 can GC old engines.
    if (!acquireLuaSlot()) {
      throw new Error(
        "ERR Lua engine pool exhausted — too many concurrent EVAL scripts (max 8)",
      );
    }
    const lua = await luaFactory.createEngine({ openStandardLibs: true });
    try {
      // KEYS and ARGV must be proper 1-indexed Lua sequence tables.
      // Embed values directly as Lua string literals to avoid proxy indexing ambiguity.
      const keysLit = keys.map((k) => this.luaQuoteStr(k)).join(", ");
      const argvLit = argv.map((a) => this.luaQuoteStr(a)).join(", ");
      lua.doStringSync(`KEYS = {${keysLit}}; ARGV = {${argvLit}}`);

      // Helper shared by redis.call and redis.pcall
      const toStrArgs = (args: unknown[]): string[] =>
        args.map((a) => {
          if (a === null || a === undefined) return "";
          if (a instanceof Uint8Array || Buffer.isBuffer(a))
            return Buffer.from(a).toString("binary");
          return String(a);
        });

      lua.global.set("redis", {
        // redis.call() — raises a Lua error on Redis error replies
        call: (cmd: string, ...args: unknown[]) => {
          const result = this.execSync(cmd, toStrArgs(args));
          return this.redisReplyToLua(result, lua);
        },
        // redis.pcall() — returns { err = "..." } on Redis error replies
        pcall: (cmd: string, ...args: unknown[]) => {
          try {
            const result = this.execSync(cmd, toStrArgs(args));
            return this.redisReplyToLua(result, lua);
          } catch (e) {
            return { err: e instanceof Error ? e.message : String(e) };
          }
        },
        error_reply: (msg: string) => ({ err: msg }),
        status_reply: (msg: string) => ({ ok: msg }),
        LOG_DEBUG: 0,
        LOG_VERBOSE: 1,
        LOG_NOTICE: 2,
        LOG_WARNING: 3,
        log: (_level: number, _msg: string) => {},
      });

      lua.global.set("cjson", {
        encode: (v: unknown) => JSON.stringify(this.luaTableToJs(v)),
        decode: (s: string) => this.jsToLuaVal(JSON.parse(s), lua),
      });

      // cmsgpack: Redis-compatible MessagePack extension.
      // pack()   serializes a Lua value → MessagePack binary (returned as a Latin-1 Lua string).
      // unpack() deserializes a MessagePack binary Lua string → Lua value.
      lua.global.set("cmsgpack", {
        pack: (v: unknown): string => {
          const jsVal = this.luaTableToJs(v);
          const bytes = msgpackEncode(jsVal);
          return this.bytesToLuaStr(bytes);
        },
        unpack: (s: unknown): unknown => {
          const buf = this.luaStrToBytes(s);
          const decoded = msgpackDecode(buf);
          return this.jsToLuaVal(decoded, lua);
        },
      });

      lua.global.set("struct", {
        pack: (_fmt: string, ...vals: unknown[]): string => {
          // Minimal struct.pack for 'H' (unsigned short, 2 bytes, big-endian)
          // BullMQ uses this only for the 'H' format in a few scripts.
          if (typeof _fmt === "string" && _fmt === ">H") {
            const n = Number(vals[0]) & 0xffff;
            return String.fromCharCode((n >> 8) & 0xff, n & 0xff);
          }
          throw new Error("ERR struct.pack format not supported: " + _fmt);
        },
        unpack: (_fmt: string, s: unknown, _pos?: number): unknown[] => {
          if (typeof _fmt === "string" && _fmt === ">H") {
            const buf = this.luaStrToBytes(s);
            const n = (buf[0]! << 8) | buf[1]!;
            return [n, 3]; // value, next position
          }
          throw new Error("ERR struct.unpack format not supported: " + _fmt);
        },
        size: (_fmt: string): number => {
          if (_fmt === ">H") return 2;
          throw new Error("ERR struct.size format not supported: " + _fmt);
        },
      });

      lua.global.set("tonumber", (v: unknown, base?: number) => {
        if (v === null || v === undefined) return null;
        const n = base ? parseInt(String(v), base) : parseFloat(String(v));
        return isNaN(n) ? null : n;
      });

      const result = await lua.doString(script);
      return this.luaToRedis(result);
    } finally {
      lua.global.close();
      releaseLuaSlot();
    }
  }

  private async cmdEval(args: string[]): Promise<RedisCommandResult> {
    const [script, numkeysStr, ...rest] = args;
    if (script === undefined || numkeysStr === undefined)
      throw new Error("ERR wrong number of arguments for 'eval'");
    const numkeys = Number(numkeysStr);
    if (isNaN(numkeys) || numkeys < 0)
      throw new Error("ERR value is not an integer or out of range");
    const keys = rest.slice(0, numkeys);
    const argv = rest.slice(numkeys);
    return this.runLua(script, keys, argv);
  }

  private async cmdEvalSha(args: string[]): Promise<RedisCommandResult> {
    const [sha, numkeysStr, ...rest] = args;
    if (sha === undefined || numkeysStr === undefined)
      throw new Error("ERR wrong number of arguments for 'evalsha'");
    const script = this.scriptCache.get(sha.toLowerCase());
    if (!script)
      throw new Error("NOSCRIPT No matching script. Please use EVAL.");
    const numkeys = Number(numkeysStr);
    const keys = rest.slice(0, numkeys);
    const argv = rest.slice(numkeys);
    return this.runLua(script, keys, argv);
  }

  private cmdScript(args: string[]): RedisCommandResult {
    const [subcmd, ...rest] = args;
    if (!subcmd) throw new Error("ERR wrong number of arguments for 'script'");
    const sub = subcmd.toUpperCase();

    if (sub === "LOAD") {
      const script = rest[0];
      if (script === undefined)
        throw new Error("ERR wrong number of arguments for 'script|load'");
      const sha = this.sha1(script);
      this.scriptCache.set(sha, script);
      return sha;
    }

    if (sub === "EXISTS") {
      return rest.map((sha) =>
        this.scriptCache.has(sha.toLowerCase()) ? 1 : 0,
      ) as unknown as string[];
    }

    if (sub === "FLUSH") {
      this.scriptCache.clear();
      return "OK";
    }

    throw new Error(`ERR unknown subcommand '${subcmd}' for 'script'`);
  }

  // ============================================================================
  // RPOPLPUSH
  // ============================================================================

  private cmdRPopLPush(args: string[]): string | null {
    const [src, dst] = args;
    if (!src || !dst)
      throw new Error("ERR wrong number of arguments for 'rpoplpush'");
    return this.cmdLMove([src, dst, "RIGHT", "LEFT"]);
  }

  // ============================================================================
  // STREAM HELPERS
  // ============================================================================

  private streamSeqMap = new Map<number, number>();

  private generateStreamId(): string {
    const ms = Date.now();
    const seq = (this.streamSeqMap.get(ms) ?? -1) + 1;
    this.streamSeqMap.set(ms, seq);
    if (this.streamSeqMap.size > 10) {
      const oldest = [...this.streamSeqMap.keys()].sort((a, b) => a - b)[0]!;
      this.streamSeqMap.delete(oldest);
    }
    return `${ms}-${seq}`;
  }

  private parseStreamId(id: string): [number, number] {
    const parts = id.split("-");
    return [Number(parts[0] ?? 0), Number(parts[1] ?? 0)];
  }

  private compareStreamIds(a: string, b: string): number {
    const [ams, aseq] = this.parseStreamId(a);
    const [bms, bseq] = this.parseStreamId(b);
    if (ams !== bms) return ams - bms;
    return aseq - bseq;
  }

  private getOrCreateStream(
    key: string,
  ): RedisStreamEntry {
    const existing = this.data.get(key);
    if (existing) {
      if (existing.type !== "stream")
        throw new Error(
          "WRONGTYPE Operation against a key holding the wrong kind of value",
        );
      return existing;
    }
    const entry: RedisStreamEntry = {
      type: "stream",
      value: [],
      groups: {},
    };
    this.data.set(key, entry);
    return entry;
  }

  private trimStream(
    stream: RedisStreamEntry,
    maxlen: number,
  ): number {
    const excess = stream.value.length - maxlen;
    if (excess <= 0) return 0;
    stream.value.splice(0, excess);
    return excess;
  }

  private streamIdAfter(
    entries: StreamItem[],
    afterId: string,
  ): StreamItem[] {
    if (afterId === "0" || afterId === "0-0") return entries;
    return entries.filter((e) => this.compareStreamIds(e.id, afterId) > 0);
  }

  private formatStreamEntries(
    entries: StreamItem[],
  ): unknown[] {
    return entries.map((e) => [e.id, e.fields]);
  }

  // ============================================================================
  // STREAM COMMANDS
  // ============================================================================

  private cmdXAdd(args: string[]): string | null {
    let i = 0;
    const key = args[i++];
    if (!key) throw new Error("ERR wrong number of arguments for 'xadd'");

    let noMkStream = false;
    let maxlen: number | null = null;

    // Parse optional flags
    while (i < args.length) {
      const tok = args[i]!.toUpperCase();
      if (tok === "NOMKSTREAM") {
        noMkStream = true;
        i++;
      } else if (tok === "MAXLEN" || tok === "MINID") {
        i++;
        if (args[i] === "~") i++;
        maxlen = Number(args[i++]);
      } else break;
    }

    const rawId = args[i++];
    if (!rawId) throw new Error("ERR wrong number of arguments for 'xadd'");
    const fields = args.slice(i);
    if (fields.length === 0 || fields.length % 2 !== 0)
      throw new Error("ERR wrong number of arguments for 'xadd'");

    if (noMkStream && (!this.data.has(key) || this.isExpired(key))) return null;
    if (this.isExpired(key)) this.data.delete(key);

    const stream = this.getOrCreateStream(key);
    const id = rawId === "*" ? this.generateStreamId() : rawId;
    stream.value.push({ id, fields });
    if (maxlen !== null && maxlen >= 0) this.trimStream(stream, maxlen);
    this.dirty = true;
    return id;
  }

  private cmdXTrim(args: string[]): number {
    const [key, strategy, ...rest] = args;
    if (!key || !strategy)
      throw new Error("ERR wrong number of arguments for 'xtrim'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "stream")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );

    let idx = 0;
    if (rest[idx] === "~") idx++;
    const threshold = Number(rest[idx]);
    if (isNaN(threshold))
      throw new Error("ERR value is not an integer or out of range");

    const strat = strategy.toUpperCase();
    if (strat === "MAXLEN") {
      const removed = this.trimStream(entry, threshold);
      if (removed > 0) this.dirty = true;
      return removed;
    } else if (strat === "MINID") {
      const before = entry.value.length;
      entry.value = entry.value.filter(
        (e) => this.compareStreamIds(e.id, String(threshold)) >= 0,
      );
      const removed = before - entry.value.length;
      if (removed > 0) this.dirty = true;
      return removed;
    }
    throw new Error(`ERR unsupported XTRIM strategy '${strategy}'`);
  }

  private cmdXLen(args: string[]): number {
    const [key] = args;
    if (!key) throw new Error("ERR wrong number of arguments for 'xlen'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "stream")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    return entry.value.length;
  }

  private cmdXRange(args: string[], reverse: boolean): unknown[] {
    const [key, start, end, ...rest] = args;
    if (!key || start === undefined || end === undefined)
      throw new Error(
        `ERR wrong number of arguments for '${reverse ? "xrevrange" : "xrange"}'`,
      );
    if (this.isExpired(key) || !this.data.has(key)) return [];
    const entry = this.data.get(key)!;
    if (entry.type !== "stream")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );

    let count = Infinity;
    for (let i = 0; i < rest.length; i++) {
      if (rest[i]?.toUpperCase() === "COUNT")
        count = Number(rest[i + 1] ?? Infinity);
    }

    const lo = reverse ? end : start;
    const hi = reverse ? start : end;

    let entries = entry.value.filter((e) => {
      const gtLo = lo === "-" || this.compareStreamIds(e.id, lo) >= 0;
      const ltHi = hi === "+" || this.compareStreamIds(e.id, hi) <= 0;
      return gtLo && ltHi;
    });

    if (reverse) entries = entries.slice().reverse();
    if (isFinite(count)) entries = entries.slice(0, count);
    return this.formatStreamEntries(entries);
  }

  private cmdXRead(args: string[]): unknown {
    let i = 0;
    let count = Infinity;

    while (i < args.length) {
      const tok = args[i]!.toUpperCase();
      if (tok === "COUNT") {
        count = Number(args[++i]);
        i++;
      } else if (tok === "BLOCK") {
        i += 2;
      } else if (tok === "STREAMS") {
        i++;
        break;
      } else i++;
    }

    const remaining = args.slice(i);
    const half = Math.floor(remaining.length / 2);
    const keys = remaining.slice(0, half);
    const ids = remaining.slice(half);

    const result: unknown[] = [];
    for (let k = 0; k < keys.length; k++) {
      const key = keys[k]!;
      const afterId = ids[k] ?? "0";
      if (this.isExpired(key) || !this.data.has(key)) continue;
      const entry = this.data.get(key)!;
      if (entry.type !== "stream") continue;
      let entries = this.streamIdAfter(entry.value, afterId);
      if (isFinite(count)) entries = entries.slice(0, count);
      if (entries.length > 0)
        result.push([key, this.formatStreamEntries(entries)]);
    }

    return result.length > 0 ? result : null;
  }

  private cmdXReadGroup(args: string[]): RedisCommandResult {
    const groupIndex = args.findIndex((a) => a.toUpperCase() === "GROUP");
    const streamsIndex = args.findIndex((a) => a.toUpperCase() === "STREAMS");
    const countIndex = args.findIndex((a) => a.toUpperCase() === "COUNT");
    if (groupIndex !== 0 || streamsIndex < 3) throw new Error("ERR invalid XREADGROUP arguments");
    const groupName = args[1]!;
    const consumer = args[2]!;
    const rest = args.slice(streamsIndex + 1);
    if (!rest.length || rest.length % 2) throw new Error("ERR unbalanced streams and IDs");
    const half = rest.length / 2;
    const count = countIndex < 0 ? Infinity : Number(args[countIndex + 1]);
    if (!(count > 0)) throw new Error("ERR invalid COUNT");
    const noack = args.slice(3, streamsIndex).some((a) => a.toUpperCase() === "NOACK");
    const result: unknown[] = [];
    for (let i = 0; i < half; i++) {
      const key = rest[i]!;
      const id = rest[i + half]!;
      const entry = this.isExpired(key) ? undefined : this.data.get(key);
      if (entry && entry.type !== "stream") throw new Error("WRONGTYPE expected stream");
      const group = entry?.groups[groupName];
      if (!entry || !group) throw new Error(`NOGROUP ${groupName} for ${key}`);
      const messages = id === ">"
        ? this.streamIdAfter(entry.value, group.lastDeliveredId).slice(0, count)
        : this.streamIdAfter(entry.value, id).filter((message) =>
          group.pending.some((p) => p.id === message.id && p.consumer === consumer)).slice(0, count);
      if (!messages.length) continue;
      const now = Date.now();
      group.consumers[consumer] = { name: consumer, lastSeenAt: now };
      for (const message of messages) {
        const pending = group.pending.find((p) => p.id === message.id);
        if (pending) { pending.deliveredAt = now; pending.count++; }
        else if (!noack) group.pending.push({ id: message.id, consumer, deliveredAt: now, count: 1 });
      }
      if (id === ">") group.lastDeliveredId = messages.at(-1)!.id;
      this.dirty = true;
      result.push([key, this.formatStreamEntries(messages)]);
    }
    return result.length ? result : null;
  }

  private cmdXDel(args: string[]): number {
    const [key, ...ids] = args;
    if (!key || ids.length === 0)
      throw new Error("ERR wrong number of arguments for 'xdel'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "stream")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const idSet = new Set(ids);
    const before = entry.value.length;
    entry.value = entry.value.filter((e) => !idSet.has(e.id));
    const removed = before - entry.value.length;
    if (removed > 0) this.dirty = true;
    return removed;
  }

  private cmdXAck(args: string[]): number {
    const [key, group, ...ids] = args;
    if (!key || !group || ids.length === 0)
      throw new Error("ERR wrong number of arguments for 'xack'");
    if (this.isExpired(key) || !this.data.has(key)) return 0;
    const entry = this.data.get(key)!;
    if (entry.type !== "stream")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const grp = entry.groups[group];
    if (!grp) return 0;
    const before = grp.pending.length;
    const idSet = new Set(ids);
    grp.pending = grp.pending.filter((p) => !idSet.has(p.id));
    return before - grp.pending.length;
  }

  private cmdXGroup(args: string[]): RedisCommandResult {
    const [subcmd, key, ...rest] = args;
    if (!subcmd || !key)
      throw new Error("ERR wrong number of arguments for 'xgroup'");
    const sub = subcmd.toUpperCase();

    if (sub === "CREATE") {
      const [group, id, ...flags] = rest;
      if (!group)
        throw new Error("ERR wrong number of arguments for 'xgroup|create'");
      const mkStream = flags.map((f) => f.toUpperCase()).includes("MKSTREAM");
      if (this.isExpired(key) || !this.data.has(key)) {
        if (!mkStream)
          throw new Error(
            `ERR The XGROUP subcommand requires the key to exist`,
          );
        this.getOrCreateStream(key);
      }
      const entry = this.data.get(key)!;
      if (entry.type !== "stream")
        throw new Error(
          "WRONGTYPE Operation against a key holding the wrong kind of value",
        );
      entry.groups[group] = {
        lastDeliveredId: id === "$" ? (entry.value.at(-1)?.id ?? "0-0") : (id ?? "0-0"),
        pending: [],
        consumers: {},
      };
      this.dirty = true;
      return "OK";
    }

    if (sub === "SETID") {
      const [group, id] = rest;
      if (!group || id === undefined)
        throw new Error("ERR wrong number of arguments for 'xgroup|setid'");
      if (this.isExpired(key) || !this.data.has(key))
        throw new Error("ERR no such key");
      const entry = this.data.get(key)!;
      if (entry.type !== "stream")
        throw new Error(
          "WRONGTYPE Operation against a key holding the wrong kind of value",
        );
      const grp = entry.groups[group];
      if (!grp)
        throw new Error(
          `ERR -NOGROUP No such consumer group '${group}' for key name '${key}'`,
        );
      grp.lastDeliveredId = id;
      this.dirty = true;
      return "OK";
    }

    if (sub === "DESTROY") {
      const [group] = rest;
      if (!group)
        throw new Error("ERR wrong number of arguments for 'xgroup|destroy'");
      if (this.isExpired(key) || !this.data.has(key)) return 0;
      const entry = this.data.get(key)!;
      if (entry.type !== "stream")
        throw new Error(
          "WRONGTYPE Operation against a key holding the wrong kind of value",
        );
      if (!entry.groups[group]) return 0;
      delete entry.groups[group];
      this.dirty = true;
      return 1;
    }

    if (sub === "CREATECONSUMER") {
      const [group, consumer] = rest;
      if (!group || !consumer)
        throw new Error(
          "ERR wrong number of arguments for 'xgroup|createconsumer'",
        );
      if (this.isExpired(key) || !this.data.has(key))
        throw new Error("ERR no such key");
      const entry = this.data.get(key)!;
      if (entry.type !== "stream")
        throw new Error(
          "WRONGTYPE Operation against a key holding the wrong kind of value",
        );
      const grp = entry.groups[group];
      if (!grp)
        throw new Error(
          `ERR -NOGROUP No such consumer group '${group}' for key name '${key}'`,
        );
      if (grp.consumers[consumer]) return 0;
      grp.consumers[consumer] = { name: consumer, lastSeenAt: Date.now() };
      this.dirty = true;
      return 1;
    }

    if (sub === "DELCONSUMER") {
      const [group, consumer] = rest;
      if (!group || !consumer)
        throw new Error(
          "ERR wrong number of arguments for 'xgroup|delconsumer'",
        );
      if (this.isExpired(key) || !this.data.has(key)) return 0;
      const entry = this.data.get(key)!;
      if (entry.type !== "stream")
        throw new Error(
          "WRONGTYPE Operation against a key holding the wrong kind of value",
        );
      const grp = entry.groups[group];
      if (!grp || !grp.consumers[consumer]) return 0;
      const pendingCount = grp.pending.filter(
        (p) => p.consumer === consumer,
      ).length;
      grp.pending = grp.pending.filter((p) => p.consumer !== consumer);
      delete grp.consumers[consumer];
      this.dirty = true;
      return pendingCount;
    }

    throw new Error(`ERR unknown subcommand '${subcmd}' for 'xgroup'`);
  }

  private cmdXClaim(args: string[]): unknown[] {
    const [key, groupName, consumer, minIdleRaw, ...rest] = args;
    if (!key || !groupName || !consumer || minIdleRaw === undefined) {
      throw new Error("ERR wrong number of arguments for 'xclaim'");
    }
    const minIdle = Number(minIdleRaw);
    if (!Number.isSafeInteger(minIdle) || minIdle < 0) {
      throw new Error("ERR invalid min-idle-time");
    }

    const optionNames = new Set(["IDLE", "TIME", "RETRYCOUNT", "FORCE", "JUSTID"]);
    const ids: string[] = [];
    let optionIndex = 0;
    while (optionIndex < rest.length &&
           !optionNames.has(rest[optionIndex]!.toUpperCase())) {
      ids.push(rest[optionIndex++]!);
    }
    if (ids.length === 0 || ids.some((id) => !/^\d+-\d+$/.test(id))) {
      throw new Error("ERR invalid stream ID");
    }

    let idleOverride: number | undefined;
    let timeOverride: number | undefined;
    let retryCount: number | undefined;
    let force = false;
    let justId = false;
    while (optionIndex < rest.length) {
      const option = rest[optionIndex++]!.toUpperCase();
      if (option === "FORCE") {
        force = true;
      } else if (option === "JUSTID") {
        justId = true;
      } else if (option === "IDLE" || option === "TIME" || option === "RETRYCOUNT") {
        const raw = rest[optionIndex++];
        if (raw === undefined || !/^\d+$/.test(raw)) {
          throw new Error(`ERR ${option} requires a non-negative integer`);
        }
        const value = Number(raw);
        if (!Number.isSafeInteger(value)) {
          throw new Error(`ERR ${option} is out of range`);
        }
        if (option === "IDLE") idleOverride = value;
        else if (option === "TIME") timeOverride = value;
        else retryCount = value;
      } else {
        throw new Error(`ERR unsupported XCLAIM option '${option}'`);
      }
    }
    if (idleOverride !== undefined && timeOverride !== undefined) {
      throw new Error("ERR IDLE and TIME cannot be used together");
    }

    if (this.isExpired(key) || !this.data.has(key)) return [];
    const entry = this.data.get(key)!;
    if (entry.type !== "stream") {
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    }
    const group = entry.groups[groupName];
    if (!group) {
      throw new Error(
        `NOGROUP No such key '${key}' or consumer group '${groupName}'`,
      );
    }

    const now = Date.now();
    const claimed: StreamItem[] = [];
    let changed = false;
    for (const id of ids) {
      let pendingIndex = group.pending.findIndex((pending) => pending.id === id);
      let pending = pendingIndex >= 0 ? group.pending[pendingIndex] : undefined;
      const message = entry.value.find((item) => item.id === id);

      if (!pending && force && message) {
        pending = {
          id,
          consumer,
          deliveredAt: now,
          count: 0,
        };
        group.pending.push(pending);
        pendingIndex = group.pending.length - 1;
        changed = true;
      }
      if (!pending) continue;
      if (!message) {
        group.pending.splice(pendingIndex, 1);
        changed = true;
        continue;
      }
      if (now - pending.deliveredAt < minIdle) continue;

      pending.consumer = consumer;
      pending.deliveredAt = timeOverride ?? (
        idleOverride === undefined ? now : now - idleOverride
      );
      pending.count = retryCount ?? (justId ? pending.count : pending.count + 1);
      group.consumers[consumer] = { name: consumer, lastSeenAt: now };
      claimed.push(message);
      changed = true;
    }
    if (changed) this.dirty = true;
    return justId
      ? claimed.map((message) => message.id)
      : this.formatStreamEntries(claimed);
  }

  private cmdXAutoClaim(args: string[]): unknown[] {
    const [key, groupName, consumer, minIdleRaw, start, ...rest] = args;
    if (!key || !groupName || !consumer || minIdleRaw === undefined || !start) {
      throw new Error("ERR wrong number of arguments for 'xautoclaim'");
    }
    const minIdle = Number(minIdleRaw);
    if (!Number.isSafeInteger(minIdle) || minIdle < 0) {
      throw new Error("ERR invalid min-idle-time");
    }
    if (!/^\d+-\d+$/.test(start)) throw new Error("ERR invalid stream ID");

    let count = 100;
    let justId = false;
    for (let i = 0; i < rest.length; i++) {
      const option = rest[i]!.toUpperCase();
      if (option === "JUSTID") {
        justId = true;
      } else if (option === "COUNT") {
        const raw = rest[++i];
        if (raw === undefined || !/^\d+$/.test(raw)) {
          throw new Error("ERR COUNT requires a positive integer");
        }
        count = Number(raw);
        if (!Number.isSafeInteger(count) || count < 1) {
          throw new Error("ERR COUNT requires a positive integer");
        }
      } else {
        throw new Error(`ERR unsupported XAUTOCLAIM option '${option}'`);
      }
    }

    if (this.isExpired(key) || !this.data.has(key)) return ["0-0", [], []];
    const entry = this.data.get(key)!;
    if (entry.type !== "stream") {
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    }
    const group = entry.groups[groupName];
    if (!group) {
      throw new Error(
        `NOGROUP No such key '${key}' or consumer group '${groupName}'`,
      );
    }

    const pending = group.pending
      .filter((item) => this.compareStreamIds(item.id, start) >= 0)
      .sort((a, b) => this.compareStreamIds(a.id, b.id));
    const scanLimit = count * 10;
    const now = Date.now();
    const claimed: StreamItem[] = [];
    const deletedIds: string[] = [];
    let scanned = 0;
    let changed = false;

    for (const item of pending) {
      if (scanned >= scanLimit || claimed.length >= count) break;
      scanned++;
      const message = entry.value.find((candidate) => candidate.id === item.id);
      if (!message) {
        const pendingIndex = group.pending.indexOf(item);
        if (pendingIndex >= 0) group.pending.splice(pendingIndex, 1);
        deletedIds.push(item.id);
        changed = true;
        continue;
      }
      if (now - item.deliveredAt < minIdle) continue;

      item.consumer = consumer;
      item.deliveredAt = now;
      if (!justId) item.count++;
      claimed.push(message);
      changed = true;
    }

    if (claimed.length > 0) {
      group.consumers[consumer] = { name: consumer, lastSeenAt: now };
    }
    if (changed) this.dirty = true;

    const nextPending = pending[scanned];
    const nextStart = nextPending ? nextPending.id : "0-0";
    const result = justId
      ? claimed.map((message) => message.id)
      : this.formatStreamEntries(claimed);
    return [nextStart, result, deletedIds];
  }

  private cmdXPending(args: string[]): unknown {
    const [key, group] = args;
    if (!key || !group)
      throw new Error("ERR wrong number of arguments for 'xpending'");
    if (this.isExpired(key) || !this.data.has(key)) return [0, null, null, []];
    const entry = this.data.get(key)!;
    if (entry.type !== "stream")
      throw new Error(
        "WRONGTYPE Operation against a key holding the wrong kind of value",
      );
    const grp = entry.groups[group];
    if (!grp || grp.pending.length === 0) return [0, null, null, []];
    const ids = grp.pending
      .map((p) => p.id)
      .sort((a, b) => this.compareStreamIds(a, b));
    return [grp.pending.length, ids[0], ids[ids.length - 1], []];
  }

  private cmdXInfo(args: string[]): unknown {
    const [subcmd, key, group] = args;
    if (!subcmd || !key)
      throw new Error("ERR wrong number of arguments for 'xinfo'");
    const sub = subcmd.toUpperCase();

    if (sub === "STREAM") {
      const len = this.cmdXLen([key]);
      const entry =
        !this.isExpired(key) && this.data.has(key) ? this.data.get(key)! : null;
      const stream = entry?.type === "stream" ? entry : null;
      const first = stream?.value[0] ?? null;
      const last = stream?.value[stream.value.length - 1] ?? null;
      return [
        "length",
        len,
        "radix-tree-keys",
        1,
        "radix-tree-nodes",
        2,
        "last-generated-id",
        last ? last.id : "0-0",
        "max-deleted-entry-id",
        "0-0",
        "entries-added",
        len,
        "recorded-first-entry-id",
        first ? first.id : "0-0",
        "first-entry",
        first ? [first.id, first.fields] : null,
        "last-entry",
        last ? [last.id, last.fields] : null,
        "groups",
        stream ? Object.keys(stream.groups).length : 0,
      ];
    }

    if (sub === "GROUPS") {
      if (this.isExpired(key) || !this.data.has(key)) return [];
      const entry = this.data.get(key)!;
      if (entry.type !== "stream")
        throw new Error(
          "WRONGTYPE Operation against a key holding the wrong kind of value",
        );
      return Object.values(entry.groups).map((g) => [
        "name",
        Object.keys(entry.groups).find((k) => entry.groups[k] === g) ?? "",
        "consumers",
        Object.keys(g.consumers).length,
        "pending",
        g.pending.length,
        "last-delivered-id",
        g.lastDeliveredId,
        "entries-read",
        0,
        "lag",
        0,
      ]);
    }

    if (sub === "CONSUMERS") {
      if (!group)
        throw new Error("ERR wrong number of arguments for 'xinfo|consumers'");
      if (this.isExpired(key) || !this.data.has(key)) return [];
      const entry = this.data.get(key)!;
      if (entry.type !== "stream")
        throw new Error(
          "WRONGTYPE Operation against a key holding the wrong kind of value",
        );
      const grp = entry.groups[group];
      if (!grp) return [];
      const now = Date.now();
      return Object.values(grp.consumers).map((c) => [
        "name",
        c.name,
        "pending",
        grp.pending.filter((p) => p.consumer === c.name).length,
        "idle",
        now - c.lastSeenAt,
        "inactive",
        now - c.lastSeenAt,
      ]);
    }

    if (sub === "HELP") {
      return ["STREAM <key>", "GROUPS <key>", "CONSUMERS <key> <groupname>"];
    }

    throw new Error(`ERR unknown subcommand '${subcmd}' for 'xinfo'`);
  }

  // ============================================================================
  // OBJECT COMMAND (BullMQ uses OBJECT ENCODING)
  // ============================================================================

  private cmdObject(args: string[]): RedisCommandResult {
    const [subcmd, key] = args;
    if (!subcmd) throw new Error("ERR wrong number of arguments for 'object'");
    const sub = subcmd.toUpperCase();

    if (sub === "ENCODING") {
      if (!key || this.isExpired(key) || !this.data.has(key))
        throw new Error("ERR no such key");
      const entry = this.data.get(key)!;
      switch (entry.type) {
        case "string": {
          const n = Number(entry.value);
          if (!isNaN(n) && Number.isInteger(n)) return "int";
          return entry.value.length <= 44 ? "embstr" : "raw";
        }
        case "list":
          return entry.value.length <= 128 ? "listpack" : "quicklist";
        case "hash":
          return Object.keys(entry.value).length <= 128
            ? "listpack"
            : "hashtable";
        case "set":
          return entry.value.length <= 128 ? "listpack" : "hashtable";
        case "zset":
          return entry.value.length <= 128 ? "listpack" : "skiplist";
        case "stream":
          return "stream";
        default:
          return "raw";
      }
    }

    if (sub === "REFCOUNT") {
      if (!key || this.isExpired(key) || !this.data.has(key))
        throw new Error("ERR no such key");
      return 1;
    }

    if (sub === "IDLETIME") {
      if (!key || this.isExpired(key) || !this.data.has(key))
        throw new Error("ERR no such key");
      return 0;
    }

    if (sub === "FREQ") {
      if (!key || this.isExpired(key) || !this.data.has(key))
        throw new Error("ERR no such key");
      return 0;
    }

    if (sub === "HELP") {
      return [
        "ENCODING <key>",
        "REFCOUNT <key>",
        "IDLETIME <key>",
        "FREQ <key>",
      ];
    }

    throw new Error(`ERR unknown subcommand '${subcmd}' for 'object'`);
  }
}

/**
 * PDIM HTTP Redis Adapter
 *
 * Wraps the Pocket Dimension / Redis replacement server's HTTP exec endpoint
 * with a full ioredis-compatible interface. Any code that calls getRedisClient()
 * transparently receives this adapter when PDIM_HTTP_EXEC_URL is set.
 *
 * env vars consumed:
 *   PDIM_HTTP_EXEC_URL  — https://…/api/redis/instances/{id}/exec
 *   PDIM_BEARER_TOKEN   — Bearer auth token
 */

import { EventEmitter } from "events";
import os from "os";
import { logger } from "../logger.js";
import { loopbackUrl, runtimePorts } from "../config/ports.js";
import { execLuaViaPdim } from "./luaExecutor.js";
import { cbAllowRequest, cbRecordFailure as cbRecord503, cbRecordSuccess, cbHalfOpenFailed, cbForceClose, cbGetState } from "./pdimCircuitBreaker.js";

// ── Adaptive PDIM Rate Limiter (AIMD) ────────────────────────────────────────
// "Fluid like water: easy to contain but expands freely when userbase expands."
//
// Uses AIMD — the same Additive Increase / Multiplicative Decrease algorithm
// as TCP congestion control — applied to the inter-request gap:
//
//   Success  → gap -= STEP  (additive decrease: throughput ramps up gradually)
//   HTTP 429 → gap *= MULT  (multiplicative increase: immediate hard back-off)
//   Demand   → STEP × 3    (when callers are queued, ramp-up accelerates 3×)
//
// This makes the rate limiter self-tuning:
//   • At rest (1–2 callers): gap drifts toward floor — maximum efficiency
//   • Under load (many callers queued): gap falls 3× faster — serves demand
//   • After a 429: gap jumps to 2.5× — backs off faster than a single retry cycle
//   • Sustained 429s: gap compounds (500 → 1250 → 3125 → ...) up to CEIL
//   • After recovery: gap ramps smoothly back down to floor
//
// All PDIM HTTP requests, from every code path (direct calls, LuaExecutor
// redis.call(), BZPOPMIN polling), are serialized through this single chain.
// At most ONE request is in-flight at any time, with an adaptive gap between
// completions.  There is no static global concurrency cap — the chain itself
// guarantees sequential execution.

// ── Auto multiplier ───────────────────────────────────────────────────────────
// Target scale: 120 million long-term concurrent users.
//
// Max Booster deploys to VM Reserve and connects to PDIM via Redis-compatible
// URLs.  PDIM runs its own auto-scale cluster (effectively no cluster limit),
// so Max Booster transparently benefits from PDIM's cluster capacity without
// managing any workers itself.
//
// Two dimensions determine how many concurrent callers are hitting the PDIM
// chain from this side:
//
//   1. PDIM cluster workers  — PDIM cluster nodes serving this instance
//      (set via PDIM_CLUSTER_WORKERS; defaults to 1, grows as PDIM auto-scales)
//   2. CPU cores on the VM   — more cores → more concurrent microtask paths
//      competing for the shared HTTP chain simultaneously
//
// Formula:  autoMultiplier = clusterWorkers × ceil(cpuCores / 2)
//
//   VM Reserve, 8 cores,  1 PDIM worker :  1 × ceil(8/2)  =  1 × 4 = 4
//     → AIMD init=1ms, ZPOPMIN gap = 4 ms   (~250 polls/sec)
//   VM Reserve, 8 cores,  6 PDIM workers:  6 × 4 = 24
//     → AIMD init=1ms, ZPOPMIN gap = 24 ms  (~42 polls/sec per worker)
//   VM Reserve, 16 cores, 12 PDIM workers: 12 × 8 = 96
//     → AIMD init=1ms, ZPOPMIN gap = 96 ms  (~10 polls/sec per worker)
//
// PDIM is rated 120M req/s — no artificial floor.  Under load the AIMD gap
// self-tunes via demand/backoff steps.  At rest it drifts up gently (1ms/step)
// so the system stays quiet.  The multiplier gives per-worker jitter only.
//
const clusterWorkers = Math.max(
  1,
  parseInt(process.env.PDIM_CLUSTER_WORKERS ?? "1", 10),
);
const cpuCores = Math.max(1, os?.cpus().length);
const autoMultiplier = clusterWorkers * Math.max(1, Math.ceil(cpuCores / 2));

// ── AIMD parameters ──────────────────────────────────────────────────────────
//
// Worker-count-aware floor (defined before the logger so the logger can print it).
//
// Root cause of sustained 429 floods in production:
//   In a multi-worker deployment (e.g. PDIM_CLUSTER_WORKERS=13) each Node?.js
//   cluster worker has its own AIMD state.  A floor of 1ms means each worker
//   eventually ramps back down to 1ms after backing off.  With 13 workers all
//   at 1ms simultaneously the combined rate = 13,000 req/s — far above PDIM's
//   per-instance limit (~250–500 req/s), causing relentless 429 cycling.
//
// Fix: floor = clusterWorkers × BASE_MS so that combined steady-state rate
//   ≈ 1000/BASE req/s regardless of how many workers are running.
//
// BASE was 4ms (combined 250 req/s) but production 429 storms continued: prod
// logs showed waves of `gap→102-148ms` and `gap→102-319ms` 429s where the
// pre-multiplier gap was ~50ms — i.e. workers were sitting AT the 52ms floor
// when PDIM rejected them.  Empirical evidence: PDIM's real per-instance
// limit is BELOW the 250 req/s the 4ms base produced, ESPECIALLY now that the
// script-chain split makes direct and script chains run concurrently per
// worker (shared 429 throttle via _rateLimitedUntil only engages AFTER a 429,
// not as a budget ceiling).
//
// BASE=10ms (combined ~100 req/s) overcorrected: prod chain depth grew to
// 29,000+ callers because steady-state arrival rate exceeded the throttled
// drain rate, sessions timed out, login broke.  BASE=4ms (combined ~250) had
// the opposite problem — burst 429s — but kept up with steady-state.
//
// Middle ground: BASE=6ms → ~167 combined req/s for the direct chain.
//   Dev (1 worker):     floor = 6ms  — negligible latency.
//   Prod (13 workers):  floor = 78ms each → ~167 req/s combined direct.
//   Margin: ~30% below the empirical 429 trigger, ~70% above the starved-drain
//   threshold where chain depth grew unbounded.
//
// CEIL: 2000ms — ceiling after sustained 429 cascade.
// INIT: 1ms    — still start at minimum; AIMD+jitter ramp up naturally.
//
// Scripts (BullMQ Lua redis?.call()s) use the _enqueueScriptExec fast-lane
// (10ms gap, dedicated chain) and are NOT subject to this floor.  Their
// throughput is bounded indirectly: any 429 they receive raises
// _rateLimitedUntil which BOTH chains honour on the next call.
const _PDIM_GAP_FLOOR_BASE_MS = 6;
const _PDIM_GAP_FLOOR_WORKER_MIN = Math.max(
  _PDIM_GAP_FLOOR_BASE_MS,
  clusterWorkers * _PDIM_GAP_FLOOR_BASE_MS,
);
let _PDIM_GAP_FLOOR_MS = _PDIM_GAP_FLOOR_WORKER_MIN;
const _PDIM_GAP_CEIL_MS = 2_000;
const _PDIM_GAP_INIT_MS = 1; // start at minimum — AIMD self-tunes from here
// 2.5× matches the research-backed AIMD recommendation: aggressive multiplicative
// decrease so the ceiling is reached in ~9 consecutive 429s instead of ~60.
// With 1.5× the gap grows: 1ms→1.5→2.25→…→2000ms (60 steps).
// With 2.5×: 1ms→2.5→6.25→15.6→39→97→244→610→1525→ceil (9 steps).
// Recovery is still smooth: additive increase on success (1-100ms step).
const _PDIM_MULT_429 = 2.5;

logger.info(
  `[PDIM] Auto multiplier: ${autoMultiplier} ` +
    `(clusterWorkers=${clusterWorkers} × ceil(cpuCores=${cpuCores}/2)=` +
    `${Math.max(1, Math.ceil(cpuCores / 2))}) — ` +
    `AIMD init=1ms, floor=${_PDIM_GAP_FLOOR_MS}ms (${clusterWorkers}workers×${_PDIM_GAP_FLOOR_BASE_MS}ms, combined≤${Math.round(1000 / _PDIM_GAP_FLOOR_BASE_MS)} req/s), ` +
    `ZPOPMIN gap=${Math.max(1, autoMultiplier)}ms`,
);

/** Permanently raise the PDIM gap floor — called by PermanentFixRegistry on startup
 *  and after each escalation.  Floor can only move upward (min = worker-count-scaled
 *  minimum, max 2 000 ms) so external callers can never accidentally lower the floor
 *  below the safe per-worker minimum derived from clusterWorkers.
 *  Applies only to direct PDIM calls; BullMQ Lua scripts use the 10ms fast-lane. */
export function setPdimGapFloor(ms: number): void {
  // Never allow floor to drop below the worker-count-aware minimum.
  _PDIM_GAP_FLOOR_MS = Math.max(
    _PDIM_GAP_FLOOR_WORKER_MIN,
    Math.min(2_000, Math.round(ms)),
  );
  // If the live gap is below the new floor, snap it up immediately so the change
  // takes effect on the very next enqueued request without waiting for AIMD.
  if (_pdimGapMs < _PDIM_GAP_FLOOR_MS) _pdimGapMs = _PDIM_GAP_FLOOR_MS;
}

export function getPdimGapFloor(): number {
  return _PDIM_GAP_FLOOR_MS;
}

// ── AIMD state (module-level, shared across all PdimRedisClient instances) ───
//
// Per-process startup desynchronization.
// Production autoscale runs 10–15 worker processes that all start at approximately
// the same time.  Without jitter every process fires PDIM requests in lockstep:
// they back off together after a 429, wait the same duration, and retry together —
// a thundering herd that repeats indefinitely regardless of the AIMD ceiling.
//
// Fix: initialise each process's gap with a random offset in [0, JITTER_INIT_MS).
// Workers drift apart within the first AIMD cycle and never re-synchronise because
// each subsequent 429 backoff also adds a random fraction (see _pdimAdapt429).
// In single-worker dev there is no thundering herd risk — jitter only matters
// when multiple workers start simultaneously.  Start dev at the minimum gap so
// the first ~40s of passive decay aren't wasted recovering from a jitter spike.
const _PDIM_JITTER_INIT_MS = clusterWorkers <= 1 ? 0 : 1_500;
let _pdimGapMs =
  _PDIM_GAP_INIT_MS + Math.floor(Math.random() * _PDIM_JITTER_INIT_MS);
let _pdimQueueDepth = 0; // callers waiting in the chain (not yet executing)

// ── Parallel direct-call lanes ───────────────────────────────────────────────
// Previously a single _pdimGlobalChain serialized every direct PDIM call in this
// process.  At RTT≈80ms + AIMD gap, single-lane throughput is ~11 ops/sec.  Under
// sustained background load (audit pump, presence, session writes, multiple
// autonomous schedulers) arrivals exceed that, the chain saturates, and the
// fast-fail boundary (417 callers at gap=6ms) becomes the steady-state depth —
// every new direct caller fast-fails to PG/in-memory fallback.
//
// PDIM handles concurrent connections; the script chain already runs in parallel
// with the direct chain (see _pdimScriptChain).  Splitting direct calls across N
// parallel lanes multiplies throughput by N while preserving AIMD correctness:
//   • _pdimGapMs, _rateLimitedUntil, _pdimAdaptSuccess/429 are all global; every
//     lane reads the same gap and honours the same rate-limit deadline.
//   • Per-lane gap still enforces spacing within a lane; N lanes × (1/(RTT+gap))
//     is the new combined throughput per worker.
//   • Combined cluster-wide rate stays within PDIM's per-instance limit because
//     the worker-count-aware floor (_PDIM_GAP_FLOOR_WORKER_MIN) already scales
//     with worker count.  Dev: 4 lanes × 1 worker × 1000/(4+80) ≈ 47 req/s.
//     Prod: 2 lanes × 13 workers × 1000/(52+80) ≈ 197 req/s combined.
//
// Dev uses 8 lanes (increased from 4) because dev background load (BullMQ workers,
// session store, audit pump, presence, HyperLearning, PlatformAutoFixer) generates
// 200-210 direct callers simultaneously at startup.  With 4 lanes and cap=48ms
// the estimate is 204/4×48=2448ms — within 52ms of the fast-fail threshold and
// occasionally over with bursts to 209.  8 lanes halves the per-lane depth:
// 209/8×48=1254ms — well clear of the 2500ms threshold with full burst headroom.
// Prod uses 2 lanes/worker to stay modest per-worker.
const _PDIM_DIRECT_LANES = clusterWorkers <= 1 ? 8 : 2;
const _pdimDirectChains: Promise<unknown>[] = Array.from(
  { length: _PDIM_DIRECT_LANES },
  () => Promise.resolve(),
);
let _pdimDirectLaneRR = 0; // round-robin index into _pdimDirectChains
// Dedicated chain for LuaExecutor script redis.call()s — kept separate from the
// AIMD direct-call chain so that script Workers are NEVER blocked behind hundreds
// of direct callers waiting on the 2000ms AIMD gap.  429 protection is still
// enforced because _rateLimitedUntil is checked inside every exec() invocation
// (inside fn()) before the HTTP request is sent.  Both chains can fire one request
// concurrently, which is fine — PDIM handles concurrent connections.
let _pdimScriptChain: Promise<unknown> = Promise.resolve();

// ── Per-category queue depth tracking ────────────────────────────────────────
// Direct calls (sessions, cache, rate-limiting) and script fast-lane calls
// share the same global chain but use very different gaps (AIMD gap vs 10ms).
// Tracking them separately lets _enqueueExec estimate the real wait time for
// a new user-facing call and fast-fail when that wait would exceed the threshold.
let _directQueueDepth = 0; // non-script callers currently in the chain
let _scriptQueueDepth = 0; // LuaExecutor redis.call() callers in the chain

// Maximum estimated queue wait before a direct (user-facing) call is fast-failed.
//
// Previously set to MAX_SAFE_INTEGER (fast-fail disabled) on the theory that
// the chain never stalls.  Production proved otherwise: when PDIM throughput
// gets throttled (raised gap floor, sustained 429 backoff, or PDIM-side
// slowdown) the chain depth can grow to 29,000+ callers in minutes.  Session
// fetches that get stuck in that queue time out and login breaks — even though
// the PG fallback path would have returned in <50ms had it been allowed to run.
//
// 2500ms picked so that:
//   • Session fetches fast-fail to PG well before the 5s session probe timeout
//     and well before any user-facing request times out.
//   • Normal-load wait stays comfortably below: at floor=78ms (prod), even a
//     ~30-deep chain (typical busy moment) waits 2340ms — still allowed.
//   • Pathological backups (thousands queued) fail fast so callers with
//     fallbacks (PG-backed session store, in-memory cache) actually USE them.
const _MAX_DIRECT_WAIT_MS = 2_500;

// Log fast-fail events at most once every 5s to avoid flooding the log.
let _fastFailLoggedAt = 0;

/** On each successful PDIM response: shrink the gap proportionally to demand.
 *
 * The step is queue-depth-proportional — "fluid" expansion:
 *   idle  (0–1) : 1 ms  — gap barely moves; conserves PDIM quota at rest
 *   light (2–4) : 5 ms  — gentle ramp for background/internal traffic
 *   busy  (5–9) : 12 ms — moderate ramp for real user sessions
 *   peak  (10+) : 15 ms — conservative ramp; avoids 429-sawtooth overshoot
 *
 * Why the peak step was reduced from 100ms → 15ms:
 *   At queue depth ≥10, a 100ms/success step drops the gap from the 2000ms
 *   ceiling to the 1ms floor in only ~20 requests.  PDIM then returns 429,
 *   the gap jumps back to 2.5ms, and the same 20-request collapse repeats
 *   indefinitely — a 429/sawtooth cycle with no stable equilibrium.
 *   At 15ms/success, the descent from 2000ms takes ~133 requests (~27s at
 *   200ms PDIM RTT), giving PDIM time to signal its true ceiling through a
 *   429 before the floor is reached.
 *
 * The real operational floor is set by PDIM's own 429 responses via
 * _pdimAdapt429() — not by the constant _PDIM_GAP_FLOOR_MS.
 */
function _pdimAdaptSuccess(): void {
  const q = _pdimQueueDepth;
  const step = q >= 10 ? 15 : q >= 5 ? 12 : q >= 2 ? 5 : 1;
  _pdimGapMs = Math.max(_PDIM_GAP_FLOOR_MS, _pdimGapMs - step);
}

/** On each 429 response: multiply the gap (back off hard) and return new gap
 *  so exec() can set the static rate-limit deadline to the same value.
 *
 *  Jitter rationale: without jitter, all autoscale workers that backed off to
 *  the same ceiling (2000ms) will all retry at exactly the same wall-clock time,
 *  re-triggering a synchronized 429 storm.  Adding ±25% random noise to each
 *  backoff step ensures processes drift apart within 2–3 cycles and stay apart. */
function _pdimAdapt429(): number {
  const jitter = 0.75 + Math.random() * 0.5; // uniform [0.75, 1.25]
  _pdimGapMs = Math.min(
    _PDIM_GAP_CEIL_MS,
    _pdimGapMs * _PDIM_MULT_429 * jitter,
  );
  _last429At = Date?.now();
  return _pdimGapMs;
}

/**
 * On a PDIM timeout (AbortSignal timeout — NOT a 429 rate-limit response):
 * apply mild backpressure by bumping the gap by 1 floor-unit, but do NOT
 * set _last429At.  Timeouts mean PDIM is busy/slow; they are NOT rate-limit
 * signals.  The old behaviour of calling _pdimAdapt429() on every timeout
 * was setting _last429At every ~5 seconds, which permanently blocked the
 * passive-decay timer (which requires 5s of 429-quiet to run).  Result: gap
 * pinned at 2000ms ceiling forever, session store unreachable, auth broken.
 */
function _pdimAdaptTimeout(): void {
  // Nudge the gap up very slightly — just enough to acknowledge backpressure
  // without permanently disabling passive decay.  The passive timer (0.8×
  // every 2s, 5s quiet guard) will pull it back to floor within ~30s as long
  // as no real 429s are arriving.
  _pdimGapMs = Math.min(_PDIM_GAP_CEIL_MS, _pdimGapMs + _PDIM_GAP_FLOOR_MS);
  // _last429At is intentionally NOT updated here.
}

/** Wall-clock timestamp of the most recent 429.  Unlike
 *  PdimRedisClient?._rateLimitedUntil (a deadline that gets cleared to 0 on the
 *  next success), this is monotonic and only ever advances on a fresh 429 —
 *  so the passive decay timer can use it as an exact "no 429 in last N ms"
 *  signal.  0 means no 429 has ever been observed in this process. */
let _last429At = 0;

/** Passive geometric decay — runs on a timer, independent of traffic.
 *
 *  Without this, a single 429 burst can pin _pdimGapMs near _PDIM_GAP_CEIL_MS
 *  (2000ms) for many minutes.  Production evidence: a startup-burst 429 at
 *  17:05:39 pushed gap to ~2000ms on multiple workers; 3+ minutes later
 *  workers were still at gap≈1700ms.  Why so slow?
 *
 *  - _pdimAdaptSuccess() step depends on _pdimQueueDepth.  At depth < 2 it
 *    decays only 1ms per successful call.
 *  - When the fast-fail path is active (chain wait > 2500ms), most callers
 *    fall back to PG/in-memory and never enter the chain — so they produce
 *    no success events to drive decay.  Vicious cycle: high gap → fast-fail
 *    → no successes → gap stays high.
 *
 *  Fix: a 2s timer that geometrically pulls gap toward floor whenever no 429
 *  has been observed in the last QUIET_MS window.  PDIM is provably healthy
 *  during such a quiet window, so the elevated gap is over-conservative
 *  regardless of queue depth.
 *
 *  Earlier version gated additionally on `totalDepth < 2` — production
 *  proved that gate wrong: it conflated "load" with "PDIM pressure".  Real
 *  prod fast-fail incidents (deployment logs, May 28) showed pids 221/260/
 *  299/338 each with direct depths of 3–10 callers AND gaps stuck at
 *  500–1900ms for many minutes.  The depth gate blocked passive decay, the
 *  fast-fail prevented new chain entries from generating successes, and the
 *  additive decay (1ms/success at q<2) was effectively zero — gap stayed
 *  pinned far above the floor for the full duration of the incident.
 *
 *  The no-sawtooth invariant is preserved by the 429-recency check alone:
 *  under sustained PDIM pressure 429s keep arriving, _last429At stays
 *  recent, and passive decay defers to additive.  Without recent 429s, the
 *  gap is over-paced by definition. */
const _PASSIVE_DECAY_INTERVAL_MS = 2_000;
const _PASSIVE_DECAY_FACTOR = 0.8;
const _PASSIVE_DECAY_IDLE_QUIET_MS = 5_000;
setInterval(() => {
  if (_pdimGapMs <= _PDIM_GAP_FLOOR_MS) return;
  // Use _last429At (monotonic, only updated on actual 429) rather than
  // _rateLimitedUntil (a deadline that gets cleared to 0 on next success).
  // The latter would let a single success unmask a still-active cascade.
  // `_last429At === 0` means no 429 has ever been observed in this process —
  // treat as "infinitely quiet" so decay still drains startup-jitter init.
  if (_last429At > 0 && Date?.now() - _last429At < _PASSIVE_DECAY_IDLE_QUIET_MS)
    return;
  _pdimGapMs = Math.max(
    _PDIM_GAP_FLOOR_MS,
    Math.floor(_pdimGapMs * _PASSIVE_DECAY_FACTOR),
  );
}, _PASSIVE_DECAY_INTERVAL_MS).unref();

/** Expose live state for diagnostics (ChainFixer, health endpoints). */
export function getPdimAdaptiveGapMs(): number {
  return _pdimGapMs;
}
export function getPdimQueueDepth(): number {
  return _pdimQueueDepth;
}
export function getPdimDirectQueueDepth(): number {
  return _directQueueDepth;
}
export function getPdimScriptQueueDepth(): number {
  return _scriptQueueDepth;
}

/** Allow PlatformAutoFixer to temporarily raise the polling gap under PDIM pressure. */
export function setPdimAdaptiveGap(ms: number): void {
  _pdimGapMs = Math.max(_PDIM_GAP_FLOOR_MS, Math.min(_PDIM_GAP_CEIL_MS, ms));
}

function _enqueueExec(fn: () => Promise<unknown>): Promise<unknown> {
  // ── Fast-fail: protect user-facing callers from unbounded queue waits ────────
  // Estimate how long a new direct caller would wait behind existing queue.
  // Work parallelizes across _PDIM_DIRECT_LANES (round-robin), so a new arrival
  // joins the shortest lane — average per-lane depth is _directQueueDepth/lanes:
  //   per-lane direct wait  = (directDepth / lanes) × AIMD gap
  //   script fast-lane wait = scriptDepth × 10ms  (independent chain)
  // When the combined estimate exceeds _MAX_DIRECT_WAIT_MS, reject immediately
  // so callers with fallbacks (PG-backed sessions, in-memory caches) use them.
  //
  // Gap cap rationale: after a 429 burst, AIMD pushes _pdimGapMs to the 2000ms
  // ceiling. At that ceiling, even 3 callers across 2 lanes exceeds 2500ms
  // (3/2 × 2000 = 3000ms), causing fast-fail on virtually every new caller.
  // This is a vicious cycle: fast-fail prevents success events that drive
  // additive decay, so passive geometric decay (0.8× every 2s, ~30s to floor)
  // becomes the only recovery mechanism — but new callers are rejected the
  // whole time, making PDIM appear completely unavailable during recovery.
  //
  // Fix: cap the gap used for estimation at floor×8. Passive decay brings the
  // real gap down to floor within ~30s regardless, so floor×8 is a conservative
  // upper bound on the actual wait a queued caller will experience.  At prod
  // floor=78ms: cap=624ms, max queue before fast-fail = 8 callers across 2
  // lanes (8/2×624=2496ms < 2500ms).  At normal operation (gap≤floor) there is
  // no change — the cap has no effect.  Callers that ARE queued during recovery
  // wait less than the estimate because the gap is actively falling.
  const gapForFastFail = Math.min(_pdimGapMs, _PDIM_GAP_FLOOR_MS * 8);
  const perLaneDirectWaitMs =
    (_directQueueDepth / _PDIM_DIRECT_LANES) * gapForFastFail;
  const estimatedWaitMs = perLaneDirectWaitMs + _scriptQueueDepth * 10;
  if (estimatedWaitMs > _MAX_DIRECT_WAIT_MS) {
    const now = Date?.now();
    if (now - _fastFailLoggedAt > 5_000) {
      _fastFailLoggedAt = now;
      logger.warn(
        `[PDIM] Direct-call fast-fail — est. queue wait ${Math.round(estimatedWaitMs)}ms ` +
          `(${_directQueueDepth} direct / ${_PDIM_DIRECT_LANES} lanes × ${gapForFastFail}ms capped [live=${_pdimGapMs}ms] + ` +
          `${_scriptQueueDepth} script × 10ms) > ${_MAX_DIRECT_WAIT_MS}ms threshold; ` +
          `caller falls back to PG/in-memory`,
      );
    }
    return Promise?.reject(
      new Error(
        `[PDIM] Chain congested — est. wait ${Math.round(estimatedWaitMs)}ms exceeds ${_MAX_DIRECT_WAIT_MS}ms; use fallback`,
      ),
    );
  }

  _directQueueDepth++;
  _pdimQueueDepth++;
  // Round-robin lane assignment — each enqueue picks the next lane.  Skewed
  // mixes of slow/fast calls (e?.g. one lane stalled on a 429 backoff) still get
  // balanced over time because the RR counter advances regardless of lane state.
  const laneIdx = _pdimDirectLaneRR++ % _PDIM_DIRECT_LANES;
  if (_pdimDirectLaneRR >= 1_000_000) _pdimDirectLaneRR = 0; // prevent integer drift
  const next = _pdimDirectChains[laneIdx]
    .then(async () => {
      _directQueueDepth = Math.max(0, _directQueueDepth - 1);
      _pdimQueueDepth = Math.max(0, _pdimQueueDepth - 1);
      const result = await fn();
      // Adaptive gap fires AFTER the request completes — next caller in THIS lane
      // must wait this long before it starts.  Gap is read at completion time so
      // it reflects any 429-driven adjustment made by the just-completed request.
      // (Other lanes' callers are paced by the same global _pdimGapMs.)
      if (_pdimGapMs > 0) await new Promise((r) => setTimeout(r, _pdimGapMs));
      return result;
    })
    .catch(async (err: unknown) => {
      _directQueueDepth = Math.max(0, _directQueueDepth - 1);
      _pdimQueueDepth = Math.max(0, _pdimQueueDepth - 1);
      // Enforce gap on error too — including 429.  _pdimGapMs has already been
      // updated by _pdimAdapt429() inside exec() before the throw reaches here,
      // so subsequent callers naturally wait the new (larger) gap.
      if (_pdimGapMs > 0) await new Promise((r) => setTimeout(r, _pdimGapMs));
      throw err;
    });
  // Suppress unhandled rejection on the lane tail — each caller handles its own.
  _pdimDirectChains[laneIdx] = next.catch(() => {});
  return next;
}

/**
 * Long-lived blocking commands must not occupy a normal direct-command lane.
 * Producers and Lua callbacks need that lane to mutate the queue and wake them.
 */
function _enqueueBlockingExec<T>(fn: () => Promise<T>): Promise<T> {
  return Promise.resolve().then(fn);
}

// ── Script fast-lane ──────────────────────────────────────────────────────────
// LuaExecutor redis.call()s are already serialized by Atomics.wait() inside the
// Worker thread — each call blocks the Worker until the main thread signals,
// guaranteeing that no two redis.call()s from the same script can overlap.
//
// Using the full AIMD gap (2000ms ceiling) for every redis.call() inside a
// BullMQ script means:
//   35 calls × 2000ms gap = 70s dead-wait — Workers time out at 60s.
//
// Root cause of "redis.call timed out after 60s — PDIM chain congested":
//   At startup, 780+ direct callers are queued in _pdimGlobalChain with the
//   PermanentFixer-restored 2000ms gap.  If scripts share that chain they must
//   wait behind all 780 callers: 780 × (200ms RTT + 2000ms) ≈ 28 minutes.
//   Workers time out at 60s, long before their turn arrives.
//
// Fix: scripts use a DEDICATED _pdimScriptChain that runs independently of the
//   direct-call chain.  Workers never queue behind session-store or cache calls.
//   429 protection is preserved because _rateLimitedUntil is checked inside
//   every exec() call (inside fn()) before the HTTP request is dispatched.
//   Both chains can fire one request concurrently — PDIM handles that fine.
//
// Throughput: 35 calls × (PDIM RTT ≈ 200ms + 10ms gap) = ~7.35s per script.
const _SCRIPT_CALL_GAP_MS = 10;

function _enqueueScriptExec(fn: () => Promise<unknown>): Promise<unknown> {
  // Track both shared and per-category depth so:
  //   • ChainFixer saturation checks remain accurate (script calls count as load)
  //   • _enqueueExec fast-fail calculation uses accurate script count (10ms gap
  //     each, not AIMD gap) so it does not over-estimate the wait time
  _scriptQueueDepth++;
  _pdimQueueDepth++;
  const next = _pdimScriptChain
    .then(async () => {
      _scriptQueueDepth = Math.max(0, _scriptQueueDepth - 1);
      _pdimQueueDepth = Math.max(0, _pdimQueueDepth - 1);
      const result = await fn();
      // 10ms minimal gap — script calls are Atomics-serialized so there is
      // no parallel-call risk; the gap exists only to yield the event loop.
      await new Promise((r) => setTimeout(r, _SCRIPT_CALL_GAP_MS));
      return result;
    })
    .catch(async (err: unknown) => {
      _scriptQueueDepth = Math.max(0, _scriptQueueDepth - 1);
      _pdimQueueDepth = Math.max(0, _pdimQueueDepth - 1);
      await new Promise((r) => setTimeout(r, _SCRIPT_CALL_GAP_MS));
      throw err;
    });
  _pdimScriptChain = next.catch(() => {});
  return next;
}

// ── Exec error log deduplication ─────────────────────────────────────────────
// When PDIM is completely down (e.g. 502 on every call), each exec() logs a
// WARN before the circuit opens.  With 5 failures required before the circuit
// opens and multiple BullMQ workers polling, this produces a burst of identical
// WARNs every time the circuit is force-closed and resets.
//
// Deduplication rules:
//   • First occurrence of a status code: always logged.
//   • Same status code as last logged: suppressed if within DEDUP_WINDOW_MS.
//   • Different status code: always logged (indicates a new condition).
//   • After DEDUP_WINDOW_MS silence, the next occurrence is logged again.
//
// 429 dedup — a burst of simultaneous 429s (e.g. diffusion gateway + main app
// both hitting PDIM at once) can produce 8+ identical warn lines within 700ms.
// Deduplicate within a 2s burst window: log the first occurrence immediately,
// suppress the rest, then flush a "+ N suppressed" summary on the next 429
// that arrives after the window has elapsed or when a non-429 is logged.
// The gap value in each 429 is slightly different (AIMD multiplies it) but the
// actionable signal is "429 received, gap is now X" — the final gap is what
// matters, not the intermediate values during a burst.
const _429_DEDUP_MS = 2_000; // burst window (ms)
let _last429LoggedAt = 0;
let _suppressed429Count = 0;

const _EXEC_DEDUP_WINDOW_MS = 30_000; // 30 s (for 5xx / 3xx errors)
let _lastExecErrorStatus = -1;
let _lastExecErrorLoggedAt = 0;
let _suppressedExecErrors = 0;

function _logExecError(cmd: unknown, status: number, msg: string): void {
  const now = Date.now();
  const withinWindow = now - _lastExecErrorLoggedAt < _EXEC_DEDUP_WINDOW_MS;
  if (withinWindow && status === _lastExecErrorStatus) {
    // Suppress — same error within window.  Periodically emit a summary.
    _suppressedExecErrors++;
    if (_suppressedExecErrors % 20 === 0) {
      logger.warn(
        `[PDIM] exec error [${String(cmd)}]: HTTP ${status} suppressed ×${_suppressedExecErrors} ` +
          `(same error within ${_EXEC_DEDUP_WINDOW_MS / 1000}s window)`,
      );
    }
    return;
  }
  if (_suppressedExecErrors > 0) {
    logger.warn(
      `[PDIM] exec error [${String(cmd)}]: ${msg} ` +
        `(+ ${_suppressedExecErrors} suppressed identical errors)`,
    );
    _suppressedExecErrors = 0;
  } else {
    logger.warn(`[PDIM] exec error [${String(cmd)}]: ${msg}`);
  }
  _lastExecErrorStatus = status;
  _lastExecErrorLoggedAt = now;
}

// ── Network/timeout error dedup (separate from HTTP-status dedup above) ───────
// Timeout and AbortErrors flood when PDIM is overwhelmed: hundreds of queued
// callers each receive a 4 s abort in rapid succession.  Log the first one,
// suppress the rest within the window, then emit a summary count.
const _NET_ERROR_DEDUP_MS = 10_000; // 10 s burst window
let _lastNetErrorMsg = "";
let _lastNetErrorLoggedAt = 0;
let _suppressedNetErrors = 0;

function _logNetworkError(cmd: unknown, msg: string): void {
  const now = Date.now();
  const sameMsg = msg === _lastNetErrorMsg;
  const withinWindow = now - _lastNetErrorLoggedAt < _NET_ERROR_DEDUP_MS;
  if (sameMsg && withinWindow) {
    _suppressedNetErrors++;
    // Emit a periodic summary so the operator knows the burst is ongoing.
    if (_suppressedNetErrors % 50 === 0) {
      logger.warn(
        `[PDIM] exec error [${String(cmd)}]: ${msg} — suppressed ×${_suppressedNetErrors} in last ${_NET_ERROR_DEDUP_MS / 1000}s`,
      );
    }
    return;
  }
  // New message or window elapsed — flush summary then log fresh.
  if (_suppressedNetErrors > 0) {
    logger.warn(
      `[PDIM] exec error [${String(cmd)}]: ${_lastNetErrorMsg} ` +
        `(+ ${_suppressedNetErrors} suppressed in last ${_NET_ERROR_DEDUP_MS / 1000}s)`,
    );
    _suppressedNetErrors = 0;
  } else {
    logger.warn(`[PDIM] exec error [${String(cmd)}]: ${msg}`);
  }
  _lastNetErrorMsg = msg;
  _lastNetErrorLoggedAt = now;
}

// ── L1 in-process read-through cache ─────────────────────────────────────────
// Serves GET / HGET results from memory when PDIM is unavailable.
// This keeps sessions alive and rate-limit state readable through brief PDIM
// outages, eliminating the per-request [SessionStore] WARN flood.
//
// Eviction: insertion-order LRU, capped at L1_MAX_ENTRIES.
// TTL:      hard per-entry cap of L1_TTL_MS (5 min) — stale data is never served
//           beyond this window regardless of PDIM outage duration.
// Writes:   SET / SETEX / SETNX update L1 on success so subsequent reads are
//           served without a PDIM round-trip while PDIM is up.
// Deletes:  DEL evicts the key on success so logouts are reflected immediately.
// HGET:     cached under a compound key (redisKey + NUL + field).
const L1_MAX_ENTRIES = 2_000;
const L1_TTL_MS = 5 * 60 * 1_000; // 5 minutes

interface _L1Entry {
  value: string | null;
  expiresAt: number;
}
const _l1: Map<string, _L1Entry> = new Map();

function _l1Read(key: string): string | null | undefined {
  const e = _l1.get(key);
  if (!e) return undefined;
  if (Date.now() > e.expiresAt) {
    _l1.delete(key);
    return undefined;
  }
  // LRU promotion — move to tail so the oldest entries are at the front.
  _l1.delete(key);
  _l1.set(key, e);
  return e.value; // may legitimately be null ("key exists but empty")
}

function _l1Write(key: string, value: string | null): void {
  if (_l1.size >= L1_MAX_ENTRIES && !_l1.has(key)) {
    // Evict the oldest (insertion-order head) entry.
    const oldest = _l1.keys().next().value;
    if (oldest !== undefined) _l1.delete(oldest);
  }
  _l1.set(key, { value, expiresAt: Date.now() + L1_TTL_MS });
}

function _l1Evict(...keys: string[]): void {
  for (const k of keys) _l1.delete(k);
}

/**
 * Normalize wasmoon Lua table results to proper JavaScript values.
 *
 * Problem: BullMQ Lua scripts return Lua tables (e.g. a list of stalled job IDs).
 * wasmoon translates Lua arrays to JS objects with 1-indexed numeric keys:
 *   Lua: {"id1", "id2"}  →  JS: { 1: "id1", 2: "id2" }
 *
 * This breaks callers like BullMQ that expect a proper JS array and call .forEach()
 * on the result (TypeError: stalled.forEach is not a function).
 *
 * Normalization rules:
 *   • null / undefined / primitives / real JS arrays → returned as-is
 *   • Empty plain object {} → converted to [] (Lua empty table ≡ empty array)
 *   • Object with all-numeric consecutive keys starting at 1 → converted to JS array
 *     (recursively normalizing each element)
 *   • Everything else (mixed/string-keyed objects) → object with recursively
 *     normalized values (preserves hashes / maps returned by Lua scripts)
 */
function _normalizeLuaResult(val: unknown): unknown {
  if (val === null || val === undefined) return val;
  if (Array.isArray(val)) return val.map(_normalizeLuaResult);
  if (typeof val !== "object") return val;

  const obj = val as Record<string, unknown>;
  const keys = Object.keys(obj);
  if (keys.length === 0) return [];

  const numKeys = keys.map((k) => parseInt(k, 10));
  const allNumeric = numKeys.every((n) => !isNaN(n) && n > 0);
  if (allNumeric) {
    const sorted = [...numKeys].sort((a, b) => a - b);
    const isConsecutive =
      sorted[0] === 1 && sorted[sorted.length - 1] === sorted.length;
    if (isConsecutive) {
      return sorted.map((k) => _normalizeLuaResult(obj[k] ?? obj[String(k)]));
    }
  }

  const out: Record<string, unknown> = {};
  for (const k of keys) out[k] = _normalizeLuaResult(obj[k]);
  return out;
}

/**
 * ioredis-style chainable pipeline/transaction builder.
 * pipeline() flushes commands sequentially; multi() sends one atomic owner
 * transaction and returns ioredis-compatible [error, result] tuples.
 */
interface Pipeline {
  get(k: string): Pipeline;
  set(k: string, v: string, ...a: unknown[]): Pipeline;
  setex(k: string, s: number, v: string): Pipeline;
  del(...k: string[]): Pipeline;
  expire(k: string, s: number): Pipeline;
  pexpire(k: string, ms: number): Pipeline;
  incr(k: string): Pipeline;
  incrby(k: string, n: number): Pipeline;
  decr(k: string): Pipeline;
  decrby(k: string, n: number): Pipeline;
  hset(k: string, ...a: unknown[]): Pipeline;
  hget(k: string, f: string): Pipeline;
  hdel(k: string, ...f: string[]): Pipeline;
  hgetall(k: string): Pipeline;
  sadd(k: string, ...m: unknown[]): Pipeline;
  srem(k: string, ...m: unknown[]): Pipeline;
  zadd(k: string, ...a: unknown[]): Pipeline;
  zrem(k: string, ...m: unknown[]): Pipeline;
  lpush(k: string, ...v: unknown[]): Pipeline;
  rpush(k: string, ...v: unknown[]): Pipeline;
  exec(): Promise<unknown[]>;
}

type PdimPubSubCallback = (error: Error | null, count: number) => void;

export class PdimRedisClient extends EventEmitter {
  public status: string = "ready";
  private execUrl: string;
  private bearerToken: string;
  private disconnected = false;
  private readonly lifecycleController = new AbortController();
  private readonly disconnectedError = Object.assign(
    new Error("[PDIM] Redis client disconnected"),
    { name: "ConnectionError" },
  );
  private readonly pubSubChannels = new Set<string>();
  private readonly pubSubPatterns = new Set<string>();
  private pubSubController: AbortController | null = null;
  private pubSubTask: Promise<void> | null = null;
  private pubSubGeneration = 0;
  private pubSubRefreshChain: Promise<void> = Promise.resolve();

  private assertConnected(): void {
    if (this.disconnected) throw this.disconnectedError;
  }

  private requestSignal(timeoutMs: number | null = PDIM_EXEC_TIMEOUT_MS): AbortSignal {
    if (timeoutMs === null) return this.lifecycleController.signal;
    return AbortSignal.any([
      this.lifecycleController.signal,
      AbortSignal.timeout(timeoutMs),
    ]);
  }

  private awaitOrDisconnect<T>(operation: Promise<T>): Promise<T> {
    if (this.disconnected) return Promise.reject(this.disconnectedError);
    return new Promise<T>((resolve, reject) => {
      const cleanup = () => {
        this.lifecycleController.signal.removeEventListener("abort", onAbort);
      };
      const onAbort = () => {
        cleanup();
        reject(this.disconnectedError);
      };
      this.lifecycleController.signal.addEventListener("abort", onAbort, { once: true });
      operation.then(
        (value) => {
          cleanup();
          resolve(value);
        },
        (error) => {
          cleanup();
          reject(error);
        },
      );
    });
  }

  private delay(ms: number): Promise<void> {
    if (this.disconnected) return Promise.reject(this.disconnectedError);
    if (ms <= 0) return Promise.resolve();
    return new Promise<void>((resolve, reject) => {
      const cleanup = () => {
        clearTimeout(timer);
        this.lifecycleController.signal.removeEventListener("abort", onAbort);
      };
      const onAbort = () => {
        cleanup();
        reject(this.disconnectedError);
      };
      const timer = setTimeout(() => {
        cleanup();
        resolve();
      }, ms);
      this.lifecycleController.signal.addEventListener("abort", onAbort, { once: true });
    });
  }

  private refreshPubSubStream(): Promise<void> {
    const next = this.pubSubRefreshChain.then(() => this.restartPubSubStream());
    this.pubSubRefreshChain = next.catch(() => {});
    return next;
  }

  private async restartPubSubStream(): Promise<void> {
    this.assertConnected();
    const generation = ++this.pubSubGeneration;
    const previousController = this.pubSubController;
    const previousTask = this.pubSubTask;
    previousController?.abort();
    if (previousTask) await previousTask;
    this.pubSubController = null;
    this.pubSubTask = null;

    if (this.pubSubChannels.size + this.pubSubPatterns.size === 0) return;

    const controller = new AbortController();
    this.pubSubController = controller;
    let resolveReady!: () => void;
    let rejectReady!: (error: unknown) => void;
    let settled = false;
    const ready = new Promise<void>((resolve, reject) => {
      resolveReady = resolve;
      rejectReady = reject;
    });
    const markReady = () => {
      if (settled) return;
      settled = true;
      resolveReady();
    };
    const rejectBeforeReady = (error: unknown) => {
      if (settled) return;
      settled = true;
      rejectReady(error);
    };
    this.pubSubTask = this.runPubSubLoop(
      controller,
      generation,
      markReady,
      rejectBeforeReady,
    );
    await ready;
  }

  private async runPubSubLoop(
    controller: AbortController,
    generation: number,
    markReady: () => void,
    rejectBeforeReady: (error: unknown) => void,
  ): Promise<void> {
    let retryMs = 200;
    let initialReady = false;
    const isCurrent = () =>
      !this.disconnected &&
      !controller.signal.aborted &&
      !this.lifecycleController.signal.aborted &&
      generation === this.pubSubGeneration;

    while (isCurrent()) {
      let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
      try {
        const openTimeout = new AbortController();
        const timer = setTimeout(
          () => openTimeout.abort(new Error("PDIM Pub/Sub connection timed out")),
          PDIM_EXEC_TIMEOUT_MS,
        );
        let response: Response;
        try {
          response = await fetch(this.execUrl, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${this.bearerToken}`,
            },
            body: JSON.stringify({
              cmd: "SUBSCRIBE",
              args: [...this.pubSubChannels],
              patterns: [...this.pubSubPatterns],
              stream: true,
            }),
            signal: AbortSignal.any([
              this.lifecycleController.signal,
              controller.signal,
              openTimeout.signal,
            ]),
            redirect: "manual",
          });
        } finally {
          clearTimeout(timer);
        }
        if (!response.ok) {
          const text = await response.text().catch(() => "");
          throw new Error(`PDIM Pub/Sub HTTP ${response.status}: ${text.slice(0, 200)}`);
        }
        if (!response.body) throw new Error("PDIM Pub/Sub response has no stream body");
        reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffered = "";

        while (isCurrent()) {
          const { done, value } = await reader.read();
          if (done) throw new Error("PDIM Pub/Sub stream ended unexpectedly");
          buffered += decoder.decode(value, { stream: true });
          if (buffered.length > 1_048_576) {
            throw new Error("PDIM Pub/Sub stream exceeded the client buffer limit");
          }
          let newline = buffered.indexOf("\n");
          while (newline >= 0) {
            const line = buffered.slice(0, newline);
            buffered = buffered.slice(newline + 1);
            newline = buffered.indexOf("\n");
            if (!line) continue;
            const event = JSON.parse(line) as Record<string, unknown>;
            if (event.type === "ready") {
              initialReady = true;
              retryMs = 200;
              markReady();
              this.emit("pubsub-ready");
            } else if (
              event.type === "message" &&
              typeof event.channel === "string" &&
              typeof event.message === "string"
            ) {
              this.emit("message", event.channel, event.message);
            } else if (
              event.type === "pmessage" &&
              typeof event.pattern === "string" &&
              typeof event.channel === "string" &&
              typeof event.message === "string"
            ) {
              this.emit("pmessage", event.pattern, event.channel, event.message);
            } else if (event.type === "heartbeat") {
              continue;
            } else {
              throw new Error("PDIM Pub/Sub stream returned an invalid event");
            }
          }
        }
      } catch (error) {
        if (!isCurrent()) {
          if (!initialReady) rejectBeforeReady(this.disconnectedError);
          await reader?.cancel().catch(() => {});
          return;
        }
        await reader?.cancel().catch(() => {});
        if (!initialReady) rejectBeforeReady(error);
        this.emit("pubsub-error", error);
        logger.warn(
          `[PDIM] Pub/Sub stream disconnected; retrying in ${retryMs}ms: ${
            error instanceof Error ? error.message : String(error)
          }`,
        );
        await new Promise<void>((resolve) => {
          const finish = () => {
            clearTimeout(timer);
            controller.signal.removeEventListener("abort", finish);
            this.lifecycleController.signal.removeEventListener("abort", finish);
            resolve();
          };
          const timer = setTimeout(finish, retryMs);
          controller.signal.addEventListener("abort", finish, { once: true });
          this.lifecycleController.signal.addEventListener("abort", finish, { once: true });
        });
        retryMs = Math.min(retryMs * 2, 30_000);
      }
    }
  }

  /**
   * BullMQ reads this._client.options.keyPrefix to validate no prefix is set,
   * and uses this._client.options as its opts. Supply safe defaults.
   */
  public readonly options: {
    keyPrefix?: string;
    maxRetriesPerRequest: null;
    enableReadyCheck: boolean;
    enableOfflineQueue: boolean;
  } = {
    keyPrefix: undefined,
    maxRetriesPerRequest: null,
    enableReadyCheck: false,
    enableOfflineQueue: false,
  };

  constructor(execUrl?: string, bearerToken?: string) {
    super();
    // PDIM_EXEC_URL / PDIM_EXEC_TOKEN are non-secret env vars that take
    // precedence over the legacy PDIM_HTTP_EXEC_URL / PDIM_BEARER_TOKEN
    // secrets (which may point to a transient Replit dev workspace URL).
    this.execUrl =
      execUrl ||
      process.env.PDIM_EXEC_URL ||
      process.env.PDIM_HTTP_EXEC_URL ||
      "";
    this.bearerToken =
      bearerToken ||
      process.env.PDIM_EXEC_TOKEN ||
      process.env.PDIM_BEARER_TOKEN ||
      "";

    if (!this.execUrl) {
      throw new Error("PDIM_HTTP_EXEC_URL is required for PdimRedisClient");
    }

    setImmediate(() => {
      if (this.disconnected) return;
      this.emit("connect");
      this.emit("ready");
      logger.info("✅ [PDIM] Connected via HTTP exec endpoint");
    });
  }

  // Static rate-limit deadline — shared across ALL PdimRedisClient instances.
  // Updated by exec() on each 429 to mirror the current AIMD gap, providing a
  // secondary hold that keeps any caller from firing during the backoff window.
  //
  // Cleared opportunistically by successful responses, BUT only when the deadline
  // has already expired (Date.now() >= deadline).  Race-safety under parallel
  // direct lanes: with _PDIM_DIRECT_LANES > 1, an in-flight request that started
  // before a sibling lane's 429 can complete successfully *after* the 429 has
  // set a new future deadline.  Naively clearing to 0 on that success would
  // wipe out the active backoff and release the next caller immediately.  The
  // "only clear if already expired" rule makes the assignment a no-op cleanup
  // for live holds and a tidy reset once the hold has naturally elapsed.
  private static _rateLimitedUntil = 0;
  private static _clearRateLimitIfExpired(): void {
    if (Date?.now() >= PdimRedisClient?._rateLimitedUntil) {
      PdimRedisClient._rateLimitedUntil = 0;
    }
  }
  // 429 setter — monotonic: never lowers an existing future deadline.  Without
  // this guard, two lanes racing on 429s with jittered holds could let the
  // shorter jitter overwrite the longer one and release callers early.
  private static _set429Deadline(deadlineMs: number): void {
    if (deadlineMs > PdimRedisClient?._rateLimitedUntil) {
      PdimRedisClient._rateLimitedUntil = deadlineMs;
    }
  }

  private exec<T = unknown>(
    command: unknown[],
    options: { blocking?: boolean; requestTimeoutMs?: number | null } = {},
  ): Promise<T> {
    if (this.disconnected) return Promise.reject(this.disconnectedError);
    const [cmd, ...rawArgs] = command as (string | number | null | undefined)[];
    // PDIM's HTTP contract accepts only string arguments. An absent Redis value
    // is a result (`{ result: null }`), not a valid command argument. Rejecting
    // nullish inputs prevents silently persisting an empty string in its place.
    if (rawArgs.some((arg) => arg === null || arg === undefined)) {
      throw new TypeError(`[PDIM] ${String(cmd)} received a nullish command argument`);
    }
    const args = rawArgs.map((arg) => String(arg));

    // Circuit breaker: fail-fast BEFORE joining the global queue so we don't
    // waste a queue slot on a request we know will fail.
    if (!cbAllowRequest()) {
      throw new Error(
        `[PDIM] Circuit OPEN — ${cmd} rejected (backing off until PDIM recovers)`,
      );
    }

    // Enqueue through the global serializer.  All PDIM HTTP requests from ALL
    // code paths (direct calls, LuaExecutor redis.call, bzpopmin) pass through
    // this single chain, executed one at a time with a 150ms gap between them.
    const run = async () => {
      this.assertConnected();
      // Rate-limit backoff is evaluated INSIDE the chain (at execution time, not
      // enqueue time).  This is critical: if all callers evaluated it at enqueue
      // time, they'd all clear the check simultaneously and still burst PDIM.
      // Inside the chain they are serialized — only ONE caller wakes from the
      // backoff wait at a time, preventing the burst.
      const rlWait = PdimRedisClient?._rateLimitedUntil - Date?.now();
      if (rlWait > 0) {
        await this.delay(rlWait);
      }
      this.assertConnected();

      let counted = false; // prevent double-counting in the catch block
      try {
        const res = await fetch(this.execUrl, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${this.bearerToken}`,
          },
          body: JSON.stringify({ cmd, args }),
          signal: this.requestSignal(options.requestTimeoutMs),
          // Do not follow redirects automatically — if PDIM's proxy returns 302
          // (Replit redirecting to an error/login page when the service is down)
          // we need to see the raw 302 status so our 3xx handler can trip the
          // circuit breaker rather than silently following into an HTML page.
          redirect: "manual",
        });

        if (!res.ok) {
          const text = await res.text().catch(() => "");
          if (res.status === 429) {
            // AIMD multiplicative increase: gap jumps to gap × 2.5 (aggressive,
            // reaching the 2000ms ceiling in ~9 consecutive hits rather than ~60).
            // _enqueueExec reads _pdimGapMs AFTER the throw, so the next caller
            // in the chain automatically waits the new (larger) gap before firing.
            // The static _rateLimitedUntil mirrors the new gap so that even if a
            // caller somehow got through, the per-fn() rate-limit check holds it.
            const newGap = _pdimAdapt429();
            // Respect the Retry-After header if PDIM sends one.
            // PDIM knows its own rate limit and can tell us exactly how long to
            // wait — more accurate than our AIMD estimate alone.  Honour whichever
            // is larger so we never under-wait relative to PDIM's own signal.
            let retryAfterMs = 0;
            const retryAfterHdr = res.headers.get("retry-after");
            if (retryAfterHdr) {
              const secs = parseFloat(retryAfterHdr);
              if (!isNaN(secs) && secs > 0)
                retryAfterMs = Math.ceil(secs * 1000);
            }
            const holdMs = Math.max(newGap, retryAfterMs);
            // Add per-call random jitter to _rateLimitedUntil so that processes
            // which got 429 at the same wall-clock time don't all release their
            // hold at the exact same moment — they'll be spread 0–500ms apart.
            PdimRedisClient?._set429Deadline(
              Date?.now() + holdMs + Math.floor(Math.random() * 500),
            );
            const errMsg = `PDIM HTTP 429: Too many requests (gap→${newGap}ms${retryAfterMs > 0 ? `, retry-after=${retryAfterMs}ms` : ""})`;
            counted = true;

            // Burst dedup: a simultaneous 429 storm (multiple commands within
            // 2 s) produces near-identical warn lines.  Log the first occurrence
            // immediately; accumulate subsequent ones and flush a summary on the
            // next 429 after the window expires.
            const now429 = Date?.now();
            if (now429 - _last429LoggedAt < _429_DEDUP_MS) {
              _suppressed429Count++;
            } else {
              if (_suppressed429Count > 0) {
                logger.warn(
                  `[PDIM] exec error [${cmd}]: PDIM HTTP 429 — gap→${newGap}ms ` +
                    `(+ ${_suppressed429Count} suppressed in last ${_429_DEDUP_MS}ms burst)`,
                );
                _suppressed429Count = 0;
              } else {
                logger.warn(
                  `[PDIM] exec error [${cmd}]: PDIM HTTP 429 — gap→${newGap}ms`,
                );
              }
              _last429LoggedAt = now429;
            }
            throw new Error(errMsg);
          }
          // Only trip the circuit breaker on 5xx server errors or when PDIM is
          // completely unreachable.  4xx errors are client-side mistakes (bad
          // arguments, unsupported command, etc.) — they don't indicate an outage.
          // 3xx redirects mean PDIM's HTTP exec endpoint is not reachable —
          // Replit's proxy redirects to an error/login page when the service is
          // down or restarting.  Treat exactly like a 5xx: trip the circuit
          // breaker so callers fail-fast instead of following the redirect chain
          // and surfacing confusing HTML "deployment could not be reached" errors.
          if (res.status >= 300 && res.status < 400) {
            cbRecord503();
            counted = true;
            const errMsg = `PDIM HTTP ${res.status}: service temporarily unreachable`;
            _logExecError(cmd, res.status, errMsg);
            throw new Error(errMsg);
          }
          if (res.status >= 500) {
            cbRecord503();
            counted = true;
            const errMsg = `PDIM HTTP ${res.status}: ${text.slice(0, 120)}`;
            _logExecError(cmd, res.status, errMsg);
            throw new Error(errMsg);
          }
          // 4xx means the server is responsive, but this operation failed. Keep
          // the circuit healthy while surfacing the command error to its caller.
          counted = true;
          PdimRedisClient._clearRateLimitIfExpired();
          _pdimAdaptSuccess();
          cbRecordSuccess();
          throw new Error(
            `PDIM HTTP ${res.status} (${String(cmd)}): ${text.slice(0, 200)}`,
          );
        }

        // Successful response — opportunistically clear the rate-limit deadline
        // (only if already expired, to avoid wiping out a concurrent 429-set
        // hold under parallel lanes — see _clearRateLimitIfExpired comment),
        // and let the AIMD gap shrink additively toward the floor.
        PdimRedisClient._clearRateLimitIfExpired();
        _pdimAdaptSuccess();

        // Detect when PDIM returns non-JSON (e.g. Replit's "app not running" HTML page).
        // Treat this as a 503-equivalent — trip the circuit breaker.
        const contentType = res.headers.get("content-type") ?? "";
        if (!contentType?.includes("application/json")) {
          const body = await res.text().catch(() => "(unreadable)");
          cbRecord503();
          counted = true;
          const errMsg = `PDIM returned non-JSON (${contentType?.split(";")[0].trim() || "unknown type"}): ${body?.slice(0, 80)}`;
          _logExecError(cmd, 200, errMsg);
          throw new Error(errMsg);
        }

        const data = await res.json();
        counted = true;
        cbRecordSuccess(); // a successful response resets the counter + closes circuit

        if (data !== null && typeof data === "object") {
          if ("result" in data) return data?.result;
          if ("error" in data) {
            const errMsg = String(data?.error);
            if (errMsg?.startsWith("ERR unknown command")) {
              throw new Error(errMsg);
            }
            throw new Error(errMsg);
          }
        }
        return data;
      } catch (err) {
        if (this.disconnected) throw this.disconnectedError;
        // AbortSignal.timeout() throws a TimeoutError (DOMException name='TimeoutError').
        // AbortController.abort() throws an AbortError (DOMException name='AbortError').
        // Neither should trip the circuit breaker — they indicate PDIM is slow/busy,
        // not that PDIM is down. Instead apply AIMD backpressure (increase gap) so the
        // caller rate drops and PDIM can catch up. Only genuine 5xx/network errors
        // (ECONNREFUSED, etc.) trip the circuit breaker.
        const isTimeout =
          !counted &&
          ((err as any)?.name === "TimeoutError" || (err as any)?.name === "AbortError");
        const isCircuitMsg =
          !counted && (err as any)?.message.startsWith("[PDIM] Circuit");
        if (!counted && !isTimeout && !isCircuitMsg) {
          cbRecord503();
        } else if (isTimeout) {
          // Slow PDIM response — apply mild backpressure WITHOUT setting _last429At.
          // Using _pdimAdapt429() here was the root cause of permanent gap-pinning:
          // it set _last429At on every timeout, blocking the passive-decay timer that
          // needs 5s of 429-quiet to run. Gap stayed at 2000ms forever → session store
          // unreachable → auth broken. _pdimAdaptTimeout() nudges the gap but does NOT
          // update _last429At so passive decay can still pull the gap back to floor.
          _pdimAdaptTimeout();
        }
        if (!counted) {
          // Only log errors we haven't already logged inline.
          // These are connectivity failures (ECONNREFUSED, timeouts, network errors)
          // — expected transient conditions, not bugs in our code.
          //
          // Timeout/AbortErrors flood when PDIM is overwhelmed (many callers each
          // get a 4 s abort): use the same dedup suppression as HTTP status errors.
          _logNetworkError(cmd, (err as Error).message.slice(0, 200));
        }
        cbHalfOpenFailed(); // release HALF_OPEN probe slot so next interval can retry
        throw err;
      }
      // Note: no finally/_freePdimSlot needed — _enqueueExec handles the chain gap
    };
    const operation = options.blocking
      ? _enqueueBlockingExec(run)
      : _enqueueExec(run);
    return this.awaitOrDisconnect(operation as Promise<T>);
  }

  pipeline(): Pipeline {
    return this.createPipeline(false);
  }

  private createPipeline(transactional: boolean): Pipeline {
    const cmds: unknown[][] = [];
    const self = this;
    const pipe: Pipeline = {
      get: (k: string) => {
        cmds.push(["GET", k]);
        return pipe;
      },
      set: (k: string, v: string, ...a: unknown[]) => {
        cmds.push(["SET", k, v, ...a]);
        return pipe;
      },
      setex: (k: string, s: number, v: string) => {
        cmds.push(["SETEX", k, s, v]);
        return pipe;
      },
      del: (...k: string[]) => {
        cmds.push(["DEL", ...k]);
        return pipe;
      },
      expire: (k: string, s: number) => {
        cmds.push(["EXPIRE", k, s]);
        return pipe;
      },
      pexpire: (k: string, ms: number) => {
        cmds.push(["PEXPIRE", k, ms]);
        return pipe;
      },
      incr: (k: string) => {
        cmds.push(["INCR", k]);
        return pipe;
      },
      incrby: (k: string, n: number) => {
        cmds.push(["INCRBY", k, n]);
        return pipe;
      },
      decr: (k: string) => {
        cmds.push(["DECR", k]);
        return pipe;
      },
      decrby: (k: string, n: number) => {
        cmds.push(["DECRBY", k, n]);
        return pipe;
      },
      hset: (k: string, ...a: unknown[]) => {
        cmds.push(["HSET", k, ...a]);
        return pipe;
      },
      hget: (k: string, f: string) => {
        cmds.push(["HGET", k, f]);
        return pipe;
      },
      hdel: (k: string, ...f: string[]) => {
        cmds.push(["HDEL", k, ...f]);
        return pipe;
      },
      hgetall: (k: string) => {
        cmds.push(["HGETALL", k]);
        return pipe;
      },
      sadd: (k: string, ...m: unknown[]) => {
        cmds.push(["SADD", k, ...m]);
        return pipe;
      },
      srem: (k: string, ...m: unknown[]) => {
        cmds.push(["SREM", k, ...m]);
        return pipe;
      },
      zadd: (k: string, ...a: unknown[]) => {
        cmds.push(["ZADD", k, ...a]);
        return pipe;
      },
      zrem: (k: string, ...m: unknown[]) => {
        cmds.push(["ZREM", k, ...m]);
        return pipe;
      },
      lpush: (k: string, ...v: unknown[]) => {
        cmds.push(["LPUSH", k, ...v]);
        return pipe;
      },
      rpush: (k: string, ...v: unknown[]) => {
        cmds.push(["RPUSH", k, ...v]);
        return pipe;
      },
      // Sequential execution preserves per-pipeline ordering.  Under parallel
      // direct lanes (_PDIM_DIRECT_LANES > 1), Promise.all would let commands
      // in one pipeline fan out across lanes and race (e.g. a pipeline's SET
      // then GET could complete out of order if assigned to different lanes
      // with different in-flight RTTs).  Awaiting sequentially keeps each
      // command's enqueue-then-complete strictly before the next command's
      // enqueue, which gives ioredis-compatible pipeline semantics.  Cost:
      // pipelines lose intra-pipeline parallelism — acceptable because real
      // throughput parallelism still comes from concurrent *different* pipelines
      // landing in different lanes.
      exec: async () => {
        if (transactional) {
          const commands = cmds.map((command) => {
            if (command.some((arg) => arg === null || arg === undefined)) {
              throw new TypeError(
                "[PDIM] transaction received a nullish command argument",
              );
            }
            return command.map((arg) => String(arg));
          });
          const reply = await self.exec([
            "__PDIM_MULTI_EXEC",
            JSON.stringify(commands),
          ]);
          if (!Array.isArray(reply) || reply.length !== commands.length) {
            throw new Error("[PDIM] invalid transaction response");
          }
          return reply.map((item) => {
            if (!Array.isArray(item) || item.length !== 2) {
              throw new Error("[PDIM] invalid transaction result tuple");
            }
            const [rawError, value] = item;
            if (rawError === null || rawError === undefined) {
              return [null, value];
            }
            const errorValue: {
              message?: unknown;
              code?: unknown;
              name?: unknown;
            } = typeof rawError === "object" && rawError !== null
              ? rawError as { message?: unknown; code?: unknown; name?: unknown }
              : { message: rawError };
            const error = new Error(String(errorValue.message ?? rawError));
            if (typeof errorValue.name === "string") error.name = errorValue.name;
            if (typeof errorValue.code === "string") {
              Object.assign(error, { code: errorValue.code });
            }
            return [error, null];
          });
        }

        const results: unknown[] = [];
        for (const c of cmds) {
          try {
            // exec coerces every arg to a string internally; the pipeline
            // builder collects heterogeneous args as unknown[].
            results?.push(await self?.exec(c as (string | number | null)[]));
          } catch (e) {
            results?.push(e);
          }
        }
        return results;
      },
    };
    return pipe;
  }

  multi() {
    return this.createPipeline(true);
  }

  duplicate() {
    return new PdimRedisClient(this.execUrl, this.bearerToken);
  }

  // Required by BullMQ's isRedisInstance() check: ['connect', 'disconnect', 'duplicate']
  async connect(): Promise<void> {
    this.assertConnected();
    // PDIM is HTTP-based — already "connected" on construction; no-op here
    this.emit("connect");
    this.emit("ready");
  }

  async quit(): Promise<"OK"> {
    await this.disconnect();
    return "OK";
  }
  async disconnect(): Promise<void> {
    if (this.disconnected) return;
    this.disconnected = true;
    this.status = "end";
    this.pubSubGeneration++;
    this.pubSubController?.abort(this.disconnectedError);
    this.lifecycleController.abort(this.disconnectedError);
    this.emit("close");
    this.emit("end");
    await this.pubSubTask?.catch(() => {});
    this.pubSubTask = null;
    this.pubSubController = null;
  }

  /**
   * BullMQ calls defineCommand() to register Lua scripts as named commands.
   *
   * Calling convention: BullMQ invokes the created method as
   *   client[name](argsArray)  — a SINGLE array argument (ioredis flattens it internally).
   *
   * Implementation: All Lua scripts run locally in a Worker thread via wasmoon
   * (WebAssembly Lua 5.4). redis.call() inside Lua uses synchronous SharedArrayBuffer
   * IPC to call back into the main thread, which forwards to PDIM over HTTP.
   *
   * This completely sidesteps PDIM's broken async Lua runtime where redis?.call()
   * returns Promises that Lua cannot await, causing .then(null) crashes on nil.
   */
  defineCommand(
    name: string,
    opts: { numberOfKeys: number; lua: string },
  ): void {
    const self = this;
    const numKeys = opts?.numberOfKeys;
    const lua = opts?.lua;

    (this as Record<string, unknown>)[name] = async function () {
      let flatArgs: unknown[];
      if (arguments?.length === 1 && Array.isArray(arguments[0])) {
        flatArgs = arguments[0];
      } else {
        flatArgs = Array.from(arguments);
      }

      const result = await execLuaViaPdim(
        (args: string[]) => self?.scriptExec(args),
        lua,
        numKeys,
        flatArgs,
      );
      return _normalizeLuaResult(result);
    };
  }

  async sendCommand(args: string[]): Promise<unknown> {
    const cmd = (args[0] ?? "").toUpperCase();
    if (cmd === "PUBLISH") {
      if (args.length !== 3) throw new Error("ERR wrong number of arguments for PUBLISH");
      return this.publish(args[1]!, args[2]!);
    }
    if (cmd === "SUBSCRIBE") return this.subscribe(...args.slice(1));
    if (cmd === "UNSUBSCRIBE") return this.unsubscribe(...args.slice(1));
    if (cmd === "PSUBSCRIBE") return this.psubscribe(...args.slice(1));
    if (cmd === "PUNSUBSCRIBE") return this.punsubscribe(...args.slice(1));
    return this.exec(args);
  }

  /**
   * Fast-lane variant of sendCommand for LuaExecutor redis?.call() IPC.
   *
   * Uses _enqueueScriptExec (50ms gap) instead of _enqueueExec (full AIMD gap).
   * The Worker's Atomics.wait() guarantees sequential calls from the same script,
   * so the AIMD rate-limit gap is unnecessary overhead — the 50ms gap is enough
   * to yield the event loop between redis.call()s without stalling the script.
   *
   * The circuit breaker is still checked so a downed PDIM trips correctly.
   * The 429 AIMD backoff is still applied: if a 429 is received during a script
   * call, _pdimAdapt429 raises _pdimGapMs; subsequent MAIN-CHAIN callers see the
   * raised gap.  Script callers use the fixed 50ms lane so they don't compound
   * the slowdown — but the rate-limit deadline (_rateLimitedUntil) IS checked
   * inside exec() so script calls still honour the mandatory hold-off.
   */
  async scriptExec(args: string[]): Promise<unknown> {
    this.assertConnected();
    const [cmd, ...rawArgs] = args;
    // Same contract as exec(): PDIM accepts only string arguments, and an
    // absent Redis value is a result, never a valid argument. Rejecting here
    // keeps Lua/BullMQ script calls from silently persisting empty strings.
    if (rawArgs.some((a) => a === null || a === undefined)) {
      throw new TypeError(
        `[PDIM] ${String(cmd)} (script) received a nullish command argument`,
      );
    }
    const strArgs = rawArgs.map((a) => String(a));

    if (!cbAllowRequest()) {
      throw new Error(`[PDIM] Circuit OPEN — ${cmd} (script) rejected`);
    }

    return this.awaitOrDisconnect(_enqueueScriptExec(async () => {
      this.assertConnected();
      const rlWait = PdimRedisClient?._rateLimitedUntil - Date?.now();
      if (rlWait > 0) await this.delay(rlWait);
      this.assertConnected();

      let counted = false;
      try {
        const res = await fetch(this.execUrl, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${this.bearerToken}`,
          },
          body: JSON.stringify({ cmd, args: strArgs }),
          signal: this.requestSignal(),
          // Do not follow redirects — a 3xx from Replit's proxy (PDIM sleeping)
          // must be seen as a failure here, not silently followed to an HTML page.
          // Same reasoning as the main exec() path.
          redirect: "manual",
        });

        if (!res.ok) {
          const text = await res.text().catch(() => "");
          if (res.status === 429) {
            const newGap = _pdimAdapt429();
            PdimRedisClient?._set429Deadline(Date?.now() + newGap);
            throw new Error(`PDIM HTTP 429 (script ${cmd}): gap→${newGap}ms`);
          }
          // 3xx = Replit proxy redirect (PDIM sleeping); 5xx = PDIM server error.
          // Both are counted as circuit-breaker failures in the catch block.
          if (res.status >= 300 && res.status < 400) {
            cbRecord503();
            counted = true;
            throw new Error(`PDIM HTTP ${res.status} (script ${cmd}): service temporarily unreachable`);
          }
          if (res.status >= 500) {
            cbRecord503();
            counted = true;
            throw new Error(`PDIM HTTP ${res.status} (script ${cmd}): ${text?.slice(0, 200)}`);
          }
          // The server is alive, but the script operation failed. Do not turn a
          // command failure into Lua nil: BullMQ must see the explicit error.
          counted = true;
          PdimRedisClient._clearRateLimitIfExpired();
          _pdimAdaptSuccess();
          cbRecordSuccess();
          throw new Error(
            `PDIM HTTP ${res.status} (script ${String(cmd)}): ${text.slice(0, 200)}`,
          );
        }

        PdimRedisClient?._clearRateLimitIfExpired();
        _pdimAdaptSuccess();

        const contentType = res.headers.get("content-type") ?? "";
        if (!contentType?.includes("application/json")) {
          const body = await res.text().catch(() => "(unreadable)");
          cbRecord503();
          counted = true;
          throw new Error(
            `PDIM non-JSON (script ${cmd}): ${body?.slice(0, 80)}`,
          );
        }

        const data = await res.json();
        counted = true;
        cbRecordSuccess();

        if (data !== null && typeof data === "object") {
          if ("result" in data) return data?.result;
          if ("error" in data) {
            const errMsg = String(data?.error);
            if (errMsg?.startsWith("ERR unknown command")) {
              throw new Error(errMsg);
            }
            throw new Error(errMsg);
          }
        }
        return data;
      } catch (err) {
        if (this.disconnected) throw this.disconnectedError;
        // Same TimeoutError/AbortError exclusion as the main exec catch block —
        // slow PDIM responses should not trip the circuit breaker.
        const isTimeout =
          !counted &&
          ((err as any)?.name === "TimeoutError" || (err as any)?.name === "AbortError");
        const isCircuitMsg =
          !counted && (err as any)?.message?.startsWith("[PDIM] Circuit");
        if (!counted && !isTimeout && !isCircuitMsg) {
          cbRecord503();
        } else if (isTimeout) {
          _pdimAdaptTimeout(); // backpressure: slow timeout, NOT a 429 — don't set _last429At
        }
        cbHalfOpenFailed();
        throw err;
      }
    }));
  }

  // ── String commands ───────────────────────────────────────────────────────
  async get(key: string): Promise<string | null> {
    this.assertConnected();
    const stale = _l1Read(key);
    try {
      const fresh = await this.exec<string | null>(["GET", key]);
      _l1Write(key, fresh);
      return fresh;
    } catch (err) {
      // PDIM unavailable — serve the L1 value (even if null/"key not found")
      // so callers (session store, rate limiter) keep working through the outage.
      this.assertConnected();
      if (stale !== undefined) return stale;
      throw err;
    }
  }
  async set(key: string, value: string, ...args: unknown[]): Promise<"OK"> {
    const result = await this.exec<"OK">(["SET", key, value, ...args]);
    _l1Write(key, value);
    return result;
  }
  async setex(key: string, secs: number, value: string): Promise<"OK"> {
    const result = await this.exec<"OK">(["SETEX", key, secs, value]);
    _l1Write(key, value);
    return result;
  }
  async setnx(key: string, value: string): Promise<0 | 1> {
    const result = await this.exec<0 | 1>(["SETNX", key, value]);
    if (result === 1) _l1Write(key, value);
    return result;
  }
  async getset(key: string, value: string): Promise<string | null> {
    const result = await this.exec<string | null>(["GETSET", key, value]);
    _l1Write(key, value);
    return result;
  }
  async mget(...keys: string[]): Promise<(string | null)[]> {
    return this.exec<(string | null)[]>(["MGET", ...keys]);
  }
  async mset(...args: string[]): Promise<"OK"> {
    return this.exec<"OK">(["MSET", ...args]);
  }
  async append(key: string, value: string): Promise<number> {
    return this.exec<number>(["APPEND", key, value]);
  }
  async incr(key: string): Promise<number> {
    return this.exec<number>(["INCR", key]);
  }
  async decr(key: string): Promise<number> {
    return this.exec<number>(["DECR", key]);
  }
  async incrby(key: string, n: number): Promise<number> {
    return this.exec<number>(["INCRBY", key, n]);
  }
  async decrby(key: string, n: number): Promise<number> {
    return this.exec<number>(["DECRBY", key, n]);
  }
  async incrbyfloat(key: string, n: number): Promise<string> {
    return this.exec<string>(["INCRBYFLOAT", key, n]);
  }

  // ── Key commands ──────────────────────────────────────────────────────────
  async del(...keys: string[]): Promise<number> {
    const result = await this.exec<number>(["DEL", ...keys]);
    _l1Evict(...keys);
    return result;
  }
  async exists(...keys: string[]): Promise<number> {
    return this.exec<number>(["EXISTS", ...keys]);
  }
  async expire(key: string, secs: number): Promise<0 | 1> {
    return this.exec<0 | 1>(["EXPIRE", key, secs]);
  }
  async pexpire(key: string, ms: number): Promise<0 | 1> {
    return this.exec<0 | 1>(["PEXPIRE", key, ms]);
  }
  async expireat(key: string, ts: number): Promise<0 | 1> {
    return this.exec<0 | 1>(["EXPIREAT", key, ts]);
  }
  async persist(key: string): Promise<0 | 1> {
    return this.exec<0 | 1>(["PERSIST", key]);
  }
  async ttl(key: string): Promise<number> {
    return this.exec<number>(["TTL", key]);
  }
  async pttl(key: string): Promise<number> {
    return this.exec<number>(["PTTL", key]);
  }
  async type(key: string): Promise<string> {
    return this.exec<string>(["TYPE", key]);
  }
  async rename(key: string, newKey: string): Promise<"OK"> {
    return this.exec<"OK">(["RENAME", key, newKey]);
  }
  async keys(pattern: string): Promise<string[]> {
    return this.exec<string[]>(["KEYS", pattern]);
  }
  async scan(
    cursor: string | number,
    ...args: unknown[]
  ): Promise<[string, string[]]> {
    return this.exec<[string, string[]]>(["SCAN", cursor, ...args]);
  }
  async dbsize(): Promise<number> {
    return this.exec<number>(["DBSIZE"]);
  }
  async randomkey(): Promise<string | null> {
    return this.exec<string | null>(["RANDOMKEY"]);
  }

  // ── Hash commands ─────────────────────────────────────────────────────────
  async hget(key: string, field: string): Promise<string | null> {
    this.assertConnected();
    const l1Key = `${key}\x00${field}`;
    const stale = _l1Read(l1Key);
    try {
      const fresh = await this.exec<string | null>(["HGET", key, field]);
      _l1Write(l1Key, fresh);
      return fresh;
    } catch (err) {
      this.assertConnected();
      if (stale !== undefined) return stale;
      throw err;
    }
  }
  async hset(key: string, ...args: unknown[]): Promise<number> {
    return this.exec<number>(["HSET", key, ...args]);
  }
  async hsetnx(key: string, field: string, value: string): Promise<0 | 1> {
    return this.exec<0 | 1>(["HSETNX", key, field, value]);
  }
  async hdel(key: string, ...fields: string[]): Promise<number> {
    return this.exec<number>(["HDEL", key, ...fields]);
  }
  async hmget(key: string, ...fields: string[]): Promise<(string | null)[]> {
    return this.exec<(string | null)[]>(["HMGET", key, ...fields]);
  }
  async hmset(key: string, ...args: unknown[]): Promise<"OK"> {
    // PDIM only accepts HSET with a single field-value pair.  Split HMSET
    // (which can carry N pairs) into sequential HSET calls.
    for (let i = 0; i < args.length - 1; i += 2) {
      await this.exec<"OK">(["HSET", key, args[i], args[i + 1]]);
    }
    return "OK";
  }
  async hgetall(key: string): Promise<Record<string, string>> {
    const result = await this.exec<Record<string, string>>(["HGETALL", key]);
    return result ?? {};
  }
  async hkeys(key: string): Promise<string[]> {
    return this.exec<string[]>(["HKEYS", key]);
  }
  async hvals(key: string): Promise<string[]> {
    return this.exec<string[]>(["HVALS", key]);
  }
  async hlen(key: string): Promise<number> {
    return this.exec<number>(["HLEN", key]);
  }
  async hexists(key: string, field: string): Promise<0 | 1> {
