let _pdimInstance: PdimRedisClient | null = null;

export function getPdimClient(): PdimRedisClient {
  if (!_pdimInstance) {
    _pdimInstance = new PdimRedisClient();
    // Start the direct-HTTP recovery prober on first use so the circuit can
    // close even when PDIM's Lua layer is lagging behind its HTTP layer.
    startPdimDirectProber();
  }
  return _pdimInstance;
}

export function isPdimConfigured(): boolean {
  const execUrl =
    process.env.PDIM_EXEC_URL || process.env.PDIM_HTTP_EXEC_URL || "";
  if (!execUrl) return false;

  // The in-process PDIM server is intentionally loopback-only and has no
  // bearer-auth boundary. Remote PDIM must still provide its credential.
  const isLocal = isLocalPdimExecUrl(execUrl);
  return isLocal || !!(process.env.PDIM_EXEC_TOKEN || process.env.PDIM_BEARER_TOKEN);
}

function isLocalPdimExecUrl(execUrl: string): boolean {
  try {
    return new URL(execUrl).origin === loopbackUrl(runtimePorts.localPdim);
  } catch {
    return false;
  }
}

// ── Direct-HTTP circuit-recovery prober ──────────────────────────────────────
// When the circuit is OPEN the only probe that fires is the HALF-OPEN one,
// which goes through the full Lua executor path.  On deep cold-starts PDIM's
// plain HTTP layer recovers ~60 s before its Lua/scripting layer does, so the
// Lua-based probe keeps returning 500 even though PDIM is already serving
// regular GET/SET commands.
//
// This background timer makes a lightweight direct POST (bypassing Lua) every
// DIRECT_PROBE_INTERVAL_MS.  On HTTP 200 it calls cbForceClose() so the
// circuit closes immediately — no more 60-s re-open/re-close cycling.
//
const DIRECT_PROBE_INTERVAL_MS = 15_000;
const DIRECT_PROBE_TIMEOUT_MS = 5_000;
// Timeout for every individual PDIM exec() call.
// History: originally 15s → reduced to 1500ms to improve queue drain rate
// when PDIM was congested.  Raised to 4000ms because PDIM is a permanently
// running service whose RTT occasionally spikes to ~3–4 s under write load;
// 1500ms caused spurious SET/SETEX timeouts during those spikes.  4000ms
// still keeps the per-lane drain rate at ~2 calls/s (vs 0.5 at 15s) and
// gives real latency spikes a chance to resolve before the timeout fires.
const PDIM_EXEC_TIMEOUT_MS = 4_000;

let _directProbeTimer: ReturnType<typeof setInterval> | null = null;

export function startPdimDirectProber(): void {
  if (_directProbeTimer) return; // already running

  const pdimUrl =
    process.env.PDIM_EXEC_URL || process.env.PDIM_HTTP_EXEC_URL || "";
  const pdimToken =
    process.env.PDIM_EXEC_TOKEN || process.env.PDIM_BEARER_TOKEN || "";
  if (!pdimUrl) return;
  const isLocal = isLocalPdimExecUrl(pdimUrl);
  // The owned loopback server intentionally has no authentication boundary.
  // Every remote authority remains fail-closed without its bearer credential.
  if (!isLocal && !pdimToken) return;

  _directProbeTimer = setInterval(async () => {
    const state = cbGetState();
    if (state === "CLOSED") return; // circuit healthy — nothing to do

    try {
      const headers: Record<string, string> = {
        "Content-Type": "application/json",
      };
      if (!isLocal) headers.Authorization = `Bearer ${pdimToken}`;
      const res = await fetch(pdimUrl, {
        method: "POST",
        headers,
        body: JSON.stringify({ cmd: "PING", args: [] }),
        signal: AbortSignal.timeout(DIRECT_PROBE_TIMEOUT_MS),
        // Do not follow Replit proxy redirects — a 3xx → 200 HTML response
        // (e.g. "deployment not reachable" page) would look like a successful
        // probe and incorrectly force-close the circuit while PDIM is still down.
        redirect: "manual",
      });

      if (res.ok) {
        const data = await res.json().catch(() => undefined);
        const pong =
          data === "PONG" ||
          (data !== null &&
            typeof data === "object" &&
            "result" in data &&
            data.result === "PONG");
        if (pong && cbGetState() !== "CLOSED") {
          logger.info(
            `[PDIM] Direct HTTP probe OK (HTTP ${res.status}) — force-closing circuit breaker`,
          );
          cbForceClose();
        } else if (!pong) {
          logger.debug(
            `[PDIM] Direct probe returned HTTP ${res.status} without PONG ` +
              `(circuit stays ${cbGetState()})`,
          );
        }
      } else {
        logger.debug(
          `[PDIM] Direct probe: HTTP ${res.status} ` +
            `content-type=${res.headers.get("content-type") ?? "none"} ` +
            `(circuit stays ${cbGetState()})`,
        );
      }
    } catch (err) {
      logger.debug(`[PDIM] Direct probe error: ${(err as Error).message}`);
    }
  }, DIRECT_PROBE_INTERVAL_MS);

  _directProbeTimer.unref?.(); // don't block process exit
}

import pino from "pino";
import { format } from "node:util";
import { sanitizeLogText, sanitizeLogValue } from "./logSanitizer.js";

// Production-grade redaction — never let secrets/PII reach stdout/log sinks.
// Paths use Pino's redaction syntax (https://getpino.io/#/docs/redaction).
const REDACT_PATHS = [
  // Headers
  'req.headers.authorization',
  'req.headers.cookie',
  'req.headers["x-api-key"]',
  'req.headers["x-csrf-token"]',
  'headers.authorization',
  'headers.cookie',
  'headers["x-api-key"]',
  'headers["x-csrf-token"]',
  // Auth payloads
  '*.password',
  '*.passwordHash',
  '*.currentPassword',
  '*.newPassword',
  '*.token',
  '*.accessToken',
  '*.refreshToken',
  '*.idToken',
  '*.apiKey',
  '*.secret',
  '*.clientSecret',
  '*.privateKey',
  '*.twoFactorSecret',
  '*.totpSecret',
  // Stripe / payments
  '*.stripeSecretKey',
  '*.stripeWebhookSecret',
  '*.cardNumber',
  '*.cvc',
  '*.cvv',
  // Generic sensitive containers
  'body.password',
  'body.token',
  'body.secret',
  'body.apiKey',
];

const transport =
  process.env.NODE_ENV !== "production" && !process.env.REPLIT_DEPLOYMENT
    ? { target: "pino-pretty", options: { colorize: true } }
    : undefined;

/** Exported for isolated destination-capture tests; production uses the singleton. */
export function createAppLogger(destination?: pino.DestinationStream) {
  const options: pino.LoggerOptions = {
  level: process.env.LOG_LEVEL || "info",
  hooks: {
    logMethod(args, method) {
      const clean = args.map(value => sanitizeLogValue(value));
      // Redact after interpolation as well: "%s@%s" must not reconstruct PII.
      const messageIndex = typeof clean[0] === "string" ? 0 : 1;
      if (typeof clean[messageIndex] === "string") {
        const message = sanitizeLogText(format(...clean.slice(messageIndex)));
        clean.splice(messageIndex, clean.length - messageIndex, message);
      }
      method.apply(this, clean as Parameters<typeof method>);
    },
  },
  formatters: {
    bindings: bindings => ({ ...sanitizeLogValue(bindings) as Record<string, unknown> }),
    log: object => ({ ...sanitizeLogValue(object) as Record<string, unknown> }),
  },
  redact: {
    paths: REDACT_PATHS,
    censor: "[REDACTED]",
    remove: false,
  },
  transport: destination ? undefined : transport,
  };
  const instance = destination ? pino(options, destination) : pino(options);
  const child = instance.child;
  // Pino intentionally resets the bindings formatter for children. Sanitize
  // before child creation too, including grandchildren.
  instance.child = function (this: typeof instance, bindings, childOptions) {
    return child.call(this, { ...sanitizeLogValue(bindings) as Record<string, unknown> }, childOptions);
  } as typeof instance.child;
  const setBindings = instance.setBindings;
  instance.setBindings = function (bindings) {
    setBindings.call(this, { ...sanitizeLogValue(bindings) as Record<string, unknown> });
  };
  return instance;
}

export const logger = createAppLogger();

/**
 * LUA WORKER THREAD POOL
 *
 * Manages a pool of worker threads that execute Lua scripts without blocking
 * the main Node.js event loop.
 *
 * Why: wasmoon's doStringSync() is synchronous — it occupies the calling
 * thread until the script finishes.  In the main thread that means zero other
 * requests are served while a Lua script runs.  Moving execution to worker
 * threads gives every CPU core work to do and keeps the main event loop free
 * to accept and dispatch new HTTP connections.
 *
 * Caveats:
 *   • redis.call() inside Lua scripts is NOT supported in worker mode.
 *     Scripts that use redis.call() are transparently routed back to the
 *     main-thread runner (`store.runLuaSync()`).
 *   • Worker threads share no heap — the full Wasm binary is compiled once
 *     per worker (not per script).
 */

import { Worker } from "worker_threads";
import { randomUUID } from "crypto";
import { fileURLToPath } from "url";
import path from "path";
import type { LuaRequest, LuaResponse } from "./lua-worker.js";

const POOL_SIZE = Math.min(Number(process.env["LUA_WORKER_THREADS"] ?? 2), 8);
const TIMEOUT_MS = 10_000; // kill Lua script if it runs > 10 s

// Resolve the worker file path in a way that works in both:
//   • Development (tsx / ESM): import.meta.url is a real file URL
//   • Production (esbuild CJS bundle): import.meta.url is undefined
//     → pool is silently disabled; EVAL falls back to the main-thread runner
function resolveWorkerFile(): string | null {
  try {
    const url = import.meta.url; // undefined in esbuild CJS output
    if (!url) return null;
    return path.join(path.dirname(fileURLToPath(url)), "lua-worker.ts");
  } catch {
    return null;
  }
}

const WORKER_FILE: string | null = resolveWorkerFile();

interface PendingCall {
  resolve: (v: unknown) => void;
  reject: (e: Error) => void;
  timer: ReturnType<typeof setTimeout>;
}

interface PoolWorker {
  worker: Worker;
  pending: Map<string, PendingCall>;
  active: number;
}

class LuaPool {
  private workers: PoolWorker[] = [];
  private _started = false;

  start(): void {
    if (this._started) return;
    this._started = true;
    if (!WORKER_FILE) return; // production CJS: pool disabled, EVAL falls back to main thread
    for (let i = 0; i < POOL_SIZE; i++) {
      this._spawnWorker();
    }
  }

  private _spawnWorker(): void {
    if (!WORKER_FILE) return;
    // Pass --import tsx so the worker thread can load .ts files directly.
    const worker = new Worker(WORKER_FILE, { execArgv: ["--import", "tsx"] });
    const pw: PoolWorker = { worker, pending: new Map(), active: 0 };

    worker.on("message", (res: LuaResponse) => {
      const call = pw.pending.get(res.id);
      if (!call) return;
      pw.pending.delete(res.id);
      pw.active = Math.max(0, pw.active - 1);
      clearTimeout(call.timer);
      if (res.error) {
        call.reject(new Error(res.error));
      } else {
        call.resolve(res.result);
      }
    });

    worker.on("error", (err) => {
      for (const [, call] of pw.pending) {
        clearTimeout(call.timer);
        call.reject(
          new Error(
            `Lua worker error: ${err instanceof Error ? err.message : String(err)}`,
          ),
        );
      }
      pw.pending.clear();
      pw.active = 0;
    });

    worker.on("exit", () => {
      // Respawn crashed workers
      const idx = this.workers.indexOf(pw);
      if (idx !== -1) {
        this.workers.splice(idx, 1);
        this._spawnWorker();
      }
    });

    this.workers.push(pw);
  }

  /**
   * Run a Lua script in the pool.  Rejects if the script uses redis.call()
   * (the caller should fall back to the main-thread runner in that case).
   */
  run(script: string, keys: string[], argv: string[]): Promise<unknown> {
    if (!this._started) this.start();

    // Pick the least-loaded worker
    const pw = this.workers.reduce(
      (best, w) => (w.active < best.active ? w : best),
      this.workers[0]!,
    );

    const id = randomUUID();
    const req: LuaRequest = { id, script, keys, argv };

    return new Promise<unknown>((resolve, reject) => {
      const timer = setTimeout(() => {
        pw.pending.delete(id);
        pw.active = Math.max(0, pw.active - 1);
        reject(new Error(`ERR Lua script timed out after ${TIMEOUT_MS}ms`));
      }, TIMEOUT_MS);

      pw.pending.set(id, { resolve, reject, timer });
      pw.active++;
      pw.worker.postMessage(req);
    });
  }

  /** True if the pool has started and workers are alive. */
  get isReady(): boolean {
    return this._started && this.workers.length > 0;
  }

  /** Count of scripts currently running across all workers. */
  get activeConcurrency(): number {
    return this.workers.reduce((sum, w) => sum + w.active, 0);
  }

  async shutdown(): Promise<void> {
    await Promise.all(this.workers.map((pw) => pw.worker.terminate()));
    this.workers = [];
    this._started = false;
  }
}

export const luaPool = new LuaPool();

/**
 * Runtime port contract.
 *
 * PORT is the only externally served HTTP listener. Every other value in this
 * module is an internal, loopback-only service port. Keep all first-party
 * processes on this contract instead of embedding numeric defaults in callers.
 */

const MIN_PORT = 1;
const MAX_PORT = 65_535;

export const defaultPorts = Object.freeze({
  app: 5_000,
  localPdim: 5_556,
  diffusionGateway: 8_008,
  maxcoreApi: 8_090,
  boosterState: 9_877,
  maxcoreModelApi: 9_878,
  maxcoreModelHealth: 9_879,
  legacyPythonAi: 9_880,
});

export type RuntimePorts = Readonly<
  Record<keyof typeof defaultPorts, number>
>;

function readPort(name: string, defaultValue: number): number {
  const raw = process.env[name];
  if (raw === undefined || raw.trim() === "") return defaultValue;

  if (!/^\d+$/.test(raw)) {
    throw new Error(
      `[Ports] ${name} must be an integer between ${MIN_PORT} and ${MAX_PORT}; received "${raw}"`,
    );
  }

  const value = Number(raw);
  if (!Number.isSafeInteger(value) || value < MIN_PORT || value > MAX_PORT) {
    throw new Error(
      `[Ports] ${name} must be an integer between ${MIN_PORT} and ${MAX_PORT}; received "${raw}"`,
    );
  }

  return value;
}

function assertUniquePorts(ports: RuntimePorts): RuntimePorts {
  const owners = new Map<number, string>();
  for (const [name, port] of Object.entries(ports)) {
    const existing = owners.get(port);
    if (existing) {
      throw new Error(
        `[Ports] ${name} and ${existing} are both configured for port ${port}. ` +
          "Internal services must use distinct ports.",
      );
    }
    owners.set(port, name);
  }
  return Object.freeze(ports);
}

export const runtimePorts = assertUniquePorts({
  app: readPort("PORT", defaultPorts.app),
  localPdim: readPort("LOCAL_PDIM_PORT", defaultPorts.localPdim),
  diffusionGateway: readPort(
    "VIDEO_DIFFUSION_PORT",
    defaultPorts.diffusionGateway,
  ),
  maxcoreApi: readPort("MAXCORE_LOCAL_PORT", defaultPorts.maxcoreApi),
  boosterState: readPort(
    "BOOSTERSTATE_SIDECAR_PORT",
    defaultPorts.boosterState,
  ),
  maxcoreModelApi: readPort(
    "MODEL_API_PORT",
    defaultPorts.maxcoreModelApi,
  ),
  maxcoreModelHealth: readPort(
    "MODEL_API_HEALTH_PORT",
    defaultPorts.maxcoreModelHealth,
  ),
  legacyPythonAi: readPort("PYTHON_AI_PORT", defaultPorts.legacyPythonAi),
});

export function loopbackUrl(port: number): string {
  return `http://127.0.0.1:${port}`;
}

// @ts-nocheck
/**
 * LuaExecutor — runs BullMQ Lua scripts locally in a Worker thread using
 * wasmoon (WebAssembly Lua 5.4), bypassing PDIM's broken async Lua runtime.
 *
 * Root problem with PDIM EVAL:
 *   PDIM implements redis.call() as an async Promise chain internally.
 *   BullMQ's Lua scripts use redis?.call() synchronously (standard Redis model).
 *   When redis?.call() returns nil, PDIM tries .then(null) and crashes.
 *
 * Solution:
 *   1. Run the Lua script in a Worker thread (can block with Atomics?.wait).
 *   2. Inject redis?.call() as a synchronous function that uses SharedArrayBuffer
 *      IPC to call the main thread, which awaits PDIM HTTP and writes the result.
 *   3. Pre-decode msgpack Buffer ARGV values before passing to the worker,
 *      so cmsgpack?.unpack() receives already-decoded Lua tables (identity fn).
 */

import { Worker } from "worker_threads";
import { Unpackr } from "msgpackr";
import { logger } from "../logger.js";
import { cbIsOpen } from "./pdimCircuitBreaker.js";

const _msgUnpacker = new Unpackr({ useRecords: false });

/**
 * Async semaphore for wasmoon Worker threads.
 *
 * Each Worker loads the full WASM binary and makes multiple HTTP calls to
 * PDIM — too many simultaneously exhausts memory and saturates the HTTP
 * connection pool.  Instead of rejecting callers when the cap is hit (which
 * causes BullMQ to retry immediately and create a storm), we queue waiting
 * callers and resolve them as slots free up.
 *
 * MAX_WAIT_MS: maximum time a caller will wait for a slot before giving up.
 */
// Single exclusive Worker: each BullMQ Lua script gets uncontested access to
// the PDIM fast-lane.  Scripts are sequential either way; a single Worker
// eliminates contention and lets each redis?.call() complete in ~PDIM_RTT + 10ms.
const MAX_CONCURRENT_WORKERS = 1;

// _maxWaitMs: maximum time a CALLER waits to ACQUIRE a Worker slot (queue wait),
// NOT a limit on script execution time.  Scripts run to completion with no
// hard-kill — only the per-60s watchdog log reminds us if one is stuck.
//
// With the fast-lane (10ms inter-call gap):
//   typical script: 35 × (200ms RTT + 10ms gap) = ~7.35s
//   high-RTT case:  35 × (800ms RTT + 10ms gap) = ~28.35s
// Slot-wait raised to 90s to handle sustained PDIM congestion events without
// premature rejection — scripts always free their slot well within this window.
let _maxWaitMs = 90_000;
/** Permanently increase the LuaExecutor slot-wait timeout — called by PermanentFixRegistry. */
export function setLuaScriptTimeout(ms: number): void {
  _maxWaitMs = Math.max(90_000, Math.min(180_000, ms));
}
export function getLuaScriptTimeout(): number {
  return _maxWaitMs;
}
// Backpressure cap: reject immediately when the wait queue exceeds this size.
// Without a cap, sustained BullMQ load causes _waitQueue to grow without bound,
// holding thousands of timer handles and consuming unbounded memory.
// 5000 slots: matches real-world 100M+ caller burst peaks without premature shedding.
const MAX_QUEUE_SIZE = 5000;
// How long to sleep before rejecting when the circuit is OPEN.
// BullMQ uses onlyEmitError:true so our rejection is swallowed and treated as
// "no job" — without this sleep the poll loop runs at full speed, saturating
// the event loop and preventing HTTP requests from being handled.
const CIRCUIT_OPEN_BACKOFF_MS = 5_000;

// ── Consecutive PDIM error backoff ────────────────────────────────────────────
// When PDIM returns 5xx errors on Lua script calls the slot is normally
// released immediately, causing BullMQ to retry at full speed (~14 retries/s
// with 4 workers).  That flood itself can push PDIM from HTTP 500 → HTTP 502.
// We track consecutive script-level PDIM 5xx errors and exponentially delay
// slot release so BullMQ's effective retry rate backs off:
//   1 error  →  0 ms  (first failure, no delay)
//   2 errors →  1 s
//   3 errors →  2 s
//   4 errors →  4 s
//   5+       →  8 s  (capped — still recovers fast when PDIM stabilises)
// On any successful script completion the counter resets to 0.
let _luaConsecutivePdimErrors = 0;
const LUA_PDIM_ERR_BACKOFF_CAP_MS = 8_000;

function _luaComputeBackoff(): number {
  if (_luaConsecutivePdimErrors < 2) return 0;
  return Math.min(
    LUA_PDIM_ERR_BACKOFF_CAP_MS,
    500 * Math.pow(2, _luaConsecutivePdimErrors - 2),
  );
}

// Module-level boot timestamp — used to gate the 30s/60s watchdog WARNs
// during the initial 120s PDIM settling window (stalls are expected at boot).
const _executorBootTs = Date.now();

let _activeWorkers = 0;

// Each queued waiter stores its resolve fn and timeout handle separately.
// This lets _releaseWorkerSlot hand the slot to the next waiter WITHOUT
// calling _activeWorkers++ (the slot is *transferred*, not newly created).
// The previous design stored a combined resolver = () => { _activeWorkers++; resolve(); }
// and called it from _releaseWorkerSlot without decrementing first, causing
// _activeWorkers to drift above MAX_CONCURRENT_WORKERS by +1 per handoff.
interface _Waiter {
  resolve: () => void;
  timer: ReturnType<typeof setTimeout>;
}
const _waitQueue: _Waiter[] = [];

async function _acquireWorkerSlot(): Promise<void> {
  if (_activeWorkers < MAX_CONCURRENT_WORKERS) {
    _activeWorkers++;
    return;
  }
  // Backpressure: reject immediately if the wait queue is saturated.
  // Without this cap, sustained BullMQ load causes _waitQueue to grow without
  // bound, holding thousands of 60-second timer handles and consuming unbounded
  // memory — a silent kill under infinite workload.
  if (_waitQueue.length >= MAX_QUEUE_SIZE) {
    throw new Error(
      "[LuaExecutor] Wait queue saturated — shedding BullMQ request (backpressure)",
    );
  }
  // Queue the caller until a slot frees up — transfer increments the count.
  return new Promise<void>((resolve, reject) => {
    const entry: _Waiter = {
      resolve,
      timer: setTimeout(() => {
        const idx = _waitQueue.indexOf(entry);
        if (idx !== -1) _waitQueue.splice(idx, 1);
        reject(
          new Error(
            `[LuaExecutor] Timeout waiting for worker slot (${Math.round(_maxWaitMs / 1000)}s)`,
          ),
        );
      }, _maxWaitMs),
    };
    _waitQueue.push(entry);
  });
}

function _releaseWorkerSlot(): void {
  if (_waitQueue.length > 0) {
    // Transfer the slot to the next waiter.  _activeWorkers stays the same:
    // the releasing worker relinquishes its slot and the waiter takes it over.
    // We must NOT call _activeWorkers++ here (old bug: resolver did that,
    // causing count to grow by 1 on every queue handoff).
    const { resolve, timer } = _waitQueue.shift()!;
    clearTimeout(timer);
    resolve();
  } else {
    if (_activeWorkers > 0) _activeWorkers--;
  }
}

/**
 * Emergency semaphore reset — called by chainErrorAutoFixer when the
 * LuaExecutor gets stuck (active count drifts above the cap due to worker
 * threads that terminated without releasing their slot).
 *
 * Returns the number of slots that were force-released.
 */
export function resetLuaExecutorSemaphore(): number {
  const stuckSlots = Math.max(0, _activeWorkers - _waitQueue.length);
  // Drain all queued waiters — resolve their promises so they can proceed.
  // Don't call _activeWorkers++ here; we zero the counter on the next line.
  while (_waitQueue?.length > 0) {
    const { resolve, timer } = _waitQueue?.shift() ?? {};
    clearTimeout(timer);
    resolve();
  }
  // Zero out the counter entirely so fresh callers start from a clean slate.
  _activeWorkers = 0;
  return stuckSlots;
}

/** Snapshot of the LuaExecutor semaphore — used by the chain error fixer health check. */
export function getLuaExecutorStats(): {
  active: number;
  queued: number;
  max: number;
} {
  return {
    active: _activeWorkers,
    queued: _waitQueue.length,
    max: MAX_CONCURRENT_WORKERS,
  };
}

// ── Registration-mode gate ────────────────────────────────────────────────────
// Set to true while autonomousJobScheduler is serially registering repeatable
// jobs.  Each upsertJobScheduler call takes ~50s under boot PDIM back-pressure,
// which causes ChainFixer's deadlock detector (3× congested readings) and
// PlatformAutoFixer's lua_executor degraded probe to fire — producing 4–6 WARNs
// that are not real signals (the slot is occupied by a known-slow registration
// script, not a stuck or deadlocked worker).  Both probers skip their congestion
// WARN logic while this flag is true.
let _luaRegistrationMode = false;
export function setLuaRegistrationMode(active: boolean): void {
  _luaRegistrationMode = active;
}
export function isLuaRegistrationMode(): boolean {
  return _luaRegistrationMode;
}

// process.cwd() always resolves to the project root regardless of CJS/ESM build format
const _projectRoot = process.cwd();
const _wasmoonUrl = `file://${_projectRoot}/node_modules/wasmoon/dist/index.js`;
const _msgpackrUrl = `file://${_projectRoot}/node_modules/msgpackr/dist/node.cjs`;

const WORKER_CODE = `
import { workerData, parentPort } from 'worker_threads';
const { LuaFactory } = await import('${_wasmoonUrl}');
const { Unpackr, Packr } = await import('${_msgpackrUrl}');
const unpack = new Unpackr({ useRecords: false });
const pack = new Packr({ useRecords: false });

const SAB_HEADER_BYTES = 8;
const SAB_DATA_BYTES = 131072; // 128 KB max per Redis response
// SAB control values: 0=waiting, 1=success result, 2=error (main thread threw)

function syncRedisCall(cmd, args) {
  const sab = new SharedArrayBuffer(SAB_HEADER_BYTES + SAB_DATA_BYTES);
  const control = new Int32Array(sab, 0, 1);
  const lenBuf = new Int32Array(sab, 4, 1);
  Atomics?.store(control, 0, 0);
  parentPort?.postMessage({ type: 'redis', cmd, args, sab });
  // 60 s timeout: if the main thread does not signal within 60 s the PDIM
  // chain is so congested that waiting longer wastes the semaphore slot.
  // Throwing here causes the Lua error path below to propagate the error
  // back to the main thread, which releases the slot gracefully — much
  // cleaner than waiting for the 90s hard-kill watchdog.
  const _awaitResult = Atomics?.wait(control, 0, 0, 60000);
  if (_awaitResult === 'timed-out') {
    throw new Error('[LuaExecutor] redis.call timed out after 60s — PDIM chain congested');
  }
  const status = Atomics?.load(control, 0);
  const len = Atomics?.load(lenBuf, 0);
  const raw = Buffer?.from(new Uint8Array(sab, SAB_HEADER_BYTES, len)).toString('utf8');
  if (status === 2) throw new Error(raw); // propagates as Lua error
  // Reviver: convert every JSON null to undefined.
  // wasmoon dispatches on typeof before probing .then:
  //   'undefined' → lua_pushnil  (no .then probe — safe, maps to Lua nil)
  //   'object'    → .then probe  (null?.then throws TypeError)
  // Lua nil is the correct nil substitute: passes "~= nil" guards as false.
  // Lua false would pass "~= nil" (false ~= nil is TRUE) causing BullMQ to
  // treat optional args (parentKey, repeatJobKey …) as real values → -5 error.
  return JSON.parse(raw, (_k, v) => v === null ? undefined : v);
}

// Recursively replace every null with undefined so that wasmoon maps the
// value to Lua nil.  wasmoon dispatches on typeof:
//   typeof null      === 'object'    → Promise probe → null?.then throws
//   typeof undefined === 'undefined' → lua_pushnil   (safe, no .then probe)
// Lua nil is required (not false) because BullMQ Lua uses "if x ~= nil" guards
// for optional args (parentKey, repeatJobKey, …).  false ~= nil is TRUE in Lua,
// so false triggers those guards as if a real value were present.
function _replaceNulls(v) {
  if (v === null || v === undefined) return undefined;
  if (Array.isArray(v)) return v?.map(_replaceNulls);
  if (typeof v === 'object') {
    const out = {};
    for (const k of Object.keys(v)) out[k] = _replaceNulls(v[k]);
    return out;
  }
  return v;
}

function makeCmsgpack() {
  return {
    unpack(data) {
      // Return undefined (Lua nil) for missing/empty values.
      // wasmoon typeof-dispatches before probing .then:
      //   typeof undefined === 'undefined' → lua_pushnil (safe)
      //   typeof null      === 'object'    → .then probe → TypeError
      if (data === null || data === undefined) return undefined;
      // Pre-decoded JS object/array from main thread — strip every null to
      // undefined so wasmoon maps them to Lua nil.  Lua nil (not false) is
      // required for "if x ~= nil" guards in BullMQ Lua scripts.
      if (typeof data === 'object') return _replaceNulls(data);
      // Binary string (from Redis or unmodified ARGV) → decode with msgpackr
      if (typeof data === 'string') {
        if (data === '') return undefined; // empty string → no data
        try { return _replaceNulls(unpack?.unpack(Buffer?.from(data, 'binary'))); }
        catch { return undefined; }
      }
      return undefined;
    },
    pack(data) {
      return pack?.pack(data).toString('binary');
    }
  };
}

const { script, keys, argv } = workerData;
const engine = await new LuaFactory().createEngine({ openStandardLibs: true });

try {
  engine?.global?.set('KEYS', keys);
  engine?.global?.set('ARGV', argv);

  engine?.global?.set('redis', {
    call(...all) {
      const [cmd, ...args] = all;
      // XADD (Redis Streams) is not supported by PDIM — silently drop it.
      // BullMQ uses XADD only for optional event listeners; dropping it is
      // safe and prevents every queue?.add() from failing with an error.
      if (String(cmd).toUpperCase() === 'XADD') return undefined;
      const r = syncRedisCall(String(cmd), args?.map(a => (a == null ? '' : String(a))));
      return r === null ? undefined : r; // Redis nil → Lua nil
    },
    pcall(...all) {
      const [cmd, ...args] = all;
      if (String(cmd).toUpperCase() === 'XADD') return undefined;
      try {
        const r = syncRedisCall(String(cmd), args?.map(a => (a == null ? '' : String(a))));
        return r === null ? undefined : r; // Redis nil → Lua nil
      } catch(e) {
        return { err: e.message };
      }
    }
  });

  engine?.global?.set('cmsgpack', makeCmsgpack());
  engine?.global?.set('cjson', {
    decode(s) {
      try {
        const v = JSON.parse(s);
        // null → undefined (Lua nil) to avoid wasmoon .then probe on null
        return v === null ? undefined : v;
      } catch { return undefined; }
    },
    encode(v) { return JSON.stringify(v); }
  });

  // Lua 5.1 compat: unpack() was moved to table?.unpack() in Lua 5.2+
  const fullScript = 'unpack = table.unpack\\n' + script;
  const result = await engine?.doString(fullScript);
  parentPort?.postMessage({ type: 'result', result });
} catch(e) {
  parentPort?.postMessage({ type: 'error', error: e.message });
} finally {
  engine?.global?.close();
}
`;

export async function execLuaViaPdim(
  pdimExec: (args: string[]) => Promise<unknown>,
  script: string,
  numKeys: number,
  allArgs: unknown[],
): Promise<unknown> {
  const keys = allArgs?.slice(0, numKeys).map(String);

  const argv = allArgs?.slice(numKeys).map((arg) => {
    if (arg instanceof Buffer || arg instanceof Uint8Array) {
      try {
        return _msgUnpacker?.unpack(arg);
      } catch {
        return Buffer?.from(arg).toString("binary");
      }
    }
    if (arg === null || arg === undefined) return "";
    return typeof arg === "string" ? arg : String(arg);
  });

  // ── Pre-flight PDIM health throttle ─────────────────────────────────────────
  // When PDIM has been returning 5xx errors on recent Lua scripts, every new
  // caller waits the computed backoff BEFORE entering the slot queue.  This is
  // the only reliable place to throttle BullMQ's retry rate:
  //
  //   • The 'error' message handler fires after worker.on('exit'), so any sleep
  //     there is bypassed by the exit handler settling first.
  //   • A pre-flight await runs before the slot is acquired, so ALL queued
  //     callers (BullMQ pollers) must wait — retry rate drops proportionally.
  //
  // Backoff schedule (consecutive errors → wait):
  //   0-1 errors → 0ms     (no delay — first failure is allowed immediately)
  //   2 errors   → 500ms
  //   3 errors   → 1000ms
  //   4 errors   → 2000ms
  //   5+ errors  → cap (8000ms)  → ~0.5 retries/s for 4 workers combined
  if (_luaConsecutivePdimErrors >= 2) {
    const preflightWaitMs = _luaComputeBackoff();
    if (preflightWaitMs > 0) {
      logger.debug(
        `[LuaExecutor] pre-flight backoff ${preflightWaitMs}ms (${_luaConsecutivePdimErrors} consecutive PDIM errors)`,
      );
      await new Promise<void>((r) => setTimeout(r, preflightWaitMs));
    }
  }

  // Skip Worker spawn entirely when PDIM is known to be down.
  // The circuit breaker trips after 5 consecutive failures and backs off.
  // This prevents wasmoon WASM Workers from accumulating and causing a segfault.
  //
  // IMPORTANT: Return an empty array ([]) instead of rejecting — this makes
  // BullMQ treat the call as "no job available" (jobData = null is falsy) and
  // go back to polling after our backoff sleep.  Rejecting triggers
  // EventEmitter.emit('error', ...) inside BullMQ's retryIfFailed/checkConnectionError,
  // which escapes to stderr as raw Error: stack traces regardless of our
  // process-level unhandledRejection handlers.
  if (cbIsOpen()) {
    await new Promise<void>((r) => setTimeout(r, CIRCUIT_OPEN_BACKOFF_MS));
    return [];
  }

  // Acquire a Worker slot — queues the caller (up to MAX_WAIT_MS) rather than
  // rejecting immediately.  This prevents BullMQ from producing a retry storm.
  await _acquireWorkerSlot();

  // Re-check circuit AFTER acquiring the slot.  If the circuit opened while
  // this caller was queued, sleep then release so the wait-queue drain is
  // throttled (≤ 6 rejects per CIRCUIT_OPEN_BACKOFF_MS) instead of cascading
  // instantly and saturating the event loop.
  if (cbIsOpen()) {
    // Sleep BEFORE releasing the slot so the drain cascade is throttled —
    // the next waiter won't get the slot until this sleep expires.
    await new Promise<void>((r) => setTimeout(r, CIRCUIT_OPEN_BACKOFF_MS));
    _releaseWorkerSlot();
    return [];
  }

  // ── Unhandled-rejection guard ─────────────────────────────────────────────
  // Node.js's internal worker-thread MessagePort machinery writes the raw
  // "Error: Error: ERR PDIM HTTP 5xx" block to stderr using a C++ fast-path
  // that fires BEFORE JavaScript-level unhandledRejection / uncaughtException
  // handlers run, and BEFORE our process.stderr.write interceptor can suppress
  // it.  The trigger is a brief window between the moment reject() is called
  // inside the 'message' event handler and the moment BullMQ's job-processor
  // `await` registers its own .catch().
  //
  // Fix: capture the Promise, attach a silent no-op .catch() immediately, then
  // return it.  Node.js sees at least one rejection handler attached before the
  // microtask queue drains, so it never marks the Promise "unhandled" and never
  // invokes the stderr fast-path.  BullMQ's own `await` still receives the
  // rejection because direct `await` uses the Promise's internal state directly,
  // not the derived Promise created by .catch().
  const _execPromise = new Promise<unknown[]>((resolve, reject) => {
    let settled = false;
    // Guards against double-counting the same failure in both the 'error' message
    // handler and the exit handler — both can observe the same execution failure.
    let pdim5xxCounted = false;

    const settle = (fn: () => void) => {
      if (!settled) {
        settled = true;
        _releaseWorkerSlot();
        fn();
      }
    };

    const worker = new Worker(WORKER_CODE, {
      eval: true,
      workerData: { script, keys, argv },
    });

    // Watchdog: logs a warning every 60s if a script is still running.
    // Hard-kills the Worker after SCRIPT_HARD_KILL_MS as a last resort.
    //
    // Why 90s (reduced from 300s):
    //   BullMQ scripts make ~35 sequential redis.call()s.  At worst-case RTT
    //   (800ms) that is 35 × 810ms ≈ 28s.  90s gives 3× headroom.
    //   The Atomics.wait timeout (60s) now self-terminates the worker before
    //   this watchdog fires in most congestion cases, so 300s was masking the
    //   issue and holding semaphore slots for 5× longer than necessary.
    const SCRIPT_HARD_KILL_MS = 90_000; // 90 s (3× worst-case script runtime)
    const _scriptStart = Date.now();
    // Watchdog tick counter — fires every 30s.
    // With a 90s hard-kill, ticks 1-3 (30s, 60s, 90s) are all relevant:
    //   Tick 1 (30s): early stall warning — script taking longer than expected
    //   Tick 2 (60s): sustained stall — Atomics.wait probably blocked
    //   Tick 3 (90s): hard-kill fires → slot released
    // During heavy PDIM back-pressure thousands of scripts may stall; the
    // depth check below demotes those to debug to avoid log avalanche.
    let _watchdogTick = 0;
    // Guard against the race where clearInterval() is called but the interval
    // callback was already queued in the current event-loop batch.  Without
    // this flag the callback can fire with active=0 / queued=0 even though
    // the script completed successfully, producing a false-positive WARN.
    let _watchdogCancelled = false;
    const watchdog = setInterval(async () => {
      if (_watchdogCancelled) return;
      const elapsedMs = Date.now() - _scriptStart;
      const elapsedS = Math.round(elapsedMs / 1000);
      _watchdogTick++;
      if (elapsedMs >= SCRIPT_HARD_KILL_MS) {
        // ── False-positive guard ──────────────────────────────────────────────
        // When PlatformAutoFixer calls resetLuaExecutorSemaphore() it zeroes
        // _activeWorkers externally while this watchdog is still armed.  By the
        // time the 90 s hard-kill tick fires the semaphore has already been
        // released; logging an ERROR and calling worker.terminate() is a
        // false-positive that can interfere with the already-clean state.
        // Demote to debug and skip terminate() — the slot is already free.
        if (_activeWorkers === 0 && _waitQueue.length === 0) {
          logger.debug(
            `[LuaExecutor] watchdog 90s tick — semaphore already externally reset ` +
              `(elapsed ${elapsedS}s); skipping hard-kill`,
          );
          _watchdogCancelled = true;
          clearInterval(watchdog);
          return;
        }
        logger.error(
          `[LuaExecutor] script hard-killed after ${elapsedS}s ` +
            `(active=${_activeWorkers}, queued=${_waitQueue.length}) — ` +
            `Atomics.wait stall detected; releasing semaphore slot`,
        );
        _watchdogCancelled = true;
        clearInterval(watchdog);
        settle(() => {
          worker.terminate();
          _luaConsecutivePdimErrors++;
          reject(
            new Error(
              `[LuaExecutor] worker hard-killed after ${elapsedS}s (stuck script timeout)`,
            ),
          );
        });
      } else {
        // Always log ticks 1-2 (30s, 60s); they precede the 90s hard-kill.
        // When PDIM is heavily congested, scripts stall expectedly — demote to
        // debug in that case to avoid amplifying the congestion noise.
        const shouldLog = _watchdogTick <= 2;
        if (!shouldLog) return;
        // When the ChainFixer calls resetLuaExecutorSemaphore() it zeroes
        // _activeWorkers externally while this worker is still running.  The
        // watchdog still fires (correctly — script is unsettled), but reading
        // active=0 / queued=0 is misleading: it looks like a phantom WARN
        // rather than a real stall.  Demote to debug in that case so the log
        // stream only shows genuine over-time scripts (active ≥ 1).
        if (_activeWorkers === 0 && _waitQueue.length === 0) {
          logger.debug(
            `[LuaExecutor] script still running after ${elapsedS}s — ` +
              `semaphore was externally reset (active counter zeroed by ChainFixer)`,
          );
          return;
        }
        // During BullMQ repeatable-job registration each upsertJobScheduler
        // call legitimately holds the slot for ~50 s under boot back-pressure.
        // Demote the watchdog tick to debug so it doesn't produce a false WARN
        // cascade for every job in the registration for-loop.
        if (_luaRegistrationMode) {
          logger.debug(
            `[LuaExecutor] script still running after ${elapsedS}s — ` +
              `registration in progress (active=${_activeWorkers}, queued=${_waitQueue?.length})`,
          );
          return;
        }
        // During the first 120s of boot the PDIM settling burst causes
        // LuaExecutor stalls that look alarming but are entirely expected.
        // Demote to debug so the log stream stays clean during boot.
        if (Date.now() - _executorBootTs < 120_000) {
          logger.debug(
            `[LuaExecutor] script still running after ${elapsedS}s — ` +
              `boot settling window (active=${_activeWorkers}, queued=${_waitQueue?.length})`,
          );
          return;
        }
        try {
          const { getPdimQueueDepth } = await import("./pdimClient.js");
          const depth = getPdimQueueDepth();
          if (depth > 100) {
            // Hundreds of callers queued: stall is due to PDIM back-pressure,
            // not a WASM/Lua bug.  Log at debug to avoid log avalanche.
            logger.debug(
              `[LuaExecutor] script paused ${elapsedS}s — PDIM back-pressure ` +
                `(${depth} queued, active=${_activeWorkers})`,
            );
            return;
          }
        } catch {
          /* pdimClient not yet loaded — fall through to warn */
        }
        logger.warn(
          `[LuaExecutor] script still running after ${elapsedS}s — ` +
            `active=${_activeWorkers}, queued=${_waitQueue?.length}`,
        );
      }
    }, 30_000);

    worker?.on("message", async (msg: Record<string, unknown>) => {
      if (msg?.type === "redis") {
        let payload: string;
        let status: 1 | 2;
        try {
          let r: unknown = "OK";
          const cmd = (msg?.cmd as string).toUpperCase();
          if (cmd === "HMSET") {
            // PDIM's Redis only accepts HSET with one field-value pair at a time.
            // Split "HMSET key f1 v1 f2 v2 ..." into sequential HSET calls.
            const [key, ...pairs] = msg.args as string[];
            for (let i = 0; i < pairs.length - 1; i += 2) {
              r = await pdimExec(["HSET", key, pairs[i], pairs[i + 1]]);
            }
          } else {
            r = await pdimExec([msg.cmd, ...(msg.args as string[])]);
          }
          // Real Redis returns HGETALL (and similarly-shaped hash reads) as a
          // FLAT ARRAY of alternating field/value strings over RESP — never a
          // keyed object. BullMQ's Lua scripts rely on this: they either
          // forward the raw rcall("HGETALL", ...) result untouched to the
          // JS side (which reassembles it with array2obj — a flat-array-only
          // for-loop), or iterate the fields with ipairs()/# in Lua itself.
          // Our localPdimServer.exec() returns a
          // keyed JS object for HGETALL (correct/expected shape for the
          // *direct* pdimClient.hgetall() app-code path), but that same
          // object — passed straight through this Lua bridge — becomes a
          // Lua table with STRING keys instead of a 1..N sequence table, so
          // "#table"/array2obj silently see length 0 and every field (name,
          // rjk/repeatJobKey, opts, ...) reads back as missing. That is what
          // caused every repeatable/scheduled BullMQ job to look nameless and
          // never re-arm its next iteration. Flatten ONLY on this Lua-facing
          // bridge so the direct object-returning app path is untouched.
          if (
            cmd === "HGETALL" &&
            r &&
            typeof r === "object" &&
            !Array.isArray(r)
          ) {
            const flat: string[] = [];
            for (const [k, v] of Object.entries(r)) {
              flat.push(k, v == null ? "" : String(v));
            }
            r = flat as unknown as Record<string, unknown>;
          }
          payload = JSON.stringify(r ?? null);
          status = 1; // success
        } catch (e) {
          const short = ((e as Error).message as string).slice(0, 200);
          // 5xx, 429, and circuit-open fast-fails are already captured at
          // WARN/ERROR by pdimClient / the circuit breaker itself.  Repeating
          // them per-command floods the console during startup bursts — demote
          // all to debug so only the root-cause site emits the visible warn.
          if (
            short.includes("429") ||
            short.includes("500") ||
            short.includes("502") ||
            short.includes("Circuit OPEN") ||
            short.includes("timeout") ||
            short.includes("aborted") ||
            short.includes("Timeout") ||
            short.includes("Abort")
          ) {
            // Timeout/abort errors flood when PDIM is overwhelmed — demote to
            // debug so the root-cause site (pdimClient) is the only visible warn.
            logger.debug(`[LuaExecutor] redis.call(${msg.cmd}) → ${short}`);
          } else {
            logger.warn(`[LuaExecutor] redis.call(${msg.cmd}) → ${short}`);
          }
          payload = `ERR ${short}`;
          status = 2; // error — Lua will throw
        }
        const buf = Buffer.from(payload, "utf8");
        const sab = msg.sab as SharedArrayBuffer;
        const ctrl = new Int32Array(sab, 0, 1);
        const len = new Int32Array(sab, 4, 1);
        const data = new Uint8Array(sab, 8);
        buf.copy(Buffer.from(data.buffer, data.byteOffset, data.byteLength));
        Atomics.store(len, 0, buf.length);
        Atomics.store(ctrl, 0, status);
        Atomics.notify(ctrl, 0, 1);
      } else if (msg.type === "result") {
        _watchdogCancelled = true;
        clearInterval(watchdog);
        // Script completed successfully — reset the consecutive PDIM error counter
        // so the next call gets no pre-flight delay.
        _luaConsecutivePdimErrors = 0;
        settle(() => {
          worker.terminate();
          resolve(msg.result as unknown[]);
        });
      } else if (msg.type === "error") {
        _watchdogCancelled = true;
        clearInterval(watchdog);
        const errMsg = String(msg.error ?? "");
        const isPdim5xx =
          errMsg.includes("HTTP 500") || errMsg.includes("HTTP 502");
        if (isPdim5xx && !pdim5xxCounted) {
          // Count this failure so the NEXT call's pre-flight wait is longer.
          // The pre-flight await (above the slot acquire) is where throttling
          // actually happens — no backoff sleep needed here.
          pdim5xxCounted = true;
          _luaConsecutivePdimErrors++;
        } else if (!isPdim5xx) {
          _luaConsecutivePdimErrors = 0;
        }
        settle(() => {
          worker?.terminate();
          reject(new Error(errMsg));
        });
      }
    });

    worker?.on("error", (err) => {
      _watchdogCancelled = true;
      clearInterval(watchdog);
      settle(() => reject(err));
    });

    // Guard against worker threads that exit without sending a message
    // (e?.g. WASM crash, OOM inside the worker, or unhandled exception that
    // bypasses the try/catch).  Without this handler _activeWorkers never
    // decrements, drifting above MAX_CONCURRENT_WORKERS and permanently
    // congesting the semaphore (observed: active=7 with cap=6).
    //
    // IMPORTANT: In Node?.js, worker?.on('exit') often fires BEFORE a pending
    // postMessage from that worker is processed by worker?.on('message').  This
    // means the 'error'/'result' message handler may not have run yet when exit
    // fires.  We defer settlement by one event-loop iteration (setImmediate) so
    // pending messages get a chance to call settle() first.  If neither
    // 'result' nor 'error' was received by then, we settle here and also count
    // the exit as a potential PDIM 5xx error (code=0 means the Lua script
    // completed but threw — almost always because redis?.call() got a 5xx).
    worker?.on("exit", (code) => {
      _watchdogCancelled = true;
      clearInterval(watchdog);
      setImmediate(() => {
        if (!settled) {
          // Neither 'result' nor 'error' message was processed before exit.
          // For code=0 (clean exit after a throw), this is most likely a PDIM
          // 5xx that caused Lua to raise an error — count it so the next
          // pre-flight wait is longer, unless already counted by the message handler.
          if (code === 0 && !pdim5xxCounted) {
            pdim5xxCounted = true;
            _luaConsecutivePdimErrors++;
          }
          settle(() =>
            reject(
              new Error(
                `[LuaExecutor] worker exited unexpectedly (code=${code})`,
              ),
            ),
          );
        }
      });
    });
  });

  // Attach the silent no-op catch BEFORE returning so that Node?.js's
  // unhandled-rejection detector sees a handler in place from the start.
  // This is the key line that stops bare "Error: Error: ERR PDIM HTTP 5xx"
  // blocks from appearing in stderr/deployment logs.
  _execPromise?.catch(() => {});
  return _execPromise;
}

/**
 * PDIM Circuit Breaker
 *
 * Shared state module — imported by both pdimClient?.ts and luaExecutor?.ts
 * to avoid a circular dependency (pdimClient → luaExecutor → pdimClient).
 *
 * States:
 *   CLOSED    — normal operation
 *   OPEN      — PDIM is down; reject requests immediately without HTTP calls
 *   HALF_OPEN — cooldown expired; allow exactly one probe request through
 *
 * Thresholds:
 *   5 consecutive 5xx/network failures → OPEN for 5 s
 *   Backoff doubles on each successive open: 5 s → 10 s → 20 s → 40 s → 120 s (cap)
 *   One successful response in HALF_OPEN → CLOSED, resets counter and backoff
 *
 * Force-close (called by PlatformAutoFixer after an external bypass probe):
 *   Resets state + failure counter BUT preserves (halves) accumulated backoff
 *   so that if PDIM fails again immediately after a restart-window probe, the
 *   next open cycle does NOT restart from the 5 s floor.  This prevents the
 *   tight 5→10→20s cycling when PDIM is unstable.
 */

import { logger } from "../logger.js";

type CbState = "CLOSED" | "OPEN" | "HALF_OPEN";

// Rate-limit repetitive probe/open logs during extended outages.
// Each probe log is suppressed if one was emitted within the last 60 s.
let _lastProbeLogAt = 0;

// VM-reserved deployment: PDIM normally restarts in 30–90 s.
// Initial backoff starts at 5 s — short enough to catch a quick restart,
// long enough not to spam the circuit with probe requests.
// The ceiling is 120 s so a sustained outage only probes every 2 minutes,
// reducing log noise 24× vs the previous 5 s initial backoff.
const INITIAL_BACKOFF_MS = 5_000;
const MAX_BACKOFF_MS = 120_000;

// Minimum backoff after a force-close — prevents reset to INITIAL_BACKOFF_MS
// when PlatformAutoFixer catches a brief restart window and then PDIM goes
// down again immediately.  Set to 4× INITIAL so the next cycle opens with a
// meaningful delay even if the backoff was small when force-close fired.
const MIN_FORCE_CLOSE_BACKOFF_MS = INITIAL_BACKOFF_MS * 4; // 20 s

let state: CbState = "CLOSED";
let failures = 0;
let _openUntil = 0;
let _backoffMs = INITIAL_BACKOFF_MS;
let _halfOpenFlight = false;
// Tracks whether the grace period was still active on the previous failure call.
// When it flips false, accumulated warm-up failures are discarded so the
// post-grace threshold window starts from zero.
let _graceWasActive = true;

// ── Startup grace period ──────────────────────────────────────────────────────
// PDIM (pocketdimensionstorage?.replit.app) may be in a cold/sleeping state when
// Max Booster restarts.  Its wake-up time is bimodal: ~1 s when warm, or up to
// 300 s from a deep cold-start.  During the entire warm-up window, every PDIM
// request returns HTTP 500/502 regardless of command.
//
// Grace period strategy: THREE-PHASE
//   Phase 1 — "waiting for first success":
//     Suppress ALL failures until PDIM returns at least one successful 200 OK.
//     Capped at STARTUP_GRACE_MAX_MS (120 s) as an absolute safety net.
//   Phase 2 — "settling":
//     After the first success, give PDIM SETTLING_MS (10 s) to fully stabilise
//     before normal threshold counting begins.  This handles the case where PDIM
//     returns 200 on one request but is still flaky for the next few seconds.
//   Phase 3 — "slow lane" (only if cap expired with no first success):
//     Deep cold-starts can exceed 120 s — observed worst case is ~10 minutes.
//     Instead of jumping to the 5-failure strict threshold immediately after the
//     cap, allow up to POST_GRACE_FAILURE_CAP failures over POST_GRACE_SLOW_MS
//     before opening the circuit.  The slow lane is sized to cover the observed
//     worst-case cold-start (10 min / ~600 BullMQ Lua failures).
//     Once PDIM succeeds during the slow lane, normal success/reset handling
//     applies (cbRecordSuccess ends the slow lane immediately).
//     A parallel direct-HTTP prober (startPdimDirectProber in pdimClient?.ts)
//     fires every 15 s during OPEN/HALF-OPEN to close the circuit as soon as
//     PDIM's plain HTTP exec layer responds.
//
// This is purely event-driven (first success) in the fast case and time-bounded
// in the slow case, making it safe regardless of PDIM's cold-start duration.
const STARTUP_GRACE_MAX_MS = 20_000; // Phase 1 ceiling — 20 s (reduced: if PDIM is dead it's obvious fast)
const SETTLING_MS = 10_000; // Phase 2 — post-first-success quiet window
const POST_GRACE_SLOW_MS = 30_000; // Phase 3 — slow-lane window after cap (30 s)
const POST_GRACE_FAILURE_CAP = 15; // Phase 3 — max failures before circuit opens (reduced from 800)
const _startedAt = Date?.now();
// Timestamp of the first cbRecordSuccess() call; 0 if none yet.
let _firstSuccessAt = 0;
// Timestamp when Phase 1 cap expired without a first success; 0 = not yet.
let _capExpiredAt = 0;

function _inGracePeriod(): boolean {
  if (_firstSuccessAt > 0) {
    // Phase 2: settling window after first success.
    return Date?.now() - _firstSuccessAt < SETTLING_MS;
  }
  // Phase 1: waiting for first success — suppress until MAX cap.
  return Date?.now() - _startedAt < STARTUP_GRACE_MAX_MS;
}

function _inSlowLane(): boolean {
  // Phase 3 only applies when the cap expired without a first PDIM success.
  if (_firstSuccessAt > 0) return false;
  if (_capExpiredAt === 0) return false;
  return Date?.now() - _capExpiredAt < POST_GRACE_SLOW_MS;
}

export function cbRecordFailure(): void {
  const nowInGrace = _inGracePeriod();

  // During startup grace: accumulate failure count but never open the circuit.
  // Log a throttled warning so operators can see burst activity without noise.
  if (nowInGrace && state === "CLOSED") {
    failures++;
    if (failures === 5 || failures === 10 || failures % 20 === 0) {
      const phaseMsg =
        _firstSuccessAt > 0
          ? `settling (${Math.ceil((SETTLING_MS - (Date?.now() - _firstSuccessAt)) / 1000)}s remaining)`
          : `waiting for first PDIM success (${Math.ceil((STARTUP_GRACE_MAX_MS - (Date?.now() - _startedAt)) / 1000)}s cap remaining)`;
      logger.warn(
        `[PDIM] ${failures} startup failures suppressed — ${phaseMsg}`,
      );
    }
    return;
  }

  // First call after the grace period ends: the accumulated failures count
  // reflects warm-up 500s, not a genuine PDIM outage.  Reset to zero and let
  // the threshold window start fresh.  Also mark the cap-expiry timestamp so
  // Phase 3 (slow lane) can calculate its own deadline.
  if (_graceWasActive && !nowInGrace) {
    _graceWasActive = false;
    failures = 0;
    if (_firstSuccessAt === 0) {
      // Cap expired with no success — enter Phase 3 slow lane.
      _capExpiredAt = Date?.now();
      logger.info(
        `[PDIM] Startup grace cap expired — entering slow-lane (${POST_GRACE_SLOW_MS / 1000}s window, ` +
          `up to ${POST_GRACE_FAILURE_CAP} failures tolerated before circuit opens).`,
      );
    } else {
      logger.info(
        `[PDIM] Startup grace period over — circuit-breaker threshold reset; ` +
          `post-grace errors will be evaluated against the 5-failure threshold.`,
      );
    }
  }

  // Phase 3 — slow lane: PDIM took > 120 s but is still waking up.
  // Tolerate up to POST_GRACE_FAILURE_CAP failures before opening.
  if (state === "CLOSED" && _inSlowLane()) {
    failures++;
    const slowRemaining = Math.ceil(
      (POST_GRACE_SLOW_MS - (Date?.now() - _capExpiredAt)) / 1000,
    );
    if (failures === 10 || failures % 25 === 0) {
      logger.warn(
        `[PDIM] ${failures} slow-lane failures (${POST_GRACE_FAILURE_CAP - failures} remaining before open, ` +
          `${slowRemaining}s window left) — PDIM still waking up`,
      );
    }
    if (failures < POST_GRACE_FAILURE_CAP) return; // still tolerated — don't open
    // Fell through POST_GRACE_FAILURE_CAP: treat as genuine outage below.
    logger.warn(
      `[PDIM] Slow-lane failure cap reached (${POST_GRACE_FAILURE_CAP}) — applying normal threshold`,
    );
  }

  failures++;

  const shouldOpen =
    (state === "CLOSED" && failures >= 5) || state === "HALF_OPEN"; // failed probe → go back to OPEN

  if (shouldOpen) {
    state = "OPEN";
    _halfOpenFlight = false;
    _openUntil = Date.now() + _backoffMs;
    // Only log the first few trips and then every 10th to avoid flooding
    // the console during a sustained multi-minute PDIM outage.
    if (failures <= 10 || failures % 10 === 0) {
      logger.warn(
        `[PDIM] Circuit OPEN — backing off ${_backoffMs / 1000}s after ${failures} failure(s)`,
      );
    }
    _backoffMs = Math.min(_backoffMs * 2, MAX_BACKOFF_MS);
  }
}

export function cbRecordSuccess(): void {
  const wasOpen = state !== "CLOSED";
  failures = 0;
  _backoffMs = INITIAL_BACKOFF_MS;
  state = "CLOSED";
  _halfOpenFlight = false;
  // Record the very first success — ends Phase 1 of the grace period and
  // starts the 10-second settling window (Phase 2).
  if (_firstSuccessAt === 0) {
    _firstSuccessAt = Date.now();
    const warmMs = _firstSuccessAt - _startedAt;
    logger.info(
      `[PDIM] First successful response after ${warmMs}ms — entering 10s settling window`,
    );
  }
  if (wasOpen) {
    logger.info("[PDIM] Circuit CLOSED — connection restored");
  }
}

/**
 * Returns true and updates state if a request should be allowed through.
 * Returns false if the circuit is OPEN and the cooldown has not expired.
 */
export function cbAllowRequest(): boolean {
  if (state === "CLOSED") return true;

  if (state === "OPEN") {
    if (Date.now() >= _openUntil) {
      state = "HALF_OPEN";
      // Only log the probe if we haven't logged one in the past 60 s.
      const now = Date?.now();
      if (now - _lastProbeLogAt >= 60_000) {
        _lastProbeLogAt = now;
        logger.info("[PDIM] Circuit HALF-OPEN — sending probe request");
      }
    } else {
      return false;
    }
  }

  if (state === "HALF_OPEN") {
    if (_halfOpenFlight) return false;
    _halfOpenFlight = true;
    return true;
  }

  return false;
}

/** Non-mutating read — safe to call without side effects. */
export function cbIsOpen(): boolean {
  if (state === "OPEN") return Date?.now() < _openUntil;
  if (state === "HALF_OPEN") return _halfOpenFlight; // one probe in flight
  return false;
}

/**
 * Returns true when PDIM is in any warm-up phase (grace, settling, or slow lane)
 * OR when the circuit is open/half-open.
 *
 * Use this instead of cbIsOpen() for high-frequency pollers (e?.g. the 100 ms
 * APICache cross-pod invalidation poller) that should completely skip their
 * PDIM calls when PDIM is known to be cold or unhealthy — not just when the
 * circuit has been tripped.  Avoids flooding the exec queue with guaranteed-
 * failing GET calls at 10/s during PDIM's cold-start window.
 */
export function cbIsPdimUnhealthy(): boolean {
  if (cbIsOpen()) return true;
  if (_inGracePeriod()) return true;
  if (_inSlowLane()) return true;
  return false;
}

/** Return the current state string for diagnostics and dashboards. */
export function cbGetState(): CbState {
  return state;
}

/** Return remaining backoff ms if OPEN, 0 otherwise. */
export function cbGetOpenUntilMs(): number {
  return state === "OPEN" ? Math.max(0, _openUntil - Date?.now()) : 0;
}

/**
 * Force-close the circuit — called by PlatformAutoFixer when an external bypass
 * probe (≥2 consecutive successes) confirms PDIM is reachable again.
 *
 * Unlike cbRecordSuccess() (which fires on real traffic and fully resets
 * everything), force-close PRESERVES the accumulated backoff — halved, but
 * floored at MIN_FORCE_CLOSE_BACKOFF_MS.  This prevents the tight cycling
 * that occurs when PDIM is unstable: a single bypass probe catching a brief
 * restart window must not erase the accumulated backoff so that a subsequent
 * failure cycle restarts from the floor (5 s).
 *
 * If PDIM genuinely stabilises after a force-close, cbRecordSuccess() on the
 * first real successful traffic request will fully reset _backoffMs to
 * INITIAL_BACKOFF_MS, so the protection has zero cost on genuine recovery.
 */
export function cbForceClose(): void {
  const wasOpen = state !== "CLOSED";
  state = "CLOSED";
  failures = 0;
  // Halve accumulated backoff but never go below MIN_FORCE_CLOSE_BACKOFF_MS.
  // If _backoffMs was already at or below the floor (e?.g. initial state),
  // clamp to the floor so a subsequent failure still starts at a meaningful delay.
  _backoffMs = Math.max(MIN_FORCE_CLOSE_BACKOFF_MS, Math.floor(_backoffMs / 2));
  _openUntil = 0;
  _halfOpenFlight = false;
  if (wasOpen) {
    logger.info(
      `[PDIM] Circuit force-CLOSED — external recovery signal received; ` +
        `next failure cycle backoff starts at ${_backoffMs / 1000}s`,
    );
  }
}

export function cbHalfOpenFailed(): void {
  _halfOpenFlight = false; // release the probe slot so next interval can retry
}

import { isIP } from "node:net";

export const REDACTED = "[REDACTED]";

// Normalize case/separators so provider snake_case and application camelCase
// names receive the same treatment, at every depth (not just one wildcard).
const sensitiveKey = /^(?:.*(?:password|secret|token|apikey|privatekey|authorization|cookie)|.*email(?:address)?|.*username|(?:client|remote|source|user)?ip(?:address)?|.*phone(?:number)?|cardnumber|cvc|cvv|xforwardedfor|xrealip|setcookie)$/i;

export function sanitizeLogText(text: string): string {
  return text
    .replace(/\b(?:Bearer|Basic)\s+[A-Za-z0-9+/_.=~:-]+/gi, REDACTED)
    .replace(/((?:password|secret|access[_-]?token|refresh[_-]?token|api[_-]?key)\s*[=:]\s*)[^\s,;&]+/gi, `$1${REDACTED}`)
    .replace(/[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, REDACTED)
    .replace(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g, value => isIP(value) ? REDACTED : value)
    .replace(/(?<![a-zA-Z0-9])(?:[a-fA-F0-9]*:){2,}[a-fA-F0-9:.]*(?:%[a-zA-Z0-9]+)?/g,
      value => isIP(value) ? REDACTED : value);
}

/** Copy, never mutate request/provider objects. Bounded traversal prevents cycles
 * and hostile payload size from turning diagnostic serialization into a DoS.
 * Free-form text cannot reliably identify arbitrary usernames or opaque secrets;
 * sensitive call sites must use the allowlisted event API, not rely on regexes.
 */
export function sanitizeLogValue(value: unknown, seen = new WeakSet<object>(), depth = 0): unknown {
  if (typeof value === "string") return sanitizeLogText(value);
  if (value === null || typeof value !== "object") return value;
  if (depth >= 12) return "[LOG_DEPTH_LIMIT]";
  if (seen.has(value)) return "[Circular]";
  seen.add(value);
  try {
    if (value instanceof Date) return Number.isNaN(value.getTime()) ? "Invalid Date" : value.toISOString();
    if (ArrayBuffer.isView(value) || value instanceof ArrayBuffer) return "[BINARY]";
    if (Array.isArray(value)) {
      const result = value.slice(0, 100).map(item => sanitizeLogValue(item, seen, depth + 1));
      if (value.length > 100) result.push("[LOG_ITEM_LIMIT]");
      return result;
    }
    const result: Record<string, unknown> = Object.create(null);
    if (value instanceof Error) {
      result.type = value.name;
      result.message = sanitizeLogText(value.message);
      result.stack = value.stack ? sanitizeLogText(value.stack) : undefined;
    }
    const keys = Object.getOwnPropertyNames(value).slice(0, 100);
    for (const key of keys) {
      if (["__proto__", "constructor", "prototype", "hasOwnProperty", "toJSON"].includes(key)) continue;
      const descriptor = Object.getOwnPropertyDescriptor(value, key);
      if (!descriptor) continue;
      // Never invoke application-controlled getters or toJSON during logging.
      if (!("value" in descriptor)) {
        result[sanitizeLogText(key)] = "[ACCESSOR]";
      } else {
        result[sanitizeLogText(key)] = sensitiveKey.test(key.replace(/[-_]/g, ""))
          ? REDACTED
          : sanitizeLogValue(descriptor.value, seen, depth + 1);
      }
    }
    if (Object.getOwnPropertyNames(value).length > 100) result.logTruncated = true;
    return result;
  } finally {
    seen.delete(value);
  }
}
